INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34973, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个人或事物区别于其他人或事物的称呼。", "primary_collocate": null, "pronunciation": "míng zi", "ipa": "miŋ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "这家店的名字很好记。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌的名字是什么？", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这个城市的名字吗？", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花的名字我不知道。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书的名字写在第一页上。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给小狗起了一个名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河的名字很特别。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请写下这个游戏的名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了那部电影的名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山的名字叫什么？", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人或事物的称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f82c8ae-82ab-4595-b449-235c22ee33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名字", "is_correct": true, "explanation": "名字：指店的称呼，与“很好记”搭配，是正确答案。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是气味和滋味，不是可以“记”的称呼。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很好记”只说名称、号码一类，不能用于身高。"}, {"text": "芳名", "is_correct": false, "explanation": "语域：芳名是敬称，用来问人的姓名，用于店名不合语域。"}], "explanations": {"名字": "名字：指店的称呼，与“很好记”搭配，是正确答案。", "味道": "语义：味道是气味和滋味，不是可以“记”的称呼。", "身高": "搭配：“很好记”只说名称、号码一类，不能用于身高。", "芳名": "语域：芳名是敬称，用来问人的姓名，用于店名不合语域。"}, "sentence_index": 0, "correct_answer": "名字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试拿了第一名字，大家都很惊讶。", "explanation": "这里应该用〈名次〉。名字指称呼，表示排在第几位要说名次，不能说“第一名字”。"}, {"text": "他把名字递给我，上面印着公司电话。", "explanation": "这里应该用〈名片〉。递给别人、上面印有电话的是名片，名字只是称呼，不能这样递送。"}, {"text": "学校只分给我们班一个名字，我们都很想去。", "explanation": "这里应该用〈名额〉。学校分配的是名额，名字不能分配，这里应该说“一个名额”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名字", "is_correct": true, "explanation": "名字：指河的称呼，与“很特别”搭配，是正确答案。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重只用于人或动物，河没有体重。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育的程度，只用于人，河不适用。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是工作得到的报酬，只用于人，河没有工资。"}], "explanations": {"名字": "名字：指河的称呼，与“很特别”搭配，是正确答案。", "体重": "语义：体重只用于人或动物，河没有体重。", "学历": "语义：学历指受教育的程度，只用于人，河不适用。", "工资": "语义：工资是工作得到的报酬，只用于人，河没有工资。"}, "sentence_index": 6, "correct_answer": "名字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被授予了“优秀教师”的名字，大家都很敬佩。", "explanation": "这里应该用〈称号〉。被授予的是称号，名字是人的本名，不能被授予。"}, {"text": "他获得了“最佳员工”的名字，并写进了简历。", "explanation": "这里应该用〈头衔〉。获得的是头衔，名字是称呼，不能说获得名字。"}, {"text": "他的名字重六十公斤。", "explanation": "这里应该用〈体重〉。〈名字〉是称呼，没有重量，不能说“名字重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给这只猫取了一本好听的名字。", "corrected_sentence": "他给这只猫取了一个好听的名字。", "error_description": "量词错误：名字的量词应为“个”，“本”用于书籍，不能用于名字。错误形式为“一本名字”，正确形式为“一个名字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她给小鸟叫了一个名字。", "corrected_sentence": "她给小鸟起了一个名字。", "error_description": "搭配错误：给……取名要说“起名字”，不能说“叫了一个名字”。错误形式为“叫了一个名字”，正确形式为“起了一个名字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
