INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来玩的东西，比如小熊、小汽车。", "primary_collocate": null, "pronunciation": "wán jù", "ipa": "wan˧˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟有很多玩具。", "target_word": "玩具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具是爸爸送我的。", "target_word": "玩具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子正在地上玩玩具。", "target_word": "玩具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给女儿买了一个新玩具。", "target_word": "玩具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具太大了，放不进包里。", "target_word": "玩具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把玩具收到箱子里了。", "target_word": "玩具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店里的玩具又好看又便宜。", "target_word": "玩具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗最喜欢咬那个旧玩具。", "target_word": "玩具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩完玩具以后，要放回原来的地方。", "target_word": "玩具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过生日时，他收到了一件很大的玩具。", "target_word": "玩具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "件", "label": "量词"}, {"form": "玩具店", "label": "复合词"}, {"form": "玩具车", "label": "复合词"}], "register": "中性", "sense_fingerprint": "供孩子玩的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语法：“睡觉”是动词，不能作“有很多”的宾语。"}, {"text": "玩具", "is_correct": true, "explanation": "玩具是供孩子玩的东西，“弟弟有很多玩具”符合语境。"}, {"text": "高兴", "is_correct": false, "explanation": "语法：“高兴”是形容词，不能说“有很多高兴”。"}, {"text": "安静", "is_correct": false, "explanation": "语法：“安静”是形容词，不能说“有很多安静”。"}], "explanations": {"睡觉": "语法：“睡觉”是动词，不能作“有很多”的宾语。", "玩具": "玩具是供孩子玩的东西，“弟弟有很多玩具”符合语境。", "高兴": "语法：“高兴”是形容词，不能说“有很多高兴”。", "安静": "语法：“安静”是形容词，不能说“有很多安静”。"}, "sentence_index": 0, "correct_answer": "玩具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把螺丝刀是修东西用的玩具。", "explanation": "这里应该用〈工具〉。玩具指供孩子玩的东西，修东西用的是工具，不能说“玩具”。"}, {"text": "我下午在写玩具。", "explanation": "这里应该用〈作业〉。玩具是供玩的东西，不能用“写”，写的是作业。"}, {"text": "孩子最爱吃玩具。", "explanation": "这里应该用〈零食〉。玩具是供玩的东西，不能吃，孩子爱吃的应是零食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病人", "is_correct": false, "explanation": "语义：病人不能在店里出售，“这家店里的病人又好看又便宜”说不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能在店里出售，也谈不上便宜，与语境不符。"}, {"text": "玩具", "is_correct": true, "explanation": "玩具可以在店里出售，也能说好看、便宜，符合语境。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能在店里出售，与“这家店里的……又好看又便宜”的语境不符。"}], "explanations": {"病人": "语义：病人不能在店里出售，“这家店里的病人又好看又便宜”说不通。", "天空": "语义：天空不能在店里出售，也谈不上便宜，与语境不符。", "玩具": "玩具可以在店里出售，也能说好看、便宜，符合语境。", "月亮": "语义：月亮不能在店里出售，与“这家店里的……又好看又便宜”的语境不符。"}, "sentence_index": 6, "correct_answer": "玩具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "过生日时，他收到了一本很大的玩具。", "explanation": "这里应该用〈件〉。“本”用于书本、本子等，玩具不用“本”计量。"}, {"text": "过生日时，他收到了一棵很大的玩具。", "explanation": "这里应该用〈件〉。“棵”用于树、草等植物，玩具不能用“棵”计量。"}, {"text": "过生日时，他收到了一张很大的玩具。", "explanation": "这里应该用〈件〉。“张”用于纸、桌子等平面的东西，玩具不能用“张”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟收到了三本玩具。", "corrected_sentence": "弟弟收到了三个玩具。", "error_description": "量词错误：“玩具”前应用“个”或“件”，“本”用于书本、本子等，不能说“三本玩具”，应改为“三个玩具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一条玩具。", "corrected_sentence": "他买了一套玩具。", "error_description": "量词错误：“条”用于长条形的东西，成套的玩具应用“套”，不能说“一条玩具”，应改为“一套玩具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
