INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "熊是一种大动物，有毛，会爬树。", "primary_collocate": null, "pronunciation": "xióng", "ipa": "ɕjʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "动物园里的熊正在吃苹果。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊冬天会在山洞里睡很久，醒来就找蜂蜜吃。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只熊爬上树，想找蜂蜜吃。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头熊很大，站起来比爸爸还高。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊的毛又黑又厚，冬天一点儿也不冷。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊喜欢吃蜂蜜，也喜欢吃鱼。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在山上看见了一头熊，吓了一跳。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊用大手抓住河里的鱼。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在笼子外面看熊。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到熊走过来，我们马上跑了。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一头熊", "label": "量词"}, {"form": "黑熊", "label": "复合"}, {"form": "北极熊", "label": "复合"}], "register": "口语", "sense_fingerprint": "熊：身体很大、有毛、会爬树的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47c36c6a-10d1-484f-a144-0a730fa56e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34976, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "熊", "is_correct": true, "explanation": "熊（第二声）是本词，指一种大型动物。"}, {"text": "兄", "is_correct": false, "explanation": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“哥哥”。"}, {"text": "胸", "is_correct": false, "explanation": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“胸口”。"}, {"text": "凶", "is_correct": false, "explanation": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“凶猛”。"}, {"text": "穷", "is_correct": false, "explanation": "qióng（第二声）与 xióng（第二声）声母不同（q 与 x），意思是“贫穷”。"}], "explanations": {"熊": "熊（第二声）是本词，指一种大型动物。", "兄": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“哥哥”。", "胸": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“胸口”。", "凶": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“凶猛”。", "穷": "qióng（第二声）与 xióng（第二声）声母不同（q 与 x），意思是“贫穷”。"}, "sentence_index": null, "correct_answer": "熊"}, "level_3": {"options": [{"text": "熊", "is_correct": true, "explanation": "熊：本词，指动物，符合“动物园里”和“吃苹果”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是动物，不会吃苹果。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是动物，不能进食。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“吃”的主语必须是能进食的生命体，房子不能充当。"}], "explanations": {"熊": "熊：本词，指动物，符合“动物园里”和“吃苹果”的语境。", "桌子": "语义：桌子不是动物，不会吃苹果。", "汽车": "语义：汽车不是动物，不能进食。", "房子": "配价：“吃”的主语必须是能进食的生命体，房子不能充当。"}, "sentence_index": 0, "correct_answer": "熊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这头熊长着长长的耳朵，每天吃胡萝卜。", "explanation": "此处的“熊”指向兔子，错误。“熊”不能指兔子，描述的是兔子，应说“兔子”。"}, {"text": "这头熊会汪汪叫，见了陌生人就摇尾巴。", "explanation": "此处的“熊”指向狗，错误。“熊”不能指狗，描述的是狗，应说“狗”。"}, {"text": "这头熊有翅膀，在天上飞来飞去。", "explanation": "此处的“熊”指向鸟，错误。“熊”不能指鸟，描述的是鸟，应说“鸟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34976, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "熊", "is_correct": true, "explanation": "熊（第二声）是本词，指一种大型动物。"}, {"text": "汹", "is_correct": false, "explanation": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“汹涌”。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 xióng（第二声）韵母不同（ing 与 ong），意思是“形状”。"}, {"text": "刑", "is_correct": false, "explanation": "xíng（第二声）与 xióng（第二声）韵母不同（ing 与 ong），意思是“刑罚”。"}], "explanations": {"熊": "熊（第二声）是本词，指一种大型动物。", "汹": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“汹涌”。", "形": "xíng（第二声）与 xióng（第二声）韵母不同（ing 与 ong），意思是“形状”。", "刑": "xíng（第二声）与 xióng（第二声）韵母不同（ing 与 ong），意思是“刑罚”。"}, "sentence_index": null, "correct_answer": "熊"}, "level_3": {"options": [{"text": "熊", "is_correct": true, "explanation": "熊：本词，指动物，符合“看见一头…吓了一跳”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "量词：“头”主要用于牛、熊等大型动物，石头应说“一块”，“一头石头”不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“一头”不搭配窗户，量词不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“一头”不搭配冰箱，量词不符。"}], "explanations": {"熊": "熊：本词，指动物，符合“看见一头…吓了一跳”的语境。", "石头": "量词：“头”主要用于牛、熊等大型动物，石头应说“一块”，“一头石头”不成立。", "窗户": "搭配：“一头”不搭配窗户，量词不符。", "冰箱": "搭配：“一头”不搭配冰箱，量词不符。"}, "sentence_index": 6, "correct_answer": "熊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这头熊喜欢在窗台上晒太阳，还会喵喵叫。", "explanation": "此处的“熊”指向猫，错误。“熊”不能指猫，描述的是猫，应说“猫”。"}, {"text": "农民把这头熊赶进猪圈，给它喂食。", "explanation": "此处的“熊”指向猪，错误。“熊”不能指猪，应说“猪”。"}, {"text": "这头熊在院子里下蛋，每天早上叫醒大家。", "explanation": "此处的“熊”指向鸡，错误。“熊”不能指鸡，描述的是鸡，应说“鸡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors =