INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "摸起来不像石头那么硬，像棉花一样。", "primary_collocate": null, "pronunciation": "ruǎn", "ipa": "ʐwan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个枕头很软，睡起来真舒服。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫的毛很软，摸起来像棉花。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的沙发又大又软。", "target_word": "软", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "刚出炉的面包又香又软。", "target_word": "软", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条毛巾很软，擦脸一点儿也不疼。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婴儿的小手又小又软。", "target_word": "软", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "床太软，睡久了腰会不舒服。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她摸了摸被子，说：“真软，像云一样。”", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋底很软，走路时脚不累。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天我喜欢盖软一点儿的被子。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "软软", "label": "重叠"}, {"form": "柔软", "label": "复合"}, {"form": "軟", "label": "繁体"}], "register": "通用", "sense_fingerprint": "软：触感柔软，不硬，像棉花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebfe7736-19f5-4660-8550-caa3fb9fd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "软", "is_correct": true, "explanation": "软（ruǎn）即正确答案。"}, {"text": "暖", "is_correct": false, "explanation": "nuǎn 与 ruǎn 声母不同（n 与 r），意思是温暖。"}, {"text": "染", "is_correct": false, "explanation": "rǎn 与 ruǎn 少了介音 u，意思是染色。"}, {"text": "卵", "is_correct": false, "explanation": "luǎn 与 ruǎn 声母不同（l 与 r），意思是卵，即蛋。"}], "explanations": {"软": "软（ruǎn）即正确答案。", "暖": "nuǎn 与 ruǎn 声母不同（n 与 r），意思是温暖。", "染": "rǎn 与 ruǎn 少了介音 u，意思是染色。", "卵": "luǎn 与 ruǎn 声母不同（l 与 r），意思是卵，即蛋。"}, "sentence_index": null, "correct_answer": "软"}, "level_3": {"options": [{"text": "软", "is_correct": true, "explanation": "软：触感柔软，与“睡起来真舒服”相合。"}, {"text": "脆", "is_correct": false, "explanation": "搭配：“脆”形容易碎或口感，不能用来形容枕头的软硬。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，与枕头的触感无关。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线，与枕头的舒适感不相合。"}], "explanations": {"软": "软：触感柔软，与“睡起来真舒服”相合。", "脆": "搭配：“脆”形容易碎或口感，不能用来形容枕头的软硬。", "甜": "语义：“甜”指味道，与枕头的触感无关。", "亮": "语义：“亮”指光线，与枕头的舒适感不相合。"}, "sentence_index": 0, "correct_answer": "软"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种红色很软，看着很温柔。", "explanation": "这里误用了〈软〉。“软”形容触感，不能用来形容颜色；这里应该用〈柔和〉。"}, {"text": "这盏台灯很软，照得屋子很亮。", "explanation": "这里误用了〈软〉。“软”形容触感，台灯不能这样形容；这里应该用〈明亮〉。"}, {"text": "这个数字很软，我总是记不住。", "explanation": "这里误用了〈软〉。“软”形容触感，数字没有触感；这里应该用〈好记〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "软", "is_correct": true, "explanation": "软（ruǎn）即正确答案。"}, {"text": "短", "is_correct": false, "explanation": "duǎn 与 ruǎn 声母不同（d 与 r），意思是短。"}, {"text": "缓", "is_correct": false, "explanation": "huǎn 与 ruǎn 声母不同（h 与 r），意思是缓慢。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn 与 ruǎn 只差开头的 r 音，意思是碗。"}], "explanations": {"软": "软（ruǎn）即正确答案。", "短": "duǎn 与 ruǎn 声母不同（d 与 r），意思是短。", "缓": "huǎn 与 ruǎn 声母不同（h 与 r），意思是缓慢。", "碗": "wǎn 与 ruǎn 只差开头的 r 音，意思是碗。"}, "sentence_index": null, "correct_answer": "软"}, "level_3": {"options": [{"text": "软", "is_correct": true, "explanation": "软：触感柔软，床太软会让腰受力，与“睡久了腰会不舒服”相合。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”指颜色，与床的软硬及腰的感受无关。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”指价格高，与“睡久了腰会不舒服”没有关系。"}, {"text": "圆", "is_correct": false, "explanation": "搭配：“圆”形容形状，“床太圆”不成立，也无法解释腰的不适。"}], "explanations": {"软": "软：触感柔软，床太软会让腰受力，与“睡久了腰会不舒服”相合。", "白": "语义：“白”指颜色，与床的软硬及腰的感受无关。", "贵": "语义：“贵”指价格高，与“睡久了腰会不舒服”没有关系。", "圆": "搭配：“圆”形容形状，“床太圆”不成立，也无法解释腰的不适。"}, "sentence_index": 6, "correct_answer": "软"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个玻璃杯很软，轻轻一碰就碎了。", "explanation": "这里误用了〈软〉。“软”形容触感柔软，玻璃杯一碰就碎应说〈脆〉。"}, {"text": "这碗汤很软，喝下去很烫。", "explanation": "这里误用了〈软〉。“软”形容触感，不能形容汤的温度；这里应该用〈烫〉。"}, {"text": "这间屋子很软，只有五平方米。", "explanation": "这里误用了〈软〉。“软”形容触感，不能形容房间的大小；这里应该用〈小〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块海绵踩上去软很，像棉花一样。", "corrected_sentence": "这块海绵踩上去很软，像棉花一样。", "error_description": "“很”应放在形容词前面，说“很软”，不能说“软很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面团揉了一会儿，慢慢软出来了。", "corrected_sentence": "面团揉了一会儿，慢慢软下来了。", "error_description": "“软”后应接趋向补语“下来”，表示变软的过程；“软出来”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
