INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体内部组织疏松，受力后容易改变形状。", "primary_collocate": null, "pronunciation": "ruǎn", "ipa": "ʐwan˨˩˦", "syllable_count": 1, "sentences": [{"text": "铅是一种很软的金属，用力就能弯。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下过雨，地很软，一踩就是一个坑。", "target_word": "软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木头太软，钉子一敲就进去了。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桃子熟透了，一捏就软。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面团发好后很软，一压就变形。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土豆煮得很软，用勺子一压就碎了。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种塑料很软，一捏就变形。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新雪很软，踩下去会陷进去。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块蜡很软，用手一捏就变形。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "软的黏土可以随便捏成各种形状。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "软软", "label": "重叠"}, {"form": "变软", "label": "复合"}, {"form": "軟", "label": "繁体"}], "register": "通用", "sense_fingerprint": "软：物体内部疏松，一受力就变形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebfe7736-19f5-4660-8550-caa3fb9fd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "软", "is_correct": true, "explanation": "软（ruǎn）即正确答案。"}, {"text": "短", "is_correct": false, "explanation": "duǎn 与 ruǎn 声母不同（d 与 r），意思是短。"}, {"text": "缓", "is_correct": false, "explanation": "huǎn 与 ruǎn 声母不同（h 与 r），意思是缓慢。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn 与 ruǎn 只差开头的 r 音，意思是碗。"}], "explanations": {"软": "软（ruǎn）即正确答案。", "短": "duǎn 与 ruǎn 声母不同（d 与 r），意思是短。", "缓": "huǎn 与 ruǎn 声母不同（h 与 r），意思是缓慢。", "碗": "wǎn 与 ruǎn 只差开头的 r 音，意思是碗。"}, "sentence_index": null, "correct_answer": "软"}, "level_3": {"options": [{"text": "软", "is_correct": true, "explanation": "软：内部疏松、用力就能弯，与“铅”的性质相合。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，金属不能用味道来形容。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与金属的硬度、可弯曲性无关。"}, {"text": "脆", "is_correct": false, "explanation": "搭配：“脆”指易断，与“用力就能弯”的性质矛盾。"}], "explanations": {"软": "软：内部疏松、用力就能弯，与“铅”的性质相合。", "甜": "语义：“甜”指味道，金属不能用味道来形容。", "咸": "语义：“咸”指味道，与金属的硬度、可弯曲性无关。", "脆": "搭配：“脆”指易断，与“用力就能弯”的性质矛盾。"}, "sentence_index": 0, "correct_answer": "软"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的工资很软，一下子就花光了。", "explanation": "这里误用了〈软〉。“软”形容物体内部疏松、易变形，工资不能这样形容；这里应该用〈少〉。"}, {"text": "这把锁很软，怎么也打不开。", "explanation": "这里误用了〈软〉。打不开锁与锁是否疏松易变形无关，说的是锁得很紧；这里应该用〈牢〉。"}, {"text": "这个房间很软，只有十平方米。", "explanation": "这里误用了〈软〉。“软”形容物体内部疏松、受力易变形，房间的大小不能用“软”来说；这里应该用〈小〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "软", "is_correct": true, "explanation": "软（ruǎn）即正确答案。"}, {"text": "暖", "is_correct": false, "explanation": "nuǎn 与 ruǎn 声母不同（n 与 r），意思是温暖。"}, {"text": "染", "is_correct": false, "explanation": "rǎn 与 ruǎn 少了介音 u，意思是染色。"}, {"text": "卵", "is_correct": false, "explanation": "luǎn 与 ruǎn 声母不同（l 与 r），意思是卵，即蛋。"}], "explanations": {"软": "软（ruǎn）即正确答案。", "暖": "nuǎn 与 ruǎn 声母不同（n 与 r），意思是温暖。", "染": "rǎn 与 ruǎn 少了介音 u，意思是染色。", "卵": "luǎn 与 ruǎn 声母不同（l 与 r），意思是卵，即蛋。"}, "sentence_index": null, "correct_answer": "软"}, "level_3": {"options": [{"text": "软", "is_correct": true, "explanation": "软：物体受力后容易变形，与“一捏就变形”相合。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”指味道，与塑料的形变无关。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”指味道，不能用来形容塑料的软硬。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”形容气味，“香的塑料”不成立，也与“一捏就变形”无关。"}], "explanations": {"软": "软：物体受力后容易变形，与“一捏就变形”相合。", "苦": "语义：“苦”指味道，与塑料的形变无关。", "辣": "语义：“辣”指味道，不能用来形容塑料的软硬。", "香": "搭配：“香”形容气味，“香的塑料”不成立，也与“一捏就变形”无关。"}, "sentence_index": 6, "correct_answer": "软"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校离我家很软，走路要半个小时。", "explanation": "这里误用了〈软〉。“软”形容物体内部疏松、受力易变形，不能形容距离；这里应该用〈远〉。"}, {"text": "这个假期很软，一下子就过去了。", "explanation": "这里误用了〈软〉。假期的长短不能用“软”来形容；这里应该用〈短〉。"}, {"text": "这箱书很软，我一个人搬不动。", "explanation": "这里误用了〈软〉。“软”形容触感或内部疏松，不能用来形容箱子的重量；这里应该用〈重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块年糕蒸好后软很，一按就变形。", "corrected_sentence": "这块年糕蒸好后很软，一按就变形。", "error_description": "“很”应放在形容词前面，说“很软”，不能说“软很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气一热，黄油就软出来了。", "corrected_sentence": "天气一热，黄油就软下来了。", "error_description": "“软”后应接趋向补语“下来”，表示变软的过程；“软出来”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34980, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "讨厌", "is_correct": true, "explanation": "反义：“可爱”指让人喜欢，“讨厌”指让人不喜欢，两者相反。"}, {"text": "高大", "is_correct": false, "explanation": "不是反义：“高大”指体形或身材高，与“可爱”在这个意义上没有对立关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "不是反义：“陈旧”指东西用久了、不新鲜，不是“可爱”的对立面。"}, {"text": "复杂", "is_correct": false, "explanation": "不是反义：“复杂”与“简单”相对，与“可爱”没有反义关系。"}], "correct_answer": "讨厌", "explanations": {"讨厌": "反义：“可爱”指让人喜欢，“讨厌”指让人不喜欢，两者相反。", "高大": "不是反义：“高大”指体形或身材高，与“可爱”在这个意义上没有对立关系。", "陈旧": "不是反义：“陈旧”指东西用久了、不新鲜，不是“可爱”的对立面。", "复杂": "不是反义：“复杂”与“简单”相对，与“可爱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34980, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "讨厌", "is_correct": true, "explanation": "反义：“可爱”指让人喜欢，“讨厌”指让人不喜欢，两者相反。"}, {"text": "严肃", "is_correct": false, "explanation": "不是反义：“严肃”指态度认真、不随便，与“可爱”没有直接的对立关系。"}, {"text": "沉重", "is_correct": false, "explanation": "不是反义：“沉重”指分量大或心情压抑，与“可爱”的喜欢之意不构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "不是反义：“粗糙”指表面不光滑，与“可爱”在这个意义上没有对立关系。"}], "correct_answer": "讨厌", "explanations": {"讨厌": "反义：“可爱”指让人喜欢，“讨厌”指让人不喜欢，两者相反。", "严肃": "不是反义：“严肃”指态度认真、不随便，与“可爱”没有直接的对立关系。", "沉重": "不是反义：“沉重”指分量大或心情压抑，与“可爱”的喜欢之意不构成反义。", "粗糙": "不是反义：“粗糙”指表面不光滑，与“可爱”在这个意义上没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34980, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "让人想抱一抱的，很招人喜欢。", "primary_collocate": null, "pronunciation": "kě ài", "ipa": "kʰɤ˨˩˦ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这只小狗真可爱。", "target_word": "可爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个小女孩穿着红衣服，可爱极了。", "target_word": "可爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫软软的，毛也很长，太可爱了，我想抱抱它。", "target_word": "可爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝笑起来的样子特别可爱。", "target_word": "可爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她买了一个可爱的小熊玩具。", "target_word": "可爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小兔子的耳朵又长又软，非常可爱。", "target_word": "可爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟才两岁，圆圆的脸，大大的眼睛，很可爱。", "target_word": "可爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到那只小熊猫在吃竹子，大家都觉得它很可爱。", "target_word": "可爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小娃娃那么小，那么可爱，谁都想抱一抱。", "target_word": "可爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸭子摇摇摆摆地走路，真可爱。", "target_word": "可爱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "可愛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小而柔软、让人想抱一抱的招人喜欢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可爱", "is_correct": true, "explanation": "正确。“这只小狗真可爱”表示小狗让人喜欢，符合句意。"}, {"text": "深奥", "is_correct": false, "explanation": "语义：“深奥”指道理、学问难懂，不用来形容小狗。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”形容地域广大，不用来形容小狗。"}, {"text": "精密", "is_correct": false, "explanation": "语义：“精密”形容仪器、工艺的精确，不用来形容小狗。"}], "explanations": {"可爱": "正确。“这只小狗真可爱”表示小狗让人喜欢，符合句意。", "深奥": "语义：“深奥”指道理、学问难懂，不用来形容小狗。", "辽阔": "语义：“辽阔”形容地域广大，不用来形容小狗。", "精密": "语义：“精密”形容仪器、工艺的精确，不用来形容小狗。"}, "sentence_index": 0, "correct_answer": "可爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只被遗弃的小猫饿得直叫，真可爱。", "explanation": "这里应该用〈可怜〉。描述小猫饿得直叫的凄惨情形应该用“可怜”，“可爱”表示讨人喜欢，不能用于惨状。"}, {"text": "这条大狗可爱得很，我不敢靠近它。", "explanation": "这里应该用〈可怕〉。“可爱”表示讨人喜欢，与“我不敢靠近它”的害怕心理相矛盾。"}, {"text": "这份合同写得很可爱，条款都很清楚。", "explanation": "这里应该用〈严谨〉。“可爱”形容让人喜欢的人或东西，形容合同条款周密应该用“严谨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可爱", "is_correct": true, "explanation": "正确。“弟弟才两岁，圆圆的脸，大大的眼睛，很可爱”，符合孩子惹人喜欢的形象。"}, {"text": "苍老", "is_correct": false, "explanation": "体貌：“圆圆的脸”是年幼的样子，“苍老”描写的是年老的外貌，与“才两岁”也矛盾。"}, {"text": "成熟", "is_correct": false, "explanation": "语义：才两岁的孩子不可能“成熟”，与“才两岁”的句中信息矛盾。"}, {"text": "老练", "is_correct": false, "explanation": "语义：“老练”指经验丰富、办事熟练，与“才两岁”的年纪不符。"}], "explanations": {"可爱": "正确。“弟弟才两岁，圆圆的脸，大大的眼睛，很可爱”，符合孩子惹人喜欢的形象。", "苍老": "体貌：“圆圆的脸”是年幼的样子，“苍老”描写的是年老的外貌，与“才两岁”也矛盾。", "成熟": "语义：才两岁的孩子不可能“成熟”，与“才两岁”的句中信息矛盾。", "老练": "语义：“老练”指经验丰富、办事熟练，与“才两岁”的年纪不符。"}, "sentence_index": 6, "correct_answer": "可爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次机会错过了，真可爱。", "explanation": "这里应该用〈可惜〉。表达错过机会的遗憾要用“可惜”，“可爱”表示讨人喜欢，用在这里不符合语境。"}, {"text": "那个陌生人鬼鬼祟祟的，很可爱。", "explanation": "这里应该用〈可疑〉。形容行迹鬼祟、让人怀疑应该用“可疑”，“可爱”表示讨人喜欢，用在陌生人身上不符合。"}, {"text": "这笔账算得很可爱，一分钱都不差。", "explanation": "这里应该用〈精确〉。形容算账准确应该用“精确”，“可爱”表示讨人喜欢，用来形容算账不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只小猫可爱得。", "corrected_sentence": "那只小猫可爱得很。", "error_description": "补语缺失。“可爱得”后面要有补语说明程度，应说“可爱得很”，只说“可爱得”句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只小猫太可爱地了。", "corrected_sentence": "这只小猫太可爱了。", "error_description": "结构助词错误：“地”用在动词前作状语，“可爱”后直接接“了”，不能加“地”。应说“太可爱了”，不能说“太可爱地了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34981, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "讨厌", "is_correct": true, "explanation": "反义：“可爱”形容人亲切讨人喜欢，“讨厌”指让人不喜欢，两者相反。"}, {"text": "陈旧", "is_correct": false, "explanation": "不是反义：“陈旧”指事物用久了、不新鲜，与形容人亲切的“可爱”没有对立关系。"}, {"text": "复杂", "is_correct": false, "explanation": "不是反义：“复杂”与“简单”相对，与“可爱”的人物形象没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "不是反义：“高大”形容身材或规模，与形容人亲切的“可爱”没有对立关系。"}], "correct_answer": "讨厌", "explanations": {"讨厌": "反义：“可爱”形容人亲切讨人喜欢，“讨厌”指让人不喜欢，两者相反。", "陈旧": "不是反义：“陈旧”指事物用久了、不新鲜，与形容人亲切的“可爱”没有对立关系。", "复杂": "不是反义：“复杂”与“简单”相对，与“可爱”的人物形象没有反义关系。", "高大": "不是反义：“高大”形容身材或规模，与形容人亲切的“可爱”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34981, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "讨厌", "is_correct": true, "explanation": "反义：“可爱”形容人亲切讨人喜欢，“讨厌”指让人不喜欢，两者相反。"}, {"text": "严肃", "is_correct": false, "explanation": "不是反义：“严肃”指态度认真，与“可爱”的亲切感没有对立关系。"}, {"text": "沉重", "is_correct": false, "explanation": "不是反义：“沉重”指分量大或心情压抑，与形容人讨人喜欢的“可爱”不构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "不是反义：“粗糙”指表面不光滑，与形容人的“可爱”没有对立关系。"}], "correct_answer": "讨厌", "explanations": {"讨厌": "反义：“可爱”形容人亲切讨人喜欢，“讨厌”指让人不喜欢，两者相反。", "严肃": "不是反义：“严肃”指态度认真，与“可爱”的亲切感没有对立关系。", "沉重": "不是反义：“沉重”指分量大或心情压抑，与形容人讨人喜欢的“可爱”不构成反义。", "粗糙": "不是反义：“粗糙”指表面不光滑，与形容人的“可爱”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34981, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容人或事物让人感到亲切、喜欢，有吸引力。", "primary_collocate": null, "pronunciation": "kě ài", "ipa": "kʰɤ˨˩˦ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "她笑起来很可爱，大家都喜欢她。", "target_word": "可爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的同桌性格很可爱，总是让大家开心。", "target_word": "可爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说话很有意思，是个可爱的人。", "target_word": "可爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事里的人物都很可爱。", "target_word": "可爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有时候很傻，但这样的他也很可爱。", "target_word": "可爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店不大，但是布置得很可爱，客人都喜欢。", "target_word": "可爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶是个可爱的老人，常常给邻居的孩子讲笑话。", "target_word": "可爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真做事的样子，让人觉得很可爱。", "target_word": "可爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位演员演的角色又聪明又可爱，观众都很喜欢。", "target_word": "可爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话轻轻的，对人很亲切，大家觉得她特别可爱。", "target_word": "可爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可愛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或事物亲切讨人喜欢、有吸引力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可爱", "is_correct": true, "explanation": "正确。“她笑起来很可爱，大家都喜欢她”，表示她亲切讨人喜欢。"}, {"text": "阴险", "is_correct": false, "explanation": "语义：“阴险”指心思狠毒、暗中害人，与“笑起来”的亲切和“大家都喜欢她”相矛盾。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”与“笑起来”和“大家都喜欢她”的意思相矛盾。"}, {"text": "陈旧", "is_correct": false, "explanation": "搭配：“陈旧”多用于物品或事物，不用来形容人笑起来的样子。"}], "explanations": {"可爱": "正确。“她笑起来很可爱，大家都喜欢她”，表示她亲切讨人喜欢。", "阴险": "语义：“阴险”指心思狠毒、暗中害人，与“笑起来”的亲切和“大家都喜欢她”相矛盾。", "冷漠": "语义：“冷漠”与“笑起来”和“大家都喜欢她”的意思相矛盾。", "陈旧": "搭配：“陈旧”多用于物品或事物，不用来形容人笑起来的样子。"}, "sentence_index": 0, "correct_answer": "可爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个乞丐很可爱，穿得破破烂烂的。", "explanation": "这里应该用〈可怜〉。形容乞丐衣衫褴褛、处境悲惨应该用“可怜”，“可爱”表示讨人喜欢，用来形容这种情况不合适。"}, {"text": "那个坏人很可爱，大家都躲着他。", "explanation": "这里应该用〈可怕〉。“大家都躲着他”说明人们害怕他，应该用“可怕”，不能用“可爱”。"}, {"text": "这笔投资的收益很可爱，比去年多了一倍。", "explanation": "这里应该用〈可观〉。形容收益、数量很多应该用“可观”，“可爱”表示讨人喜欢，不能用来形容收益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可爱", "is_correct": true, "explanation": "正确。“奶奶是个可爱的老人，常常给邻居的孩子讲笑话”，表示奶奶亲切讨人喜欢。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”与“常常给邻居的孩子讲笑话”的和善行为相矛盾。"}, {"text": "冷酷", "is_correct": false, "explanation": "语义：冷酷的人不会常常给孩子讲笑话，与句中的行为矛盾。"}, {"text": "亮堂", "is_correct": false, "explanation": "搭配：“亮堂”多用于形容光线或房间，不用来形容人。"}], "explanations": {"可爱": "正确。“奶奶是个可爱的老人，常常给邻居的孩子讲笑话”，表示奶奶亲切讨人喜欢。", "凶狠": "语义：“凶狠”与“常常给邻居的孩子讲笑话”的和善行为相矛盾。", "冷酷": "语义：冷酷的人不会常常给孩子讲笑话，与句中的行为矛盾。", "亮堂": "搭配：“亮堂”多用于形容光线或房间，不用来形容人。"}, "sentence_index": 6, "correct_answer": "可爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一次次撒谎，真可爱。", "explanation": "这里应该用〈可恨〉。撒谎令人厌恶，应该用“可恨”，“可爱”表示讨人喜欢，用来形容撒谎的人不符合。"}, {"text": "那个陌生人在街角一直盯着我看，真可爱。", "explanation": "这里应该用〈可疑〉。行迹让人怀疑应该用“可疑”，“可爱”表示讨人喜欢，用在这种情况下不符合。"}, {"text": "他在比赛中故意把对手撞倒，真可爱。", "explanation": "这里应该用〈可恶〉。故意伤人的行为让人气愤，应该用“可恶”；“可爱”表示讨人喜欢，与句意相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她说话很地可爱。", "corrected_sentence": "她说话很可爱。", "error_description": "助词误用：“地”不能放在程度副词“很”与形容词“可爱”之间，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子非常可爱们。", "corrected_sentence": "这个孩子非常可爱。", "error_description": "后缀错误：“们”只能加在指人的名词或代词后，不能用在形容词“可爱”后面，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
