INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "像天空或大海的颜色。", "primary_collocate": null, "pronunciation": "lán sè", "ipa": "lan˧˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "大海是蓝色的，很漂亮。", "target_word": "蓝色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空是蓝色的，云是白色的。", "target_word": "蓝色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢蓝色，不喜欢红色。", "target_word": "蓝色", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她今天穿了蓝色的裙子。", "target_word": "蓝色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水看起来是蓝色的。", "target_word": "蓝色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的书包是蓝色的，很大。", "target_word": "蓝色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条蓝色的裤子是新买的。", "target_word": "蓝色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子用蓝色画了一片大海。", "target_word": "蓝色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙是白色的，门是蓝色的。", "target_word": "蓝色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蓝色的海和蓝色的天连在一起。", "target_word": "蓝色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深蓝色", "label": "复合"}, {"form": "浅蓝色", "label": "复合"}, {"form": "天蓝色", "label": "复合"}], "register": "中性", "sense_fingerprint": "像天空或大海的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f82c8ae-82ab-4595-b449-235c22ee33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蓝色", "is_correct": true, "explanation": "“蓝色”表示大海的颜色，与“大海是……的，很漂亮”搭配自然。"}, {"text": "石头", "is_correct": false, "explanation": "语义：大海不是石头，“大海是石头的”与句子描写不符。"}, {"text": "木头", "is_correct": false, "explanation": "语义：大海不是木头制成的，“大海是木头的”句子不通。"}, {"text": "金属", "is_correct": false, "explanation": "语义：大海不是金属，“大海是金属的”与句子描写不合。"}], "explanations": {"蓝色": "“蓝色”表示大海的颜色，与“大海是……的，很漂亮”搭配自然。", "石头": "语义：大海不是石头，“大海是石头的”与句子描写不符。", "木头": "语义：大海不是木头制成的，“大海是木头的”句子不通。", "金属": "语义：大海不是金属，“大海是金属的”与句子描写不合。"}, "sentence_index": 0, "correct_answer": "蓝色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天的树叶是蓝色的。", "explanation": "这里应该用〈绿色〉。树叶的颜色是绿色，〈蓝色〉通常指天空或大海的颜色。"}, {"text": "他把墙蓝色了。", "explanation": "这里应该用〈涂成蓝色〉。〈蓝色〉是颜色词，不能直接作动词表示“涂色”。"}, {"text": "他把蓝色穿在身上。", "explanation": "这里应该用〈蓝色的衣服〉。〈蓝色〉是颜色，不是衣物，不能被“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蓝色", "is_correct": true, "explanation": "“蓝色”修饰“裤子”，表示颜色，句子通顺。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”不能直接作定语修饰“裤子”，搭配不当。"}, {"text": "石头", "is_correct": false, "explanation": "语义：裤子不是石头做的，“石头的裤子”与句子不符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：裤子不是玻璃做的，“玻璃的裤子”不合常理。"}], "explanations": {"蓝色": "“蓝色”修饰“裤子”，表示颜色，句子通顺。", "天空": "搭配：“天空”不能直接作定语修饰“裤子”，搭配不当。", "石头": "语义：裤子不是石头做的，“石头的裤子”与句子不符。", "玻璃": "语义：裤子不是玻璃做的，“玻璃的裤子”不合常理。"}, "sentence_index": 6, "correct_answer": "蓝色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天吃了两个蓝色。", "explanation": "这里应该用〈蓝莓〉。〈蓝色〉是颜色，不能吃；吃的是蓝莓。"}, {"text": "他用蓝色来走路。", "explanation": "这里应该用〈脚〉。〈蓝色〉是颜色，不能用来走路。"}, {"text": "蓝色今天很高兴，一直在笑。", "explanation": "这里应该用〈孩子〉。〈蓝色〉是颜色，没有情绪，不会高兴、不会笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的书包是蓝色地。", "corrected_sentence": "我的书包是蓝色的。", "error_description": "错误：“是蓝色地”；正确：“是蓝色的”。“是……的”句要用“的”，“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一条蓝色地裤子。", "corrected_sentence": "他买了一条蓝色的裤子。", "error_description": "错误：“蓝色地裤子”；正确：“蓝色的裤子”。“地”用于修饰动词，修饰名词要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
