INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用毛线织成、穿在上身保暖的衣服。", "primary_collocate": null, "pronunciation": "máo yī", "ipa": "maʊ˧˥ i˥", "syllable_count": 2, "sentences": [{"text": "天冷了，我穿上了一件毛衣。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件毛衣很厚，穿着很暖和。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天他在衬衫外面穿毛衣。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雪，你要多穿一件毛衣。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的毛衣太小了，不能再穿了。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送给爸爸一件红色的毛衣。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件毛衣不贵，我买了两件。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子冷了，妈妈给他拿了一件毛衣。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛衣放在柜子里，你自己去拿。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里不冷，他把毛衣脱了。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件毛衣", "label": "量词"}, {"form": "高领毛衣", "label": "复合"}], "register": "中性", "sense_fingerprint": "冬天穿的保暖衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毛衣", "is_correct": true, "explanation": "“毛衣”是冬天保暖的衣服，与“天冷了”相符。"}, {"text": "凉衫", "is_correct": false, "explanation": "语义：凉衫是夏天穿的薄上衣，天冷时不会穿，与“天冷了”的语境冲突。"}, {"text": "泳衣", "is_correct": false, "explanation": "搭配：泳衣只在游泳时穿，不说天冷时穿上泳衣。"}, {"text": "汗衫", "is_correct": false, "explanation": "语义：汗衫是贴身的夏季衣物，与“天冷了”的语境不合。"}], "explanations": {"毛衣": "“毛衣”是冬天保暖的衣服，与“天冷了”相符。", "凉衫": "语义：凉衫是夏天穿的薄上衣，天冷时不会穿，与“天冷了”的语境冲突。", "泳衣": "搭配：泳衣只在游泳时穿，不说天冷时穿上泳衣。", "汗衫": "语义：汗衫是贴身的夏季衣物，与“天冷了”的语境不合。"}, "sentence_index": 0, "correct_answer": "毛衣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去游泳，换上了一件毛衣。", "explanation": "这里应该用〈泳衣〉。游泳要穿泳衣，毛衣是冬天保暖的衣服，不能穿着游泳。"}, {"text": "她用毛衣包了一本书。", "explanation": "这里应该用〈书皮〉。毛衣是穿在身上的衣服，包书要用书皮，不能用毛衣。"}, {"text": "她用毛衣煮汤。", "explanation": "这里应该用〈锅〉。毛衣是穿在身上的衣服，不能用来煮汤，煮汤要用锅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毛衣", "is_correct": true, "explanation": "“毛衣”是可以买卖的商品，与“不贵”和“买了两件”相符。"}, {"text": "事情", "is_correct": false, "explanation": "语义：事情没有价格，不能说“不贵”，也不能买。"}, {"text": "心事", "is_correct": false, "explanation": "搭配：“心事”不能用来买，也不说价格便宜。"}, {"text": "误会", "is_correct": false, "explanation": "语义：误会没有价格，不能买，与“不贵”和“买”冲突。"}], "explanations": {"毛衣": "“毛衣”是可以买卖的商品，与“不贵”和“买了两件”相符。", "事情": "语义：事情没有价格，不能说“不贵”，也不能买。", "心事": "搭配：“心事”不能用来买，也不说价格便宜。", "误会": "语义：误会没有价格，不能买，与“不贵”和“买”冲突。"}, "sentence_index": 6, "correct_answer": "毛衣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用毛衣盖住了锅。", "explanation": "这里应该用〈锅盖〉。毛衣是穿在身上的衣服，不能用来盖锅，应说锅盖。"}, {"text": "他用毛衣给花浇了水。", "explanation": "这里应该用〈水壶〉。毛衣是穿在身上的衣服，不能用来浇水，应说水壶。"}, {"text": "他用毛衣擦了鞋。", "explanation": "这里应该用〈抹布〉。毛衣是穿在身上的衣服，不能用来擦鞋，应说抹布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了一件很厚毛衣。", "corrected_sentence": "我昨天买了一件很厚的毛衣。", "error_description": "定语漏掉“的”：“很厚”修饰“毛衣”时中间要加“的”，应说“很厚的毛衣”，不说“很厚毛衣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里太热，他把那只毛衣脱了。", "corrected_sentence": "屋里太热，他把那件毛衣脱了。", "error_description": "量词错误：毛衣的量词应用“件”，“只”用于动物或成对物品中的一个，不能说“那只毛衣”，应说“那件毛衣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
