INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34985, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用毛线织成的上衣，通常用于保暖。", "primary_collocate": null, "pronunciation": "máo yī", "ipa": "maʊ˧˥ i˥", "syllable_count": 2, "sentences": [{"text": "奶奶用毛线给我织了一件毛衣。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在织毛衣，是蓝色的。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件毛衣是奶奶自己织的。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学会了织毛衣。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件毛衣是手工织的，很好看。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给爸爸织一件毛衣。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛衣洗的时候要小心，别用热水。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她织了三个月，毛衣才织好。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件毛衣的毛线很软。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐织的毛衣，颜色特别好看。", "target_word": "毛衣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件毛衣", "label": "量词"}, {"form": "高领毛衣", "label": "复合"}], "register": "中性", "sense_fingerprint": "用毛线织成的上衣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34985, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毛衣", "is_correct": true, "explanation": "“织了一件毛衣”指用毛线织成的上衣，与句意相符。"}, {"text": "事情", "is_correct": false, "explanation": "语义：事情不能用毛线织，与“织”的对象冲突。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“织”的对象一般是衣物、围巾等，不说织行李。"}, {"text": "心事", "is_correct": false, "explanation": "语义：心事不是可以织的东西，与“用毛线”的语境冲突。"}], "explanations": {"毛衣": "“织了一件毛衣”指用毛线织成的上衣，与句意相符。", "事情": "语义：事情不能用毛线织，与“织”的对象冲突。", "行李": "搭配：“织”的对象一般是衣物、围巾等，不说织行李。", "心事": "语义：心事不是可以织的东西，与“用毛线”的语境冲突。"}, "sentence_index": 0, "correct_answer": "毛衣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用毛衣包饺子。", "explanation": "这里应该用〈面皮〉。毛衣是穿在身上的衣服，包饺子要用面皮，不能用毛衣。"}, {"text": "她用毛衣擦干了头发。", "explanation": "这里应该用〈毛巾〉。毛衣是衣服，擦头发要用毛巾。"}, {"text": "客厅里铺着一件毛衣。", "explanation": "这里应该用〈地毯〉。毛衣是穿的衣服，不能铺在地上，应说地毯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毛衣", "is_correct": true, "explanation": "“毛衣”是可以洗的衣物，与“别用热水”的语境相符。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不能像衣物那样洗，与“用热水”的语境冲突。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能用热水洗，与句意冲突。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“洗”的对象一般是衣物、器皿等，不说洗数学。"}], "explanations": {"毛衣": "“毛衣”是可以洗的衣物，与“别用热水”的语境相符。", "电视": "语义：电视不能像衣物那样洗，与“用热水”的语境冲突。", "手机": "语义：手机不能用热水洗，与句意冲突。", "数学": "搭配：“洗”的对象一般是衣物、器皿等，不说洗数学。"}, "sentence_index": 6, "correct_answer": "毛衣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用毛衣擦了一下黑板。", "explanation": "这里应该用〈黑板擦〉。毛衣是衣服，不能用来擦黑板，应说黑板擦。"}, {"text": "妈妈用毛衣包了一个西瓜。", "explanation": "这里应该用〈保鲜膜〉。毛衣是衣服，不能用来包西瓜，应说保鲜膜。"}, {"text": "她用毛衣煮了一碗面。", "explanation": "这里应该用〈锅〉。毛衣是穿在身上的衣服，不能用来煮面，煮面要用锅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她三个月就织好了那张毛衣。", "corrected_sentence": "她三个月就织好了那件毛衣。", "error_description": "量词错误：毛衣的量词应用“件”，“张”用于平面的东西，不能说“那张毛衣”，应说“那件毛衣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张毛衣很软，穿着很舒服。", "corrected_sentence": "这件毛衣很软，穿着很舒服。", "error_description": "量词错误：毛衣的量词应用“件”，“张”用于平面的东西，不能说“这张毛衣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
