INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34986, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小熊是小的、可爱的熊玩具。", "primary_collocate": null, "pronunciation": "xiǎo xióng", "ipa": "ɕjaʊ˨˩ ɕjʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "床上有一个小熊。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹每晚抱着小熊睡觉。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小熊的眼睛是黑色的。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日那天，妈妈给我买了一个小熊。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把小熊放在书包里了。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的小熊掉在地上了。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小熊很软，我很喜欢。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的小熊都很可爱。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给小熊穿上了红衣服。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的小熊是哪里买的？", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个小熊", "label": "量词"}], "register": "口语", "sense_fingerprint": "小熊：小孩玩的、可爱的熊形玩具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小熊", "is_correct": true, "explanation": "“床上有一个小熊”说床上有一个玩具熊，符合语境。"}, {"text": "湖", "is_correct": false, "explanation": "语义：“湖”是大片水域，不可能放在床上。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”是建筑的一部分，不能说放在床上。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是房间，不能说在床上。"}], "explanations": {"小熊": "“床上有一个小熊”说床上有一个玩具熊，符合语境。", "湖": "语义：“湖”是大片水域，不可能放在床上。", "房间": "语义：“房间”是建筑的一部分，不能说放在床上。", "厨房": "语义：“厨房”是房间，不能说在床上。"}, "sentence_index": 0, "correct_answer": "小熊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "床上有一本小熊，很软。", "explanation": "这里应该用〈个〉。“本”用于书籍和册子，不用于玩具熊。"}, {"text": "床上有一棵小熊，很软。", "explanation": "这里应该用〈个〉。“棵”用于植物，玩具熊不用“棵”。"}, {"text": "书包里有一辆小熊，很软。", "explanation": "这里应该用〈个〉。“辆”用于车，玩具熊不用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小熊", "is_correct": true, "explanation": "“这个小熊很软”说玩具熊的质地柔软，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头很硬，不能说“很软”。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁是坚硬的金属，不能说“很软”。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃很硬而且容易碎，不能说“很软”。"}], "explanations": {"小熊": "“这个小熊很软”说玩具熊的质地柔软，符合句意。", "石头": "语义：石头很硬，不能说“很软”。", "钢铁": "语义：钢铁是坚硬的金属，不能说“很软”。", "玻璃": "语义：玻璃很硬而且容易碎，不能说“很软”。"}, "sentence_index": 6, "correct_answer": "小熊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "床上有一张小熊，很舒服。", "explanation": "这里应该用〈个〉。“张”用于床、纸等平面的东西，不用于玩具熊。"}, {"text": "桌上放着一座小熊，很可爱。", "explanation": "这里应该用〈个〉。“座”用于山、房屋等大型物体，不用于玩具熊。"}, {"text": "我的书包里有一片小熊，很可爱。", "explanation": "这里应该用〈个〉。“片”用于薄而平的东西，玩具熊不用“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
