INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小熊指年幼的熊。", "primary_collocate": null, "pronunciation": "xiǎo xióng", "ipa": "ɕjaʊ˨˩ ɕjʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "动物园里有两只小熊。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小熊跟着妈妈去河边喝水。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的小熊正在睡觉。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小熊爬上了一棵大树。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大熊在前面走，小熊在后面跟着。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小熊喜欢吃蜂蜜。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在森林里救了一只小熊。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊妈妈一直在保护它的小熊。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饲养员正在给小熊喂奶。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小熊长得很快。", "target_word": "小熊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只小熊", "label": "量词"}], "register": "口语", "sense_fingerprint": "小熊：年幼的熊（动物），常与大熊、熊妈妈相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34987, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小熊", "is_correct": true, "explanation": "“动物园里有两只小熊”说动物园里有两只小熊，符合句意。"}, {"text": "手套", "is_correct": false, "explanation": "语义：“手套”是戴在手上的物品，动物园里不会有。"}, {"text": "耳环", "is_correct": false, "explanation": "语义：“耳环”是戴在耳朵上的饰品，不会出现在动物园里。"}, {"text": "袜子", "is_correct": false, "explanation": "语义：“袜子”是穿在脚上的东西，动物园里不会有。"}], "explanations": {"小熊": "“动物园里有两只小熊”说动物园里有两只小熊，符合句意。", "手套": "语义：“手套”是戴在手上的物品，动物园里不会有。", "耳环": "语义：“耳环”是戴在耳朵上的饰品，不会出现在动物园里。", "袜子": "语义：“袜子”是穿在脚上的东西，动物园里不会有。"}, "sentence_index": 0, "correct_answer": "小熊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "森林里有一棵小熊，正在睡觉。", "explanation": "这里应该用〈只〉。“棵”用于植物，小熊要用“只”。"}, {"text": "河边有一辆小熊，正在喝水。", "explanation": "这里应该用〈只〉。“辆”用于车，不用于动物。"}, {"text": "商店里摆着一座小熊。", "explanation": "这里应该用〈只〉。“座”用于山、房屋等大型物体，不用于小熊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小熊", "is_correct": true, "explanation": "“我在森林里救了一只小熊”说救了森林里一只年幼的熊，符合句意。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“救”的对象一般是生命体，“鞋子”不合。"}, {"text": "手表", "is_correct": false, "explanation": "搭配：“救”的对象一般是生命体，“手表”不合。"}, {"text": "雨靴", "is_correct": false, "explanation": "搭配：“救”的对象一般是生命体，“雨靴”不合。"}], "explanations": {"小熊": "“我在森林里救了一只小熊”说救了森林里一只年幼的熊，符合句意。", "鞋子": "搭配：“救”的对象一般是生命体，“鞋子”不合。", "手表": "搭配：“救”的对象一般是生命体，“手表”不合。", "雨靴": "搭配：“救”的对象一般是生命体，“雨靴”不合。"}, "sentence_index": 6, "correct_answer": "小熊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的桌子上放着一颗小熊，真可爱。", "explanation": "这里应该用〈只〉。“颗”用于圆形的小东西，如豆子、珠子，不用于小熊。"}, {"text": "他手里拿着一把小熊，很有趣。", "explanation": "这里应该用〈只〉。“把”用于有柄的东西，如刀、伞，不用于小熊。"}, {"text": "书架上摆着一支小熊。", "explanation": "这里应该用〈只〉。“支”用于笔、枪等细长的东西，不用于小熊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
