INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34991, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指年纪小的女性儿童。", "primary_collocate": null, "pronunciation": "xiǎo nǚ hái", "ipa": "ɕjɑʊ˨˩˦ ny˨˩˦ xaɪ˧˥", "syllable_count": 3, "sentences": [{"text": "商店门口站着一个小女孩。", "target_word": "小女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩穿着红色的裙子。", "target_word": "小女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小女孩正在看书。", "target_word": "小女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在车站遇到一个小女孩。", "target_word": "小女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩把花送给了奶奶。", "target_word": "小女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩的头发又黑又长。", "target_word": "小女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩在院子里玩游戏。", "target_word": "小女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩很有礼貌，见到人就问好。", "target_word": "小女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个很可爱的小女孩。", "target_word": "小女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩正和小朋友一起跳绳。", "target_word": "小女孩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个小女孩", "label": "量词"}, {"form": "一位小女孩", "label": "量词"}], "register": "中性", "sense_fingerprint": "年纪小的女性儿童", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245aa18a-045a-46cc-b4fa-b7de9581fe19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34991, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小女孩", "is_correct": true, "explanation": "正确：「商店门口站着一个小女孩」中，「小女孩」指年纪小的女性儿童，能站在商店门口。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不会站在商店门口。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物品，不会自己站在商店门口。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，不能站在商店门口。"}], "explanations": {"小女孩": "正确：「商店门口站着一个小女孩」中，「小女孩」指年纪小的女性儿童，能站在商店门口。", "地铁": "语义：地铁是交通工具，不会站在商店门口。", "黑板": "语义：黑板是物品，不会自己站在商店门口。", "星期": "语义：星期是时间单位，不能站在商店门口。"}, "sentence_index": 0, "correct_answer": "小女孩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在车站遇到一个小女孩，她的孙子已经上小学了。", "explanation": "这里应该用〈老奶奶〉。「小女孩」指年纪小的孩子，不能用于有孙子的老年女性。"}, {"text": "我在车站遇到一个小女孩，她是我的老师。", "explanation": "语义：「小女孩」指年纪小的女孩子，不能用来指成年的老师。"}, {"text": "我在车站遇到一位小女孩，她的丈夫是医生。", "explanation": "这里应该用〈女士〉。「小女孩」指年纪小的孩子，不用于已经有丈夫的成年女性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小女孩", "is_correct": true, "explanation": "正确：「小女孩在院子里玩游戏」中，「小女孩」是能活动、会玩游戏的人。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会玩游戏，不能在院子里玩游戏。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会玩游戏，也不会在院子里活动。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：「玩游戏」的主语须是能活动的人，「小说」与之不搭配。"}], "explanations": {"小女孩": "正确：「小女孩在院子里玩游戏」中，「小女孩」是能活动、会玩游戏的人。", "冰箱": "语义：冰箱不会玩游戏，不能在院子里玩游戏。", "石头": "语义：石头不会玩游戏，也不会在院子里活动。", "小说": "搭配：「玩游戏」的主语须是能活动的人，「小说」与之不搭配。"}, "sentence_index": 6, "correct_answer": "小女孩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位小女孩在我们厂工作了三十年，是位技术骨干。", "explanation": "这里应该用〈老师傅〉。「小女孩」指年纪小的孩子，不能指在厂里工作三十年的成年人。"}, {"text": "这位小女孩是我们学校的校长。", "explanation": "语义：「小女孩」指年纪小的孩子，不能指学校里的校长。"}, {"text": "这位小女孩是公司的老板，正在开会。", "explanation": "这里应该用〈女老板〉。「小女孩」指年纪小的孩子，不能指成年的女老板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在车站遇到一只小女孩，她在等妈妈。", "corrected_sentence": "我在车站遇到一个小女孩，她在等妈妈。", "error_description": "量词误用：错误形式为「只」，正确形式为「个」，「只」用于动物，指人要用「个」或「位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班里那个安静地小女孩画得很好。", "corrected_sentence": "班里那个安静的小女孩画得很好。", "error_description": "的/地误用：错误形式为「地」，正确形式为「的」，「安静」修饰名词「小女孩」要用「的」，「地」用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
