INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39789, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门治疗牙齿疾病的医生。", "primary_collocate": null, "pronunciation": "yá yī", "ipa": "ja˧˥ i˥˥", "syllable_count": 2, "sentences": [{"text": "牙医专门治疗牙病。", "target_word": "牙医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家医院有三位经验丰富的牙医。", "target_word": "牙医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙医用机器给我补了一颗牙。", "target_word": "牙医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的牙坏了，牙医帮我治好了。", "target_word": "牙医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牙医的诊所在地铁站旁边。", "target_word": "牙医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙医告诉他要每天刷两次牙。", "target_word": "牙医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想做牙齿矫正，要先问问牙医。", "target_word": "牙医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院做了五年牙医。", "target_word": "牙医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙医给孩子检查了蛀牙。", "target_word": "牙医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她找牙医洗了牙。", "target_word": "牙医", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "牙醫", "label": "繁体"}, {"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "专门治疗牙病的医生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662c7823-51e1-46b7-b4e3-759c04a652e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39789, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼科", "is_correct": false, "explanation": "语义：眼科治疗的是眼病，“眼科专门治疗牙病”句意不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不能治疗牙病，句意不通。"}, {"text": "牙刷", "is_correct": false, "explanation": "搭配：“治疗”的主体应是医生或机构，“牙刷”不能用来治疗牙病。"}, {"text": "牙医", "is_correct": true, "explanation": "正确：“牙医专门治疗牙病”指牙科医生专门诊治牙齿疾病。"}], "explanations": {"眼科": "语义：眼科治疗的是眼病，“眼科专门治疗牙病”句意不通。", "厨房": "语义：厨房是做饭的地方，不能治疗牙病，句意不通。", "牙刷": "搭配：“治疗”的主体应是医生或机构，“牙刷”不能用来治疗牙病。", "牙医": "正确：“牙医专门治疗牙病”指牙科医生专门诊治牙齿疾病。"}, "sentence_index": 0, "correct_answer": "牙医"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "牙医帮我治好了感冒。", "explanation": "这里应该用〈医生〉。牙医只诊治牙齿，不能治感冒。"}, {"text": "牙医帮我治好了眼睛。", "explanation": "这里应该用〈眼科医生〉。牙医只负责牙齿，不负责眼睛。"}, {"text": "牙医帮我的狗治好了病。", "explanation": "这里应该用〈兽医〉。牙医只给人看牙，不给动物看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镜子", "is_correct": false, "explanation": "搭配：“问问”后接的是人，“镜子”是器物，不能被询问，句意不通。"}, {"text": "花店", "is_correct": false, "explanation": "语义：花店不是牙齿矫正方面的专业人员，“问问花店”与语境无关。"}, {"text": "牙医", "is_correct": true, "explanation": "正确：做牙齿矫正前应先咨询牙医，符合语境。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不负责牙齿矫正，“问问厨师”与语境不符。"}], "explanations": {"镜子": "搭配：“问问”后接的是人，“镜子”是器物，不能被询问，句意不通。", "花店": "语义：花店不是牙齿矫正方面的专业人员，“问问花店”与语境无关。", "牙医": "正确：做牙齿矫正前应先咨询牙医，符合语境。", "厨师": "语义：厨师不负责牙齿矫正，“问问厨师”与语境不符。"}, "sentence_index": 6, "correct_answer": "牙医"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她笑起来，牙医又白又整齐。", "explanation": "这里应该用〈牙齿〉。牙医指治牙的医生，不能指牙齿本身。"}, {"text": "她每天早上用牙医刷牙。", "explanation": "这里应该用〈牙刷〉。牙医是医生，不是刷牙的工具。"}, {"text": "她在超市买了牙医。", "explanation": "这里应该用〈牙膏〉。牙医指人，不是可以买的日用品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只牙医专门给孩子补牙。", "corrected_sentence": "那位牙医专门给孩子补牙。", "error_description": "量词错误：“牙医”指人，量词应为“位”，“只”用于动物，不能用来数人。正确说法是“那位牙医”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我明天要去牙医。", "corrected_sentence": "我明天要去看牙医。", "error_description": "用法错误：“牙医”指人，不是地点，不能直接放在“去”后面当目的地。应说“去看牙医”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
