INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牙齿是嘴里用来咬东西的小骨头。", "primary_collocate": null, "pronunciation": "yá chǐ", "ipa": "ja˧˥ ʈʂʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小狗用牙齿咬住了球。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲨鱼的牙齿又尖又长。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝长出了两颗小牙齿。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只老虎的牙齿又白又尖。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用牙齿咬开了瓶盖。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的牙齿疼，咬不了苹果。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子用牙齿啃胡萝卜。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠的牙齿会一直长。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹用牙齿咬着一块饼干。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小马张开嘴，露出了牙齿。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "排", "label": "量词"}], "register": "中性", "sense_fingerprint": "人或动物嘴里用来咬东西的小骨头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d347d6-cd46-4fd0-a1a8-e1f8b84db37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "牙齿", "is_correct": true, "explanation": "正确答案。“用牙齿咬住了球”中，牙齿是咬东西的器官。"}, {"text": "筷子", "is_correct": false, "explanation": "语义：筷子用来夹取东西，不是用来咬的，与“咬住了球”冲突。"}, {"text": "剪刀", "is_correct": false, "explanation": "语义：剪刀用来剪断东西，不用来咬住球，与句中动作不符。"}, {"text": "指甲", "is_correct": false, "explanation": "搭配：咬东西的动作一般用牙齿，不说用指甲咬住球。"}], "explanations": {"牙齿": "正确答案。“用牙齿咬住了球”中，牙齿是咬东西的器官。", "筷子": "语义：筷子用来夹取东西，不是用来咬的，与“咬住了球”冲突。", "剪刀": "语义：剪刀用来剪断东西，不用来咬住球，与句中动作不符。", "指甲": "搭配：咬东西的动作一般用牙齿，不说用指甲咬住球。"}, "sentence_index": 0, "correct_answer": "牙齿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生让他伸出牙齿看看。", "explanation": "这里应该用〈舌头〉。医生检查时要伸出的是舌头，牙齿不能伸出，应说伸出舌头。"}, {"text": "他的牙齿每天跑步五公里。", "explanation": "这里应该用〈腿〉。跑步要靠腿，牙齿不会跑步。"}, {"text": "他每天用牙齿刷牙。", "explanation": "这里应该用〈牙刷〉。刷牙要用牙刷，牙齿是被刷的部位，不能用来刷牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牙齿", "is_correct": true, "explanation": "正确答案。“兔子用牙齿啃胡萝卜”中，啃东西要靠牙齿。"}, {"text": "勺子", "is_correct": false, "explanation": "语义：勺子用来舀取东西，不用来啃胡萝卜，与“啃”冲突。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚用来扫地，不能拿来啃胡萝卜，与句中动作不符。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：啃胡萝卜要用牙齿，不说用手套啃东西。"}], "explanations": {"牙齿": "正确答案。“兔子用牙齿啃胡萝卜”中，啃东西要靠牙齿。", "勺子": "语义：勺子用来舀取东西，不用来啃胡萝卜，与“啃”冲突。", "扫帚": "语义：扫帚用来扫地，不能拿来啃胡萝卜，与句中动作不符。", "手套": "搭配：啃胡萝卜要用牙齿，不说用手套啃东西。"}, "sentence_index": 6, "correct_answer": "牙齿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他闭上牙齿，很快就睡着了。", "explanation": "这里应该用〈眼睛〉。闭上的是眼睛，牙齿不能闭上。"}, {"text": "他的牙齿被晒伤了，疼得厉害。", "explanation": "这里应该用〈脸〉。晒伤的是皮肤，牙齿不会被晒伤。"}, {"text": "他用牙齿刷地板。", "explanation": "这里应该用〈刷子〉。地板要用刷子刷，牙齿是人体器官，不能用来刷东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只牙齿很痛，我得去看医生。", "corrected_sentence": "这颗牙齿很痛，我得去看医生。", "error_description": "量词错误：“牙齿”应用量词“颗”计量，不能用“只”，应说“这颗牙齿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的两块牙齿松得厉害。", "corrected_sentence": "他的两颗牙齿松得厉害。", "error_description": "量词错误：“牙齿”应用量词“颗”计量，不能用“块”，应说“两颗牙齿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
