INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牙齿是口腔内用于咀嚼食物、辅助发音的硬组织。", "primary_collocate": null, "pronunciation": "yá chǐ", "ipa": "ja˧˥ ʈʂʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "牙齿帮我们咬碎食物。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我的牙齿很健康。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天刷牙才能保护牙齿。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙齿不好，就不能吃太硬的东西。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙齿能帮助我们发音。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的牙齿还在长。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑的时候露出白白的牙齿。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完糖要刷牙，不然牙齿会坏。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的牙齿掉了很多。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用机器检查我的牙齿。", "target_word": "牙齿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "排", "label": "量词"}], "register": "中性", "sense_fingerprint": "口腔中咀嚼、辅助发音的器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d347d6-cd46-4fd0-a1a8-e1f8b84db37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39793, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指甲", "is_correct": false, "explanation": "语义：指甲不能咬碎食物，句子说的是牙齿的功能。"}, {"text": "舌头", "is_correct": false, "explanation": "语义：舌头不能咬碎食物，它的作用是品尝和搅拌食物。"}, {"text": "眼睛", "is_correct": false, "explanation": "配价：“咬碎”要求用牙齿作工具，眼睛不能咬东西。"}, {"text": "牙齿", "is_correct": true, "explanation": "牙齿：口腔中用于咀嚼食物、辅助发音的硬组织，能咬碎食物。"}], "explanations": {"指甲": "语义：指甲不能咬碎食物，句子说的是牙齿的功能。", "舌头": "语义：舌头不能咬碎食物，它的作用是品尝和搅拌食物。", "眼睛": "配价：“咬碎”要求用牙齿作工具，眼睛不能咬东西。", "牙齿": "牙齿：口腔中用于咀嚼食物、辅助发音的硬组织，能咬碎食物。"}, "sentence_index": 0, "correct_answer": "牙齿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用牙齿看黑板上的字。", "explanation": "这里应该用〈眼睛〉。看东西要靠眼睛，牙齿不能看。"}, {"text": "我的牙齿饿了，所以想多吃一点饭。", "explanation": "这里应该用〈胃〉。饿的是胃，牙齿不会饿。"}, {"text": "他用牙齿拿起了杯子。", "explanation": "这里应该用〈手〉。拿东西要靠手，牙齿只用于咀嚼和辅助发音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "头发", "is_correct": false, "explanation": "搭配：“露出白白的”描述的是牙齿，头发不能用来笑时露出。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜不会在笑的时候露出来，句子说的是口腔部位。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会笑，也不会露出来，与“他笑的时候”不相符。"}, {"text": "牙齿", "is_correct": true, "explanation": "牙齿：笑的时候会露出来，可以用“白白的”来描述。"}], "explanations": {"头发": "搭配：“露出白白的”描述的是牙齿，头发不能用来笑时露出。", "眼镜": "语义：眼镜不会在笑的时候露出来，句子说的是口腔部位。", "石头": "语义：石头不会笑，也不会露出来，与“他笑的时候”不相符。", "牙齿": "牙齿：笑的时候会露出来，可以用“白白的”来描述。"}, "sentence_index": 6, "correct_answer": "牙齿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的牙齿尝出了甜味，所以很开心。", "explanation": "这里应该用〈舌头〉。尝味道要靠舌头，牙齿不能尝出味道。"}, {"text": "我的牙齿闻到了饭菜的香味。", "explanation": "这里应该用〈鼻子〉。闻气味要靠鼻子，牙齿不能闻东西。"}, {"text": "我的牙齿听到了铃声。", "explanation": "这里应该用〈耳朵〉。听声音要靠耳朵，牙齿不能听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我掉了两个牙齿。", "corrected_sentence": "我掉了两颗牙齿。", "error_description": "牙齿的量词应用“颗”，不能用“个”；正确说法是“两颗牙齿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子的牙齿们快要掉了。", "corrected_sentence": "孩子的牙齿快要掉了。", "error_description": "“们”只用于指人，不能加在“牙齿”后面；正确说法是“孩子的牙齿快要掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
