INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39795, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指十三岁到十九岁左右的年轻人。", "primary_collocate": null, "pronunciation": "qīng shào nián", "ipa": "tɕʰiŋ˥ ʂau˥˩ njɛn˧˥", "syllable_count": 3, "sentences": [{"text": "青少年需要每天睡足八个小时。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是写给青少年看的。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多青少年喜欢听流行音乐。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为青少年办了一个运动营。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青少年正在长身体，要多吃饭。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影不适合青少年看。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青少年的手机用得越来越多。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有一个青少年足球队。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常常和青少年谈心。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，图书馆里有很多青少年。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "青少年期", "label": "复合"}], "register": "中性", "sense_fingerprint": "十三到十九岁左右的年轻人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e685e353-0b99-4f1c-ae5d-499665025313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "青少年", "is_correct": true, "explanation": "语义：指十三到十九岁左右的年轻人，是需要充足睡眠的人。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不需要睡眠，“睡足八个小时”不能用于植物。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“睡足八个小时”只搭配能睡觉的人或动物，不能用于手机。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有睡眠需求，这句话说不通。"}], "explanations": {"青少年": "语义：指十三到十九岁左右的年轻人，是需要充足睡眠的人。", "植物": "语义：植物不需要睡眠，“睡足八个小时”不能用于植物。", "手机": "搭配：“睡足八个小时”只搭配能睡觉的人或动物，不能用于手机。", "桌子": "语义：桌子没有睡眠需求，这句话说不通。"}, "sentence_index": 0, "correct_answer": "青少年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爸爸是青少年。", "explanation": "这里应该用〈成年人〉。青少年指十三岁到十九岁左右的人，不能用来指成年的父亲。"}, {"text": "他才五岁，还是青少年。", "explanation": "这里应该用〈儿童〉。青少年的年龄在十三岁到十九岁左右，五岁的孩子是儿童。"}, {"text": "我姐姐今年三十岁，是一名青少年。", "explanation": "这里应该用〈青年〉。青少年指十三岁到十九岁左右的人，三十岁的姐姐应称青年，不能说青少年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "青少年", "is_correct": true, "explanation": "语义：指十三到十九岁左右的年轻人，他们使用手机的情况越来越多。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会使用手机，这句话不合情理。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不能使用手机，“猫的手机”说不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不会拥有或使用手机，“电脑的手机”说不通。"}], "explanations": {"青少年": "语义：指十三到十九岁左右的年轻人，他们使用手机的情况越来越多。", "石头": "语义：石头不会使用手机，这句话不合情理。", "猫": "语义：猫不能使用手机，“猫的手机”说不通。", "电脑": "语义：电脑不会拥有或使用手机，“电脑的手机”说不通。"}, "sentence_index": 6, "correct_answer": "青少年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "田里长着很多青少年。", "explanation": "这里应该用〈幼苗〉。青少年只指人，不能用来指植物。"}, {"text": "我爷爷今年七十岁，已经算青少年了。", "explanation": "这里应该用〈老年人〉。青少年指十三岁到十九岁左右的人，七十岁的爷爷是老年人，不能称青少年。"}, {"text": "这只小狗是青少年。", "explanation": "这里应该用〈幼犬〉。青少年指十三到十九岁左右的人，不能用来指小狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上有一个青少年们在露营。", "corrected_sentence": "山上有一个青少年在露营。", "error_description": "错误在“们”。“一个”表示单数，“青少年们”表示复数，二者不能同时用。正确的说法是“一个青少年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有一只青少年想当医生。", "corrected_sentence": "我们班有一个青少年想当医生。", "error_description": "错误在量词“只”。“青少年”指人，量词应用“个”，“只”多用于动物。正确的说法是“一个青少年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
