INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39797, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里负责特定功能的部分，比如心脏、肺、肝等。", "primary_collocate": null, "pronunciation": "qì guān", "ipa": "tɕʰi˥˩ kwan˥˥", "syllable_count": 2, "sentences": [{"text": "心脏是人体很重要的器官。", "target_word": "器官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肺和肝都是身体里的器官。", "target_word": "器官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的一个器官出了问题。", "target_word": "器官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝太多酒会伤害身体的器官。", "target_word": "器官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病人在等待器官移植。", "target_word": "器官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛是人的感觉器官。", "target_word": "器官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "器官老了，功能就会变差。", "target_word": "器官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的器官捐给了别人。", "target_word": "器官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体有很多器官，每个都有作用。", "target_word": "器官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在检查孩子的心脏等器官。", "target_word": "器官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "内脏器官", "label": "复合"}, {"form": "感觉器官", "label": "复合"}, {"form": "器官移植", "label": "复合"}], "register": "中性", "sense_fingerprint": "心、肺、肝等有特定功能的身体部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662c7823-51e1-46b7-b4e3-759c04a652e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39797, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "器官", "is_correct": true, "explanation": "器官：身体里负责特定功能的部分，如心脏、肺。"}, {"text": "气管", "is_correct": false, "explanation": "guǎn（第三声）与 guān（第一声）声调不同，“气管”指呼吸用的管道，不是“器官”。"}, {"text": "奇观", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，“奇观”指奇特壮观的景象。"}, {"text": "气罐", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，“气罐”指装气体的罐子。"}], "explanations": {"器官": "器官：身体里负责特定功能的部分，如心脏、肺。", "气管": "guǎn（第三声）与 guān（第一声）声调不同，“气管”指呼吸用的管道，不是“器官”。", "奇观": "qí（第二声）与 qì（第四声）声调不同，“奇观”指奇特壮观的景象。", "气罐": "guàn（第四声）与 guān（第一声）声调不同，“气罐”指装气体的罐子。"}, "sentence_index": null, "correct_answer": "器官"}, "level_3": {"options": [{"text": "器官", "is_correct": true, "explanation": "“器官”指身体里负责特定功能的部分，填入后句意通顺。"}, {"text": "公司", "is_correct": false, "explanation": "语义：“公司”指企业，心脏不是公司，句子说的是人体的部分。"}, {"text": "节目", "is_correct": false, "explanation": "语义：“节目”指表演或电视内容，不能指人体的一部分。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“很重要的工具”说的是为做事而用的东西，不能用来描述人体的器官。"}], "explanations": {"器官": "“器官”指身体里负责特定功能的部分，填入后句意通顺。", "公司": "语义：“公司”指企业，心脏不是公司，句子说的是人体的部分。", "节目": "语义：“节目”指表演或电视内容，不能指人体的一部分。", "工具": "搭配：“很重要的工具”说的是为做事而用的东西，不能用来描述人体的器官。"}, "sentence_index": 0, "correct_answer": "器官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的一个器官坏了。", "explanation": "这里应该用〈零件〉。“器官”指身体里的部分，机器的部件要用“零件”。"}, {"text": "书桌上堆满了器官。", "explanation": "这里应该用〈文件〉。“器官”指身体里负责特定功能的部分，不能用来指书桌上堆的文件。"}, {"text": "钢琴是一种很好听的器官。", "explanation": "这里应该用〈乐器〉。“乐器”是演奏音乐的工具，“器官”指身体里负责特定功能的部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "器官", "is_correct": true, "explanation": "“器官”指身体里负责特定功能的部分，老了之后功能会变差，填入后句意通顺。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：“比赛”是竞技活动，没有器官那样的功能，不会因为“老了”而功能变差。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“功能变差”不能用来形容歌曲，“歌曲”不与“功能”搭配。"}, {"text": "课程", "is_correct": false, "explanation": "语义：“课程”是教学内容，不是身体的部分，不会“老了”。"}], "explanations": {"器官": "“器官”指身体里负责特定功能的部分，老了之后功能会变差，填入后句意通顺。", "比赛": "语义：“比赛”是竞技活动，没有器官那样的功能，不会因为“老了”而功能变差。", "歌曲": "搭配：“功能变差”不能用来形容歌曲，“歌曲”不与“功能”搭配。", "课程": "语义：“课程”是教学内容，不是身体的部分，不会“老了”。"}, "sentence_index": 6, "correct_answer": "器官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把汤倒进了一个大器官里。", "explanation": "这里应该用〈器皿〉。“器皿”指盛放东西的容器，“器官”指身体里负责特定功能的部分，不能用来盛汤。"}, {"text": "工厂的器官坏了，只能停工。", "explanation": "这里应该用〈设备〉。“设备”指工厂里的机器装置，“器官”是身体的部分。"}, {"text": "木工师傅的工作台上摆着很多器官。", "explanation": "这里应该用〈器具〉。“器具”指日常或工作中使用的用具，“器官”指身体里负责特定功能的部分，不能当作工具摆在工作台上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一只器官生病了。", "corrected_sentence": "他的一个器官生病了。", "error_description": "量词错误：“器官”的量词应为“个”，写成“只”不对。“只”多用于动物，或耳朵、手等成对的部位。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些器官们都很健康。", "corrected_sentence": "这些器官都很健康。", "error_description": "“们”误用：“们”一般只加在指人的名词后面，“器官”不指人，不能说“器官们”，应说“这些器官”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把自己有的东西送给需要的人。", "primary_collocate": null, "pronunciation": "juān xiàn", "ipa": "tɕɥɛn˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他把旧衣服捐献给了山区的孩子。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这些书捐献给图书馆。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她捐献了自己一半的工资。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人把一生的积蓄都捐献给了学校。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人捐献粮食，帮助受灾的家庭。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司向灾区捐献了大量药品。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山区的孩子冬天很冷，大家捐献了很多棉衣。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有钱，只能捐献几件旧玩具。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把自己的奖金全部捐献给了养老院。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们捐献了自己的零花钱，帮助生病的小朋友。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捐献了", "label": "完成体"}, {"form": "捐献过", "label": "经历体"}, {"form": "捐献者", "label": "复合"}, {"form": "捐獻", "label": "繁体"}], "register": "正式", "sense_fingerprint": "把自己的物品或钱送给需要帮助的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e685e353-0b99-4f1c-ae5d-499665025313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捐献", "is_correct": true, "explanation": "语义：捐献指无偿把财物送给需要帮助的人，与“给了山区的孩子”相符。"}, {"text": "修", "is_correct": false, "explanation": "配价：“修”不带“给”的双宾结构，不能说修给别人。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是焚烧，旧衣服烧掉后无法送给孩子，句子说不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指割开，与“旧衣服”和“给”搭配不当，不能说切给孩子。"}], "explanations": {"捐献": "语义：捐献指无偿把财物送给需要帮助的人，与“给了山区的孩子”相符。", "修": "配价：“修”不带“给”的双宾结构，不能说修给别人。", "烧": "语义：“烧”是焚烧，旧衣服烧掉后无法送给孩子，句子说不通。", "切": "搭配：“切”指割开，与“旧衣服”和“给”搭配不当，不能说切给孩子。"}, "sentence_index": 0, "correct_answer": "捐献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把生日礼物捐献给了朋友。", "explanation": "这里应该用〈赠送〉。捐献指无偿交给机构或用于公益，送给朋友的礼物要用〈赠送〉。"}, {"text": "他把旧车捐献出去，还收了两千元。", "explanation": "这里应该用〈卖〉。捐献是无偿的，不能同时收取钱款。"}, {"text": "我把书捐献给了同学，过几天他还给我。", "explanation": "这里应该用〈借〉。捐献是把东西永久送出，不能说之后归还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捐献", "is_correct": true, "explanation": "语义：捐献指无偿送给需要的人，与“山区的孩子冬天很冷”的语境一致。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“棉衣”搭配，不能说吃棉衣。"}, {"text": "脱", "is_correct": false, "explanation": "语义：“脱”指脱下衣服，与“孩子冬天很冷”的语境相反，不能用来帮助孩子。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与“大家帮助孩子”的语境相反。"}], "explanations": {"捐献": "语义：捐献指无偿送给需要的人，与“山区的孩子冬天很冷”的语境一致。", "吃": "搭配：“吃”不能与“棉衣”搭配，不能说吃棉衣。", "脱": "语义：“脱”指脱下衣服，与“孩子冬天很冷”的语境相反，不能用来帮助孩子。", "偷": "语义：“偷”是窃取，与“大家帮助孩子”的语境相反。"}, "sentence_index": 6, "correct_answer": "捐献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们捐献了那些贫困学生。", "explanation": "这里应该用〈资助〉。捐献的对象是财物或器官，不能用于人；资助人要用〈资助〉。"}, {"text": "他捐献了一场官司，结果输了。", "explanation": "这里应该用〈打〉。捐献的对象是财物或器官，不能用于官司这样的事件，应说“打官司”。"}, {"text": "他每年都按时捐献水电费。", "explanation": "这里应该用〈交纳〉。捐献是自愿无偿的，水电费是应付的费用，不能说捐献。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把旧书捐献给着山区的小学。", "corrected_sentence": "他把旧书捐献给了山区的小学。", "error_description": "错误在“了”。“捐献给”表示已完成的动作，应用“了”，不能用“着”。正确的说法是“捐献给了山区的小学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把社区捐献了一批旧书。", "corrected_sentence": "她向社区捐献了一批旧书。", "error_description": "错误在介词“向”。“捐献”的对象要用“向”引出，不能用“把”引出“社区”。正确的说法是“她向社区捐献了一批旧书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
