INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39799, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指把自己的财物或身体的一部分无偿地给予他人或组织，用于公益或救助。", "primary_collocate": null, "pronunciation": "juān xiàn", "ipa": "tɕɥɛn˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他决定死后捐献自己的器官。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每年他都去医院捐献血液。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她向红十字会捐献了十万元善款。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位教授把遗体捐献给了医学院。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他捐献骨髓，救了一个白血病孩子。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司向基金会捐献了一千万元。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥报名当志愿者，打算捐献造血干细胞。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把大部分财产捐献给了慈善机构。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "捐献器官可以让别人重新获得健康。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷生前签了协议，同意捐献眼角膜。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "捐献了", "label": "完成体"}, {"form": "捐献过", "label": "经历体"}, {"form": "捐献者", "label": "复合"}, {"form": "捐獻", "label": "繁体"}], "register": "正式", "sense_fingerprint": "无偿捐出器官、血液、遗体或大笔财产给他人或机构，用于公益或救助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e685e353-0b99-4f1c-ae5d-499665025313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捐献", "is_correct": true, "explanation": "语义：捐献指无偿把器官交给他人或机构，符合“死后”的语境。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，不是捐献，与“决定死后……器官”的语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”只能带歌曲等，不能说唱自己的器官。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”不能与“器官”搭配，不能说撕自己的器官。"}], "explanations": {"捐献": "语义：捐献指无偿把器官交给他人或机构，符合“死后”的语境。", "扔": "语义：“扔”是丢弃，不是捐献，与“决定死后……器官”的语境不符。", "唱": "搭配：“唱”只能带歌曲等，不能说唱自己的器官。", "撕": "搭配：“撕”不能与“器官”搭配，不能说撕自己的器官。"}, "sentence_index": 0, "correct_answer": "捐献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位教授把旧电脑捐献给了医学院，还收了三百元。", "explanation": "这里应该用〈卖〉。捐献是无偿的，不能同时收取钱款。"}, {"text": "这位教授捐献了一场比赛，结果输了。", "explanation": "这里应该用〈举办〉。捐献的对象是财物或器官，比赛是活动，不能说捐献，应说“举办一场比赛”。"}, {"text": "这位教授把一台显微镜捐献给了医学院，过后又还给他。", "explanation": "这里应该用〈借〉。捐献是把东西永久送出，不能说过后归还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捐献", "is_correct": true, "explanation": "语义：捐献指无偿提供造血干细胞给需要的人，与志愿者救助的语境一致。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“造血干细胞”搭配。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”会毁坏细胞，与志愿者救助的语境不符。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”是切断，不能用于细胞，这句话说不通。"}], "explanations": {"捐献": "语义：捐献指无偿提供造血干细胞给需要的人，与志愿者救助的语境一致。", "吃": "搭配：“吃”不能与“造血干细胞”搭配。", "烧": "语义：“烧”会毁坏细胞，与志愿者救助的语境不符。", "砍": "语义：“砍”是切断，不能用于细胞，这句话说不通。"}, "sentence_index": 6, "correct_answer": "捐献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月按时捐献个人所得税。", "explanation": "这里应该用〈交纳〉。捐献是自愿无偿的，纳税是法定义务，不能说捐献。"}, {"text": "我把自己的旧自行车捐献给了表弟。", "explanation": "这里应该用〈赠送〉。捐献指无偿交给机构或用于公益，送给亲戚的东西要用〈赠送〉。"}, {"text": "他为病人捐献了朋友的眼角膜。", "explanation": "这里应该用〈移植〉。捐献的器官必须是捐献者本人的，不能说捐献别人的器官。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在捐献了自己的器官，帮助需要的人。", "corrected_sentence": "他正在捐献自己的器官，帮助需要的人。", "error_description": "错误在“了”。“正在”表示动作进行，不能与表示完成的“了”同用。应去掉“了”，说“正在捐献”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把遗体捐献给着县医院。", "corrected_sentence": "她把遗体捐献给了县医院。", "error_description": "错误在“了”。“捐献给”表示已完成的动作，应用“了”，不能用“着”。正确的说法是“捐献给了县医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
