INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "茶是一种可以泡水喝的叶子。", "primary_collocate": null, "pronunciation": "chá", "ipa": "tʂʰa˧˥", "syllable_count": 1, "sentences": [{"text": "这包茶是朋友从中国带来的。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了两盒茶当礼物。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶放在厨房的柜子里。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，农民去山上采茶。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶要用热水泡三分钟。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把茶放进杯子，再倒开水。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶又细又卷，颜色深绿。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从商店买了一斤茶。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖很多种茶。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶不要放在潮湿的地方。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包", "label": "量词"}, {"form": "盒", "label": "量词"}, {"form": "茶叶", "label": "复合"}, {"form": "茶杯", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以泡水喝的干叶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38845469-7ba0-4215-b3c1-2b01ad8b31c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39802, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "茶", "is_correct": true, "explanation": "“茶”（chá）指可以泡水喝的干叶子，是本词的读音。"}, {"text": "叉", "is_correct": false, "explanation": "chā（第一声）与 chá（第二声）声调不同，意思是叉子。"}, {"text": "插", "is_correct": false, "explanation": "chā（第一声）与 chá（第二声）声调不同，意思是插入。"}, {"text": "岔", "is_correct": false, "explanation": "chà（第四声）与 chá（第二声）声调不同，意思是岔开。"}, {"text": "馋", "is_correct": false, "explanation": "chán 与 chá 韵母不同（多了 n），意思是贪吃。"}], "explanations": {"茶": "“茶”（chá）指可以泡水喝的干叶子，是本词的读音。", "叉": "chā（第一声）与 chá（第二声）声调不同，意思是叉子。", "插": "chā（第一声）与 chá（第二声）声调不同，意思是插入。", "岔": "chà（第四声）与 chá（第二声）声调不同，意思是岔开。", "馋": "chán 与 chá 韵母不同（多了 n），意思是贪吃。"}, "sentence_index": null, "correct_answer": "茶"}, "level_3": {"options": [{"text": "茶", "is_correct": true, "explanation": "“茶”指干叶子，与“这包……是朋友从中国带来的”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“包”用于袋装物品，“桌子”不能用“包”计量。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能装成一包，与“朋友从中国带来的”不合。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“包”用于袋装物品，汽车不能说“一包”。"}], "explanations": {"茶": "“茶”指干叶子，与“这包……是朋友从中国带来的”相合。", "桌子": "搭配：“包”用于袋装物品，“桌子”不能用“包”计量。", "空气": "语义：空气不能装成一包，与“朋友从中国带来的”不合。", "汽车": "搭配：“包”用于袋装物品，汽车不能说“一包”。"}, "sentence_index": 0, "correct_answer": "茶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只茶当礼物。", "explanation": "这里应该用〈包〉或〈斤〉。茶叶按包、斤计量，不用“只”。"}, {"text": "他穿了一件茶色的外套。", "explanation": "这里的“茶”在“茶色”中指颜色，是另一义项，不是可以泡水的叶子。"}, {"text": "我们下午去茶楼坐了一会儿。", "explanation": "这里的“茶”在“茶楼”中指茶馆，是另一义项，不是叶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39802, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "茶", "is_correct": true, "explanation": "“茶”（chá）指可以泡水喝的干叶子，是本词的读音。"}, {"text": "差", "is_correct": false, "explanation": "chà（第四声）与 chá（第二声）声调不同，意思是不好、欠缺。"}, {"text": "缠", "is_correct": false, "explanation": "chán 与 chá 韵母不同（多了 n），意思是缠绕。"}, {"text": "蝉", "is_correct": false, "explanation": "chán 与 chá 韵母不同（多了 n），意思是蝉（昆虫）。"}, {"text": "擦", "is_correct": false, "explanation": "cā 与 chá 声母（c / ch）和声调都不同，意思是擦拭。"}], "explanations": {"茶": "“茶”（chá）指可以泡水喝的干叶子，是本词的读音。", "差": "chà（第四声）与 chá（第二声）声调不同，意思是不好、欠缺。", "缠": "chán 与 chá 韵母不同（多了 n），意思是缠绕。", "蝉": "chán 与 chá 韵母不同（多了 n），意思是蝉（昆虫）。", "擦": "cā 与 chá 声母（c / ch）和声调都不同，意思是擦拭。"}, "sentence_index": null, "correct_answer": "茶"}, "level_3": {"options": [{"text": "茶", "is_correct": true, "explanation": "“茶”指干叶子，与“这种……又细又卷，颜色深绿”相合。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是液体，不会“又细又卷”，与句意不合。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：电灯是照明电器，不能“又细又卷”，与句意不合。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“又细又卷”多形容叶子或线条，不用来形容书。"}], "explanations": {"茶": "“茶”指干叶子，与“这种……又细又卷，颜色深绿”相合。", "墨水": "语义：墨水是液体，不会“又细又卷”，与句意不合。", "电灯": "语义：电灯是照明电器，不能“又细又卷”，与句意不合。", "书": "搭配：“又细又卷”多形容叶子或线条，不用来形容书。"}, "sentence_index": 6, "correct_answer": "茶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一个茶，放在包里。", "explanation": "这里应该用〈包〉。茶叶按包计量，不用“个”。"}, {"text": "我们班下午开了一个茶会。", "explanation": "这里的“茶”在“茶会”中指聚会，是另一义项，不是叶子。"}, {"text": "这个配方需要两茶匙糖。", "explanation": "这里的“茶”在“茶匙”中指小勺，是另一义项，不是叶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶让我去超市买一个茶。", "corrected_sentence": "奶奶让我去超市买一包茶。", "error_description": "茶叶按包、斤计量，应说“一包茶”；说“一个茶”误用了量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买两张茶当礼物。", "corrected_sentence": "我想买两盒茶当礼物。", "error_description": "茶叶按盒计量，应说“两盒茶”；说“两张茶”误用了量词“张”，“张”多用于纸张、桌子等平面物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
