INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39805, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指接待客人的礼节和方式。", "primary_collocate": null, "pronunciation": "dài kè zhī dào", "ipa": "tai˥˩ kʰɤ˥˩ tʂɨ˥ tau˥˩", "syllable_count": 4, "sentences": [{"text": "请客人先坐，是中国人的待客之道。", "target_word": "待客之道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给客人倒茶是基本的待客之道。", "target_word": "待客之道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家的待客之道都不一样。", "target_word": "待客之道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶很懂待客之道。", "target_word": "待客之道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不让客人先吃饭，真不懂待客之道。", "target_word": "待客之道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们中国人的待客之道。", "target_word": "待客之道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本的待客之道很讲究礼貌。", "target_word": "待客之道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "送客人到门口也是待客之道。", "target_word": "待客之道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了各国的待客之道。", "target_word": "待客之道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我家，先请客人喝茶是待客之道。", "target_word": "待客之道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "接待客人的礼节和方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38845469-7ba0-4215-b3c1-2b01ad8b31c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39805, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "待客之道", "is_correct": true, "explanation": "正确。待客之道指接待客人的礼节和方式，与“请客人先坐”的语境相合。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是出门携带的箱包，不是接待客人的礼节，与“请客人先坐”不合。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是播放节目的电器，不是待人的礼节，“中国人的电视”说不通。"}, {"text": "面貌", "is_correct": false, "explanation": "体貌：面貌指容貌外观，说的是长相，不是接待客人的方式，与“请客人先坐”的行为不合。"}], "explanations": {"待客之道": "正确。待客之道指接待客人的礼节和方式，与“请客人先坐”的语境相合。", "行李": "语义：行李是出门携带的箱包，不是接待客人的礼节，与“请客人先坐”不合。", "电视": "语义：电视是播放节目的电器，不是待人的礼节，“中国人的电视”说不通。", "面貌": "体貌：面貌指容貌外观，说的是长相，不是接待客人的方式，与“请客人先坐”的行为不合。"}, "sentence_index": 0, "correct_answer": "待客之道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的待客之道很好。", "explanation": "这里应该用〈性能〉。待客之道只用于人接待客人，不能说车子有待客之道。"}, {"text": "这次考试他的待客之道很好。", "explanation": "这里应该用〈表现〉。待客之道只指接待客人的礼节，不能用来评价考试中的表现。"}, {"text": "这家公司给员工的待客之道很好。", "explanation": "这里应该用〈待遇〉。待客之道专指接待客人的礼节，不指公司对员工的薪资和待遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "待客之道", "is_correct": true, "explanation": "正确。待客之道指接待客人的礼节，与“日本的……讲究礼貌”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气象状况，不指接待客人的礼节，“日本的天气很讲究礼貌”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指身体的高矮，与接待礼节无关，不能“讲究礼貌”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用具，不是接待礼节，与“讲究礼貌”不合。"}], "explanations": {"待客之道": "正确。待客之道指接待客人的礼节，与“日本的……讲究礼貌”相合。", "天气": "语义：天气指气象状况，不指接待客人的礼节，“日本的天气很讲究礼貌”说不通。", "身高": "体貌：身高指身体的高矮，与接待礼节无关，不能“讲究礼貌”。", "雨伞": "语义：雨伞是遮雨的用具，不是接待礼节，与“讲究礼貌”不合。"}, "sentence_index": 6, "correct_answer": "待客之道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对待工作的待客之道很认真。", "explanation": "这里应该用〈态度〉。待客之道只指接待客人的礼节，不能用来形容对待工作的态度。"}, {"text": "这台电脑的待客之道很快。", "explanation": "这里应该用〈速度〉。待客之道只指人接待客人的礼节，不能形容电脑。"}, {"text": "这条河的待客之道很长。", "explanation": "这里应该用〈长度〉。待客之道是接待客人的礼节，不能形容河流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家有一只很好的待客之道。", "corrected_sentence": "他家有一套很好的待客之道。", "error_description": "量词错误：“待客之道”是抽象的礼节和方式，量词应用“套”（或“种”），不能用“只”，因为“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他犯了待客之道。", "corrected_sentence": "他违反了待客之道。", "error_description": "搭配错误：“犯”多搭配“错误”“罪行”，不能说“犯待客之道”。表示违背待客礼节，应说“违反待客之道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
