INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39806, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "饮用茶水。", "primary_collocate": null, "pronunciation": "hē chá", "ipa": "xɤ˥ tʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶喜欢在下午喝茶，吃点心。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在公园的亭子里喝茶。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有胃病，不能空着肚子喝茶。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝茶以前，先要把茶杯洗干净。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喝茶的时候，从来不说话。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷的时候，喝茶可以让身体暖和。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家茶馆很安静，很多人来这里喝茶。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我到家里喝茶，谈谈学习的事。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天工作很累，回家后只想喝茶休息。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太热，我们在树下喝茶，聊天。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喝了茶", "label": "体标：了"}, {"form": "喝过茶", "label": "体标：过"}, {"form": "喝着茶", "label": "体标：着"}, {"form": "喝喝茶", "label": "重叠"}], "register": "中性", "sense_fingerprint": "动宾结构，指喝茶这种饮料的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38845469-7ba0-4215-b3c1-2b01ad8b31c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝茶", "is_correct": true, "explanation": "正确。喝茶指饮用茶水，与“吃点心”的悠闲语境相合。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：熬夜指夜里不睡觉，与“下午”的时间不合。"}, {"text": "打针", "is_correct": false, "explanation": "语义：打针是医疗行为，不是悠闲的活动，与“吃点心”的语境不合。"}, {"text": "打雷", "is_correct": false, "explanation": "语义：打雷是天气现象，人不能做，“奶奶喜欢打雷”说不通。"}], "explanations": {"喝茶": "正确。喝茶指饮用茶水，与“吃点心”的悠闲语境相合。", "熬夜": "语义：熬夜指夜里不睡觉，与“下午”的时间不合。", "打针": "语义：打针是医疗行为，不是悠闲的活动，与“吃点心”的语境不合。", "打雷": "语义：打雷是天气现象，人不能做，“奶奶喜欢打雷”说不通。"}, "sentence_index": 0, "correct_answer": "喝茶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用耳朵喝茶。", "explanation": "这里应该用〈听〉。喝茶要用嘴，耳朵是用来听的。"}, {"text": "这块香皂是用来喝茶的。", "explanation": "这里应该用〈洗〉。香皂是用来洗脸的，不能说“用来喝茶”。"}, {"text": "爸爸喝茶喝醉了。", "explanation": "这里应该用〈喝酒〉。醉是酒的作用，茶不会让人醉，不能说“喝茶喝醉了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝茶", "is_correct": true, "explanation": "正确。喝茶指饮用茶水，与“很安静”的茶馆语境相合。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是热闹的活动，与“很安静”的环境不合。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：吵架与“很安静”直接矛盾。"}, {"text": "打球", "is_correct": false, "explanation": "语义：打球是运动，与“很安静”的茶馆语境不合。"}], "explanations": {"喝茶": "正确。喝茶指饮用茶水，与“很安静”的茶馆语境相合。", "跳舞": "语义：跳舞是热闹的活动，与“很安静”的环境不合。", "吵架": "语义：吵架与“很安静”直接矛盾。", "打球": "语义：打球是运动，与“很安静”的茶馆语境不合。"}, "sentence_index": 6, "correct_answer": "喝茶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用高压锅喝茶。", "explanation": "这里应该用〈煮〉。高压锅是用来煮饭的，不能用来喝茶。"}, {"text": "这杯白开水可以直接喝茶。", "explanation": "这里应该用〈饮用〉。这杯是白开水，不是茶，“喝茶”只用于茶。"}, {"text": "这盏台灯每天都在喝茶。", "explanation": "这里应该用〈照明〉。台灯是用来照明的，不能做喝茶的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他喝茶着，看报纸。", "corrected_sentence": "他喝着茶，看报纸。", "error_description": "体标错误：进行体“着”应紧跟动词，应说“喝着茶”，不能说“喝茶着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶喝茶喝很开心。", "corrected_sentence": "奶奶喝茶喝得很开心。", "error_description": "补语错误：表示程度的补语前要加“得”，应说“喝得很开心”，不能说“喝很开心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吵闹", "is_correct": true, "explanation": "“吵闹”与“安静”（不出声）构成反义，指声音杂乱。"}, {"text": "整洁", "is_correct": false, "explanation": "“整洁”指干净有条理，与“安静”的不出声义没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足，与“安静”的不出声义没有反义关系。"}, {"text": "严厉", "is_correct": false, "explanation": "“严厉”形容态度或要求严格，与“安静”的不出声义没有反义关系。"}], "correct_answer": "吵闹", "explanations": {"吵闹": "“吵闹”与“安静”（不出声）构成反义，指声音杂乱。", "整洁": "“整洁”指干净有条理，与“安静”的不出声义没有反义关系。", "明亮": "“明亮”指光线充足，与“安静”的不出声义没有反义关系。", "严厉": "“严厉”形容态度或要求严格，与“安静”的不出声义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吵闹", "is_correct": true, "explanation": "“吵闹”与“安静”（不出声）构成反义，指声音杂乱。"}, {"text": "灵活", "is_correct": false, "explanation": "“灵活”形容动作或头脑敏捷，与“安静”的不出声义没有反义关系。"}, {"text": "丰富", "is_correct": false, "explanation": "“丰富”指数量多或种类多，与“安静”的不出声义没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白、不模糊，与“安静”的不出声义没有反义关系。"}], "correct_answer": "吵闹", "explanations": {"吵闹": "“吵闹”与“安静”（不出声）构成反义，指声音杂乱。", "灵活": "“灵活”形容动作或头脑敏捷，与“安静”的不出声义没有反义关系。", "丰富": "“丰富”指数量多或种类多，与“安静”的不出声义没有反义关系。", "清楚": "“清楚”指明白、不模糊，与“安静”的不出声义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不说话，不发出声音；常用于请人保持安静。", "primary_collocate": null, "pronunciation": "ān jìng", "ipa": "an˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "小朋友们，请安静，老师要讲故事了。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课了，大家安静一下。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影开始了，请大家保持安静。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里要安静，不能大声说话。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对孩子说：“安静，别说话！”", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝在睡觉，你们都安静点儿。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里请安静，不要大声说话。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛要开始了，请观众们安静。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请同学们安静，听我说。”", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能安静三分钟吗？别出声。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安靜", "label": "繁体"}, {"form": "安安静静", "label": "重叠"}], "register": "中性", "sense_fingerprint": "要求别人不说话、不出声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38845469-7ba0-4215-b3c1-2b01ad8b31c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安静", "is_correct": true, "explanation": "“安静”要求别人不说话、不出声，与“老师要讲故事了”的情境相合。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”指声音杂乱，与“老师要讲故事了”需要静听的情境相反。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指场面喧嚷，与“老师要讲故事”的情境不合。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”形容外貌或景色，不能用“请”来要求小朋友做到。"}], "explanations": {"安静": "“安静”要求别人不说话、不出声，与“老师要讲故事了”的情境相合。", "吵闹": "语义：“吵闹”指声音杂乱，与“老师要讲故事了”需要静听的情境相反。", "热闹": "语义：“热闹”指场面喧嚷，与“老师要讲故事”的情境不合。", "美丽": "搭配：“美丽”形容外貌或景色，不能用“请”来要求小朋友做到。"}, "sentence_index": 0, "correct_answer": "安静"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个病人的病情很安静，医生很放心。", "explanation": "这里应该用〈稳定〉。“安静”只形容声音或环境，说病情的状况要用“稳定”。"}, {"text": "这篇文章很安静，每个段落都很清楚。", "explanation": "这里应该用〈完整〉。“安静”指没有声音，形容文章的结构齐全要用“完整”。"}, {"text": "这组数字很安静，计算结果都对。", "explanation": "这里应该用〈准确〉。“安静”不用来形容数字，说数字精确要用“准确”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安静", "is_correct": true, "explanation": "“安静”要求别人不大声说话，与“图书馆里请……，不要大声说话”相合。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”指生动好动，与图书馆要求不大声说话的意思相反。"}, {"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”形容表演或内容，不能用“请”来要求别人。"}, {"text": "大方", "is_correct": false, "explanation": "搭配：“大方”形容人的举止，不能用“请”来要求别人的状态。"}], "explanations": {"安静": "“安静”要求别人不大声说话，与“图书馆里请……，不要大声说话”相合。", "活泼": "语义：“活泼”指生动好动，与图书馆要求不大声说话的意思相反。", "精彩": "搭配：“精彩”形容表演或内容，不能用“请”来要求别人。", "大方": "搭配：“大方”形容人的举止，不能用“请”来要求别人的状态。"}, "sentence_index": 6, "correct_answer": "安静"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子很安静，用了好几年都没坏。", "explanation": "这里应该用〈牢固〉。“安静”形容声音或环境，形容物品结实要用“牢固”。"}, {"text": "老师对学生管得很安静，上课一分钟也不能迟到。", "explanation": "这里应该用〈严格〉。“安静”指没有声音，形容管理要求高要用“严格”。"}, {"text": "这家店的服务员态度很安静，让人感觉很温暖。", "explanation": "这里应该用〈热情〉。“安静”指没有声音，形容待人的态度要用“热情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请大家很安静，我有话要说。", "corrected_sentence": "请大家安静，我有话要说。", "error_description": "用“请……安静”提出要求时，“安静”前不能加“很”，应说“请大家安静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他安静安静地坐在角落里。", "corrected_sentence": "他安安静静地坐在角落里。", "error_description": "“安静”重叠要说“安安静静”，不能说“安静安静”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
