INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有吵闹声；不出声；宁静。", "primary_collocate": null, "pronunciation": "ān jìng", "ipa": "an˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "夜深了，公园里很安静，一个人也没有。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里很安静，大家都在看书。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝睡了，请你安静一点儿。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上这个小区非常安静。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师走进教室，教室一下子安静了。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的环境很安静，适合聊天。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢住在安静的地方。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的时候，同学们都很安静。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请安静，会议马上开始。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想找个安静的房间看书。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安安静静", "label": "重叠"}, {"form": "安靜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "环境或人没有声音，宁静", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38845469-7ba0-4215-b3c1-2b01ad8b31c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安静", "is_correct": true, "explanation": "“安静”指没有声音，与“夜深了”“一个人也没有”相合。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”指声音杂乱，与“一个人也没有”矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”指人声多而乱，与“一个人也没有”矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多喧嚷，与“一个人也没有”矛盾。"}], "explanations": {"安静": "“安静”指没有声音，与“夜深了”“一个人也没有”相合。", "吵闹": "语义：“吵闹”指声音杂乱，与“一个人也没有”矛盾。", "嘈杂": "语义：“嘈杂”指人声多而乱，与“一个人也没有”矛盾。", "热闹": "语义：“热闹”指人多喧嚷，与“一个人也没有”矛盾。"}, "sentence_index": 0, "correct_answer": "安静"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盘菜很安静，味道很好。", "explanation": "这里应该用〈鲜美〉。“安静”只指没有声音或宁静，不用来形容菜的味道。"}, {"text": "这份合同很安静，条款都很周密。", "explanation": "这里应该用〈严谨〉。“安静”不用来形容合同或条款，说条款严密要用“严谨”。"}, {"text": "这份报告很安静，内容很周全。", "explanation": "这里应该用〈全面〉。“安静”指没有声音或宁静，不用来形容报告的内容；说内容周全要用“全面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安静", "is_correct": true, "explanation": "“安静”修饰“地方”，指没有吵闹声，与“喜欢住在”的意思相合。"}, {"text": "闷热", "is_correct": false, "explanation": "语义：“闷热”指天气潮湿炎热，人一般不会“喜欢住在”闷热的地方。"}, {"text": "严厉", "is_correct": false, "explanation": "搭配：“严厉”多形容人的态度，不用来修饰“地方”。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”指表面不光滑，与“喜欢住在”的意思不合。"}], "explanations": {"安静": "“安静”修饰“地方”，指没有吵闹声，与“喜欢住在”的意思相合。", "闷热": "语义：“闷热”指天气潮湿炎热，人一般不会“喜欢住在”闷热的地方。", "严厉": "搭配：“严厉”多形容人的态度，不用来修饰“地方”。", "粗糙": "语义：“粗糙”指表面不光滑，与“喜欢住在”的意思不合。"}, "sentence_index": 6, "correct_answer": "安静"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书架上的书很安静，没有一本乱放。", "explanation": "这里应该用〈整齐〉。“安静”指没有声音，形容书的摆放有序要用“整齐”。"}, {"text": "这家店的价格很安静，很划算。", "explanation": "这里应该用〈便宜〉。“安静”不用来形容价格，说价格低要用“便宜”。"}, {"text": "这张桌子很安静，用了好几年都没坏。", "explanation": "这里应该用〈牢固〉。“安静”形容声音或环境，形容物品结实要用“牢固”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈安静的走进了房间。", "corrected_sentence": "妈妈安静地走进了房间。", "error_description": "“安静”修饰动词“走进”时要用“地”，应说“安静地走进”；说“安静的走进”误用了“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把会场安静了。", "corrected_sentence": "我们把会场弄安静了。", "error_description": "“安静”作结果补语时，“把”字句要加动词，应说“把会场弄安静”；直接说“把会场安静”，结构不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
