INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "基因组学是研究所有基因的学问。", "primary_collocate": null, "pronunciation": "jī yīn zǔ xué", "ipa": "tɕi˥ in˥ tsu˨˩ ɕɥe˧˥", "syllable_count": 4, "sentences": [{"text": "基因组学是一门很新的学问。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想学基因组学。", "target_word": "基因组学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "基因组学研究人体里所有的基因。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师今天讲了基因组学。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的爸爸是基因组学老师。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基因组学的书很难，但是很有意思。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我大学的专业是基因组学。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基因组学能告诉我们人为什么会生病。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大学学的是基因组学。", "target_word": "基因组学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "基因组学是生物学的一个分支。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "药物基因组学", "label": "复合"}, {"form": "功能基因组学", "label": "复合"}], "register": "书面", "sense_fingerprint": "研究所有基因的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82a6bcae-888f-4445-995d-80c5ff9d87fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基因组学", "is_correct": true, "explanation": "正确。“基因组学”是学科名称，“一门很新的学问”正指其学科性质，句意通顺。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：“饺子”是食物，不是学问，句子不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不能说成“一门学问”。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“一门……学问”只用于知识领域，不能与“地铁”搭配。"}], "explanations": {"基因组学": "正确。“基因组学”是学科名称，“一门很新的学问”正指其学科性质，句意通顺。", "饺子": "语义：“饺子”是食物，不是学问，句子不通。", "冰箱": "语义：“冰箱”是家用电器，不能说成“一门学问”。", "地铁": "搭配：“一门……学问”只用于知识领域，不能与“地铁”搭配。"}, "sentence_index": 0, "correct_answer": "基因组学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的基因组学决定了他的血型。", "explanation": "这里应该用〈基因型〉。“基因组学”是研究所有基因的学问，不能决定血型；决定血型的是个体的〈基因型〉。"}, {"text": "这个基因组学控制着眼睛的颜色。", "explanation": "这里应该用〈基因〉。“基因组学”是研究所有基因的学问，本身不能控制性状；控制眼睛颜色的是具体的〈基因〉。"}, {"text": "这种病是由基因组学引起的。", "explanation": "这里应该用〈基因突变〉。“基因组学”是学科，不能引起疾病，致病的是基因突变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基因组学", "is_correct": true, "explanation": "正确。“基因组学”是学科名称，可以作“专业”的宾语，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“专业是空气”不是学科，句中不成立。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：“专业是雨水”不是学科，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“专业”不能与“石头”搭配，句中不成立。"}], "explanations": {"基因组学": "正确。“基因组学”是学科名称，可以作“专业”的宾语，句意通顺。", "空气": "语义：“专业是空气”不是学科，句中不成立。", "雨水": "语义：“专业是雨水”不是学科，句意不通。", "石头": "搭配：“专业”不能与“石头”搭配，句中不成立。"}, "sentence_index": 6, "correct_answer": "基因组学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "基因组学是中国的一条大河。", "explanation": "这里应该用〈长江〉。“基因组学”是学科，不是河流，不能说“一条大河”。"}, {"text": "基因组学的表演非常精彩。", "explanation": "这里应该用〈舞蹈〉。“基因组学”是学科，不能“表演”，“表演”的对象应是〈舞蹈〉。"}, {"text": "他每天早上都会喝基因组学。", "explanation": "这里应该用〈牛奶〉。“基因组学”是学科，不是饮品，不能“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从小就基因组学感兴趣。", "corrected_sentence": "他从小就对基因组学感兴趣。", "error_description": "缺少介词：“对……感兴趣”中，“对”不能省略，“基因组学”前应加“对”。应说：“他从小就对基因组学感兴趣。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "许多人都在学基因组学们。", "corrected_sentence": "许多人都在学基因组学。", "error_description": "后缀错误：“们”只用于指人的名词，学科名词“基因组学”后不能加“们”。应说：“许多人都在学基因组学。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
