INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39815, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "遗传学是研究生物体基因的传递和变异规律的科学。", "primary_collocate": null, "pronunciation": "yí chuán xué", "ipa": "i˧˥ ʈʂʰuan˧˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "科学家用遗传学研究人们对药物的不同反应。", "target_word": "遗传学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗传学研究基因怎么传给下一代。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他读大学时学的是遗传学。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遗传学可以解释孩子为什么像父母。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位科学家一生都在研究遗传学。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遗传学的知识帮助医生了解疾病。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对遗传学很感兴趣。", "target_word": "遗传学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "遗传学是生物学的一个重要部分。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遗传学老师给我们讲了一个故事。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习遗传学需要先了解基因。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "分子遗传学", "label": "复合"}, {"form": "医学遗传学", "label": "复合"}], "register": "书面", "sense_fingerprint": "研究基因传递和变异规律的科学", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82a6bcae-888f-4445-995d-80c5ff9d87fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39815, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遗传学", "is_correct": true, "explanation": "“遗传学”是研究基因传递与变异的学科，可用来研究人们对药物的不同反应，与句意相符。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：天文学研究天体，无法影响人们对药物的反应。"}, {"text": "地质学", "is_correct": false, "explanation": "语义：地质学研究地壳与岩石，与药物反应没有关系。"}, {"text": "考古学", "is_correct": false, "explanation": "搭配：“研究考古学如何影响药物反应”不成立，考古学研究的是古代遗迹。"}], "explanations": {"遗传学": "“遗传学”是研究基因传递与变异的学科，可用来研究人们对药物的不同反应，与句意相符。", "天文学": "语义：天文学研究天体，无法影响人们对药物的反应。", "地质学": "语义：地质学研究地壳与岩石，与药物反应没有关系。", "考古学": "搭配：“研究考古学如何影响药物反应”不成立，考古学研究的是古代遗迹。"}, "sentence_index": 0, "correct_answer": "遗传学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我大学选了一个遗传学。", "explanation": "这里应该用〈门〉。遗传学是学科，量词用“门”，不说“一个遗传学”。"}, {"text": "那位遗传学很聪明。", "explanation": "这里不能指人。遗传学是学科名称，指人要说“遗传学家”。"}, {"text": "他得的是遗传学，需要长期治疗。", "explanation": "这里应该用〈遗传病〉。遗传学是学科，不能作为所患的病；说患病要用“遗传病”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39815, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遗传学", "is_correct": true, "explanation": "“遗传学”是学科名称，可以作“感兴趣”的对象，与句意相符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是人们感兴趣的对象，“我对垃圾很感兴趣”语义不通。"}, {"text": "砖头", "is_correct": false, "explanation": "语义：砖头是建筑材料，一般不作“感兴趣”的对象，句子不成立。"}, {"text": "墙角", "is_correct": false, "explanation": "搭配：“感兴趣”的对象多为学问、事物或活动，“墙角”不能与之搭配。"}], "explanations": {"遗传学": "“遗传学”是学科名称，可以作“感兴趣”的对象，与句意相符。", "垃圾": "语义：垃圾不是人们感兴趣的对象，“我对垃圾很感兴趣”语义不通。", "砖头": "语义：砖头是建筑材料，一般不作“感兴趣”的对象，句子不成立。", "墙角": "搭配：“感兴趣”的对象多为学问、事物或活动，“墙角”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "遗传学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种近视是遗传学造成的。", "explanation": "这里应该用〈遗传〉。遗传学指学科，表示“造成”疾病的现象要用“遗传”，学科不能造成疾病。"}, {"text": "老师把遗传学放进了盒子里。", "explanation": "这里不能把学科当实物。遗传学是抽象的学科，不能放进盒子。"}, {"text": "这种病有很强的遗传学，家里很多人都得过。", "explanation": "这里应该用〈遗传性〉。“遗传性”指疾病能传给后代的性质，“遗传学”是学科，不能用来形容疾病的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹遗传学很感兴趣。", "corrected_sentence": "妹妹对遗传学很感兴趣。", "error_description": "错误：缺少介词“对”。正确形式是“对……感兴趣”，应说“妹妹对遗传学很感兴趣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的哥哥正在学习了遗传学。", "corrected_sentence": "我的哥哥正在学习遗传学。", "error_description": "体标错误：“了”与“正在”不能同时用，“正在”表示动作进行中，句中不能再加“了”。应说：“我的哥哥正在学习遗传学。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
