INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "治病的事情。", "primary_collocate": null, "pronunciation": "yī liáo", "ipa": "i˥ ljɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他在一家医疗公司工作。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗是一件很重要的事。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗和教育都是大家关心的问题。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学医疗管理，想以后开医院。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的医疗很方便，走路就能到医院。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗行业需要很多年轻医生。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们讨论了医疗改革的问题。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区缺少医疗资源，病人要走很远去看病。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗事故发生后，医院向病人道歉了。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每年花很多钱在医疗上。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "醫療", "label": "繁体"}, {"form": "医疗保险", "label": "复合"}, {"form": "医疗队", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：治病这件事或这个领域，如医疗行业、医疗改革、医疗资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82a6bcae-888f-4445-995d-80c5ff9d87fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医疗", "is_correct": true, "explanation": "医疗公司指从事治病相关行业的公司，此处“医疗”修饰“公司”，符合句意。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“学校公司”不能说，公司前应用行业名称。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：厨房是场所，不能修饰“公司”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体指标，不是行业，无法修饰“公司”。"}], "explanations": {"医疗": "医疗公司指从事治病相关行业的公司，此处“医疗”修饰“公司”，符合句意。", "学校": "搭配：“学校公司”不能说，公司前应用行业名称。", "厨房": "搭配：厨房是场所，不能修饰“公司”。", "体温": "语义：体温是身体指标，不是行业，无法修饰“公司”。"}, "sentence_index": 0, "correct_answer": "医疗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她学医疗，想以后当医生。", "explanation": "这里应该用〈医学〉。医疗指治病的事，学科名称要用医学，不能说“学医疗”。"}, {"text": "这家医疗有很多医生，大家都很信任。", "explanation": "这里应该用〈医院〉。医疗指治病的事，不是机构，不能用“这家”来指。"}, {"text": "医疗在认真地检查病人。", "explanation": "这里应该用〈医生〉。医疗指治病的活动，不能检查病人，检查病人的是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医疗", "is_correct": true, "explanation": "医疗改革指治病领域的制度改革，此处修饰“改革”，符合句意。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体指标，不是制度改革的领域，与“讨论改革问题”不符。"}, {"text": "宇宙", "is_correct": false, "explanation": "语义：“宇宙改革”不成立，与讨论的问题无关。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“饼干”一般不作“改革”的对象，不能说“饼干改革”。"}], "explanations": {"医疗": "医疗改革指治病领域的制度改革，此处修饰“改革”，符合句意。", "体温": "语义：体温是身体指标，不是制度改革的领域，与“讨论改革问题”不符。", "宇宙": "语义：“宇宙改革”不成立，与讨论的问题无关。", "饼干": "搭配：“饼干”一般不作“改革”的对象，不能说“饼干改革”。"}, "sentence_index": 6, "correct_answer": "医疗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府去年新建了一座医疗。", "explanation": "量词误用：“座”用于建筑，医疗是治病的领域，不能用“座”计数；新建的应是“一座医院”。"}, {"text": "政府去年发了一块医疗。", "explanation": "量词误用：“块”用于块状物，医疗是抽象的事情，不能用“块”计数，也不能被“发”。"}, {"text": "政府去年买了一条医疗。", "explanation": "量词误用：“条”用于细长的东西，医疗是抽象的领域，不能用“条”计数，也不能被“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的医疗源很丰富。", "corrected_sentence": "这座城市的医疗资源很丰富。", "error_description": "词语错误：漏写“资”，“医疗源”不成词，应为“医疗资源”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他医疗行业工作多年了。", "corrected_sentence": "他在医疗行业工作多年了。", "error_description": "介词遗漏：“医疗行业”作工作的地点，前面要加“在”，应说“在医疗行业工作”；漏掉“在”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
