INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指为了保持或恢复健康而进行的各种活动，比如看病、吃药、做手术等。", "primary_collocate": null, "pronunciation": "yī liáo", "ipa": "i˥ ljɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "通过了解一个人的基因，医生可以为他提供更个性化的医疗方案。", "target_word": "医疗", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这家医院的医疗条件很好。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的医疗服务越来越方便了。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看病需要很多医疗费用。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家提高了医疗水平。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了医疗保险，生病时不用担心。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗队到山区给村民看病。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的医疗设备很新。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗技术的进步让很多病人活了下来。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在国外生病，医疗很贵。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "醫療", "label": "繁体"}, {"form": "医疗保险", "label": "复合"}, {"form": "医疗队", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：为保持或恢复健康而进行的看病、吃药、手术等活动，如医疗条件、医疗保险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82a6bcae-888f-4445-995d-80c5ff9d87fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医疗", "is_correct": true, "explanation": "医疗指看病治病的活动，此处修饰“方案”，符合句意。"}, {"text": "财务", "is_correct": false, "explanation": "语义：财务指财产和账目，与基因、医生无关，句子讲的是健康方案。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修指房屋布置，与“基因”“医生”的健康内容不相关。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影与基因、医生和健康无关，不能作为健康方案的内容。"}], "explanations": {"医疗": "医疗指看病治病的活动，此处修饰“方案”，符合句意。", "财务": "语义：财务指财产和账目，与基因、医生无关，句子讲的是健康方案。", "装修": "语义：装修指房屋布置，与“基因”“医生”的健康内容不相关。", "电影": "语义：电影与基因、医生和健康无关，不能作为健康方案的内容。"}, "sentence_index": 0, "correct_answer": "医疗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大学学的是医疗，毕业后当了医生。", "explanation": "这里应该用〈医学〉。医疗指看病治病的活动，学科名称要用医学。"}, {"text": "药店里卖各种医疗，价格都不贵。", "explanation": "这里应该用〈药品〉。医疗是治病的活动，不能像商品一样摆在药店里出售。"}, {"text": "医疗给我打了一针，我的病好多了。", "explanation": "这里应该用〈护士〉。医疗是治病的活动，不能给病人打针，打针的是护士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医疗", "is_correct": true, "explanation": "医疗队指专门去看病治病的队伍，与“看病”的内容一致。"}, {"text": "消防", "is_correct": false, "explanation": "语义：消防队负责灭火救援，不会去山区给村民看病。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球队是体育团体，不会去山区给村民看病。"}, {"text": "宣传", "is_correct": false, "explanation": "搭配：“宣传队”指做宣传的队伍，不说去给村民看病。"}], "explanations": {"医疗": "医疗队指专门去看病治病的队伍，与“看病”的内容一致。", "消防": "语义：消防队负责灭火救援，不会去山区给村民看病。", "篮球": "语义：篮球队是体育团体，不会去山区给村民看病。", "宣传": "搭配：“宣传队”指做宣传的队伍，不说去给村民看病。"}, "sentence_index": 6, "correct_answer": "医疗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给病人做了一台医疗。", "explanation": "量词误用：“台”用于机器或手术，医疗是看病治病的活动总称，不能这样计数；应说“做了一台手术”。"}, {"text": "医院给我做了一把医疗。", "explanation": "量词误用：“把”用于有柄的器具，医疗是活动总称，不能用“把”计数；可说“做了一次治疗”。"}, {"text": "我昨天接受了一只医疗。", "explanation": "量词误用：“只”用于动物等，医疗是活动总称，不能用“只”计数；可说“接受了一次治疗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的医疗条件很好吃。", "corrected_sentence": "这个城市的医疗条件很好。", "error_description": "搭配错误：“医疗条件”只能说“好/差”，不能说“好吃”，“好吃”用于食物。应说“这个城市的医疗条件很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人看病地医疗费用很高。", "corrected_sentence": "老人看病的医疗费用很高。", "error_description": "错误：修饰名词“费用”时应用“的”，不能用“地”（“地”用于副词）。正确形式是“看病的医疗费用”，应说“老人看病的医疗费用很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c07163c-1bd8-4dcf-910e-4e1110767ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
