INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39823, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使用药物进行治疗或调理。", "primary_collocate": null, "pronunciation": "yòng yào", "ipa": "jʊŋ˥˩ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "药物基因组学正在改变我们用药的方式。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "医生提醒老人要按时用药。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用药前，要先看说明书。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕妇用药必须特别小心。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他用药后三天就会好。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近用药很规律，每天早晚各一次。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用药期间不能喝酒，不然会有危险。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合理用药对病人的健康很重要。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶年纪大了，用药要听医生的话。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士告诉我用药的时间和次数。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用过药", "label": "体标"}, {"form": "用药量", "label": "复合"}, {"form": "合理用药", "label": "复合"}], "register": "中性", "sense_fingerprint": "用药：使用药物治疗或调理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871aef36-6f52-465a-aab9-0f77eb16f723') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39823, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "用药", "is_correct": true, "explanation": "正确答案。用药（yòng yào）指使用药物进行治疗或调理。"}, {"text": "送药", "is_correct": false, "explanation": "声母不同：sòng 与 yòng 只有声母 s 和 y 不同，意思是把药送去。"}, {"text": "用到", "is_correct": false, "explanation": "声母不同：dào 与 yào 只有声母 d 和 y 不同，意思是使用到。"}, {"text": "用料", "is_correct": false, "explanation": "声母不同：liào 与 yào 只有声母 l 和 y 不同，意思是使用材料。"}], "explanations": {"用药": "正确答案。用药（yòng yào）指使用药物进行治疗或调理。", "送药": "声母不同：sòng 与 yòng 只有声母 s 和 y 不同，意思是把药送去。", "用到": "声母不同：dào 与 yào 只有声母 d 和 y 不同，意思是使用到。", "用料": "声母不同：liào 与 yào 只有声母 l 和 y 不同，意思是使用材料。"}, "sentence_index": null, "correct_answer": "用药"}, "level_3": {"options": [{"text": "用药", "is_correct": true, "explanation": "正确：「用药」指使用药物进行治疗，“改变我们用药的方式”最自然。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：药物基因组学与拍照无关，“改变我们拍照的方式”说不通。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：药物基因组学与下棋无关，“改变我们下棋的方式”不成立。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”是身体状况，不能作为“……的方式”里的行为动作。"}], "explanations": {"用药": "正确：「用药」指使用药物进行治疗，“改变我们用药的方式”最自然。", "拍照": "语义：药物基因组学与拍照无关，“改变我们拍照的方式”说不通。", "下棋": "语义：药物基因组学与下棋无关，“改变我们下棋的方式”不成立。", "发烧": "搭配：“发烧”是身体状况，不能作为“……的方式”里的行为动作。"}, "sentence_index": 0, "correct_answer": "用药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司今年用药了很多新员工。", "explanation": "这里不能用〈用药〉表示雇用人员。用药只指使用药物，招聘新员工要说录用。"}, {"text": "装修房子时，他们用药很讲究。", "explanation": "这里应该用〈用料〉。用药只指使用药物治疗，装修用的材料要说用料。"}, {"text": "这台机器需要定期用药才能正常工作。", "explanation": "这里应该用〈加油〉。用药只指使用药物，给机器加油润滑要说加油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用药", "is_correct": true, "explanation": "正确：「用药期间」指服药的这段时间，是此处唯一合适的词。"}, {"text": "干杯", "is_correct": false, "explanation": "语义：干杯本来就要喝酒，与“不能喝酒”的要求直接矛盾。"}, {"text": "抄写", "is_correct": false, "explanation": "语义：抄写与喝酒的危险无关，“抄写期间不能喝酒”不成立。"}, {"text": "敬酒", "is_correct": false, "explanation": "语义：敬酒需要喝酒，与“期间不能喝酒”的说法互相矛盾。"}], "explanations": {"用药": "正确：「用药期间」指服药的这段时间，是此处唯一合适的词。", "干杯": "语义：干杯本来就要喝酒，与“不能喝酒”的要求直接矛盾。", "抄写": "语义：抄写与喝酒的危险无关，“抄写期间不能喝酒”不成立。", "敬酒": "语义：敬酒需要喝酒，与“期间不能喝酒”的说法互相矛盾。"}, "sentence_index": 6, "correct_answer": "用药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在饭店用药，点了三道菜。", "explanation": "这里应该用〈用餐〉。用药指使用药物，在饭店吃饭要说用餐。"}, {"text": "我的手机坏了，要拿去用药修理。", "explanation": "这里应该用〈维修〉。用药只指使用药物，修理手机要说维修。"}, {"text": "她的裙子破了，需要用药缝一下。", "explanation": "这里应该用〈修补〉。用药只指使用药物，裙子破了要说修补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生把这个病人用药。", "corrected_sentence": "医生给这个病人用药。", "error_description": "把字句错误：“用药”不能用于“把”字句处置人，应说“给这个病人用药”，“把这个病人用药”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用药感冒，很快就好了。", "corrected_sentence": "他用药治感冒，很快就好了。", "error_description": "缺少动词：“用药”后面要接“治”，应说“用药治感冒”；直接说“用药感冒”意思不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
