INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木马是一种玩具，小朋友可以骑在上面玩。", "primary_collocate": null, "pronunciation": "mù mǎ", "ipa": "mu˥˩ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "小弟弟爱坐在木马上玩。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里卖各种各样的木马。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在木马上摇来摇去。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个木马是用木头做的，很结实。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "女儿过生日，我送她一个木马。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "幼儿园里有两个大木马。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友排着队等着骑木马。", "target_word": "木马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把木马搬到了院子里。", "target_word": "木马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木马的背上画着漂亮的花。", "target_word": "木马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子骑木马的时候，妈妈在旁边看着。", "target_word": "木马", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个木马", "label": "量词"}, {"form": "旋转木马", "label": "复合"}, {"form": "木馬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小朋友可以骑在上面玩的玩具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e653b9f-1786-4a98-96fa-5c2fd7ba68c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木马", "is_correct": true, "explanation": "木马是玩具，可以坐在上面玩，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是水体，不能坐在上面玩。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是抽象的称呼，不能让人坐在上面。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“坐”需要有支撑的实体，不说“坐在空气上”。"}], "explanations": {"木马": "木马是玩具，可以坐在上面玩，符合句意。", "河流": "语义：河流是水体，不能坐在上面玩。", "名字": "语义：名字是抽象的称呼，不能让人坐在上面。", "空气": "搭配：“坐”需要有支撑的实体，不说“坐在空气上”。"}, "sentence_index": 0, "correct_answer": "木马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他推着木马去市场买菜，东西装了一车。", "explanation": "这里应该用〈小车〉。木马是供孩子骑坐的玩具，不能推着运东西。"}, {"text": "他把水倒进木马里，水很快就满了。", "explanation": "这里应该用〈木桶〉。木桶用来盛水，木马是玩具，不能装水。"}, {"text": "他穿着木马去上学。", "explanation": "这里应该用〈鞋子〉。“穿”用于鞋袜、衣服等，木马是供儿童骑坐的玩具，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木马", "is_correct": true, "explanation": "木马是可以骑的玩具，句中“排队等着骑”指向它。"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件是纸质材料，不能骑。"}, {"text": "电线", "is_correct": false, "explanation": "搭配：“骑”的对象是可以骑的物件，不说“骑电线”。"}, {"text": "石板", "is_correct": false, "explanation": "语义：石板是铺地或建筑的材料，不是可以骑的东西。"}], "explanations": {"木马": "木马是可以骑的玩具，句中“排队等着骑”指向它。", "文件": "语义：文件是纸质材料，不能骑。", "电线": "搭配：“骑”的对象是可以骑的物件，不说“骑电线”。", "石板": "语义：石板是铺地或建筑的材料，不是可以骑的东西。"}, "sentence_index": 6, "correct_answer": "木马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室的墙上挂着一张木马。", "explanation": "这里应该用〈个〉。“张”用于平面物品，木马是立体的玩具，应说“一个木马”或“一匹木马”。"}, {"text": "他的手里拿着一根木马。", "explanation": "这里应该用〈个〉。“根”用于细长物，木马不能用“根”，应说“一个木马”。"}, {"text": "天冷了，妈妈给我盖上一条厚厚的木马。", "explanation": "这里应该用〈被子〉。被子用来盖在身上保暖，木马是供儿童骑坐的玩具，不能盖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐送给我一辆木马。", "corrected_sentence": "姐姐送给我一个木马。", "error_description": "量词错误：“木马”是玩具，应配量词“个”，不用“辆”（“辆”用于车辆）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幼儿园的院子里放着两个木马们。", "corrected_sentence": "幼儿园的院子里放着两个木马。", "error_description": "“们”错误：“们”只用于指人的名词之后，“木马”是事物，不能加“们”表示复数；应直接说“两个木马”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
