INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39825, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木马是一种外形像马的玩具，通常供儿童骑坐玩耍。", "primary_collocate": null, "pronunciation": "mù mǎ", "ipa": "mu˥˩ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "其中一种很特别的玩具叫做木马。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "坐在木马上，孩子们可以假装自己在骑马。", "target_word": "木马", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "木马让儿童的玩耍时光更加有趣。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "他们会玩一些简单的玩具，比如木马、娃娃或者球。", "target_word": "木马", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他骑在木马上，笑得很开心。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有一个红色的木马。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹最喜欢的玩具是木马。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子坐上木马，慢慢摇起来。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个木马是爷爷用木头做的。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木马的头上有一条长长的绳子。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个木马", "label": "量词"}, {"form": "旋转木马", "label": "复合"}, {"form": "木馬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "外形像马、供儿童骑坐的玩具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e653b9f-1786-4a98-96fa-5c2fd7ba68c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39825, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木马", "is_correct": true, "explanation": "木马是一种供儿童骑坐的玩具，符合句中“很特别的玩具”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是天然矿物，不是玩具的名称。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能作为玩具的名称。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”是食物，不是玩具的名称。"}], "explanations": {"木马": "木马是一种供儿童骑坐的玩具，符合句中“很特别的玩具”。", "石头": "语义：石头是天然矿物，不是玩具的名称。", "咖啡": "语义：咖啡是饮品，不能作为玩具的名称。", "蔬菜": "语义：“蔬菜”是食物，不是玩具的名称。"}, "sentence_index": 0, "correct_answer": "木马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "演员在舞台上操纵木马，表演很精彩。", "explanation": "这里应该用〈木偶〉。木偶是用手或线操纵的表演道具，木马是供儿童骑坐的玩具，不能用来操纵表演。"}, {"text": "孩子们在院子里荡木马，玩得很开心。", "explanation": "这里应该用〈秋千〉。“荡”用于秋千这类可以来回摆动的器械，木马是靠摇晃玩耍的玩具。"}, {"text": "他站在木马上快速滑行。", "explanation": "这里应该用〈滑板〉。滑板是用来站立滑行的器材，木马是供儿童骑坐摇晃的玩具，不能站着滑行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木马", "is_correct": true, "explanation": "木马是玩具，句中“妹妹最喜欢的玩具”指向它。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是玩具。"}, {"text": "文献", "is_correct": false, "explanation": "语义：“文献”是书面资料，不是玩具。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚是打扫用具，不是玩具。"}], "explanations": {"木马": "木马是玩具，句中“妹妹最喜欢的玩具”指向它。", "作业": "语义：作业是学习任务，不是玩具。", "文献": "语义：“文献”是书面资料，不是玩具。", "扫帚": "语义：扫帚是打扫用具，不是玩具。"}, "sentence_index": 6, "correct_answer": "木马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客厅里摆着一张木马。", "explanation": "这里应该用〈个〉。“张”用于平面物品，木马是立体的玩具，应说“一个木马”或“一匹木马”。"}, {"text": "妹妹抱着一把木马睡觉。", "explanation": "这里应该用〈个〉。“把”用于有柄的物品，木马不能用“把”，应说“一个木马”。"}, {"text": "院子里放着一根木马。", "explanation": "这里应该用〈个〉。“根”用于细长物，木马不能用“根”，应说“一个木马”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有一辆木马。", "corrected_sentence": "我家有一个木马。", "error_description": "量词错误：“木马”是玩具，应配量词“个”，不用“辆”（“辆”用于车辆）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里有两个木马们。", "corrected_sentence": "院子里有两个木马。", "error_description": "“们”错误：“们”只用于指人的名词之后，“木马”是事物，不能加“们”表示复数；应直接说“两个木马”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
