INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39828, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出一个样子，让别人以为是真的。", "primary_collocate": null, "pronunciation": "jiǎ zhuāng", "ipa": "tɕja˨˩˦ ʈʂwaŋ˥", "syllable_count": 2, "sentences": [{"text": "她假装不累，继续往前走。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗假装没看见我们。", "target_word": "假装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他假装喝醉了，躺在沙发上。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用假装高兴。", "target_word": "假装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师知道他在假装，没有说话。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹假装自己是医生，给娃娃看病。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他假装打电话，不想理那个人。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我假装没有看到，就走开了。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们假装睡着了，等着妈妈关灯。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥假装生气，其实一点也不生气。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "假装着", "label": "体标"}, {"form": "假装过", "label": "体标"}, {"form": "假裝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做出样子，让别人信以为真", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d894458-c853-45d6-bca3-f85972cb2c8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39828, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "假装", "is_correct": true, "explanation": "正确答案。假装 jiǎ zhuāng，做出一个样子，让别人以为是真的。"}, {"text": "加装", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加安装。"}, {"text": "家装", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家庭装修。"}, {"text": "嫁妆", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是陪嫁的财物。"}], "explanations": {"假装": "正确答案。假装 jiǎ zhuāng，做出一个样子，让别人以为是真的。", "加装": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加安装。", "家装": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家庭装修。", "嫁妆": "jià（第四声）与 jiǎ（第三声）声调不同，意思是陪嫁的财物。"}, "sentence_index": null, "correct_answer": "假装"}, "level_3": {"options": [{"text": "假装", "is_correct": true, "explanation": "正确答案。“假装不累”表示故意做出不累的样子。"}, {"text": "担心", "is_correct": false, "explanation": "搭配：“担心”接的是可能发生的坏事，不接“不累”这样的状态。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：“拒绝”要接请求或事情，不能直接接“不累”这样的状态。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指记不住，与句中有意识地继续往前走的语境不符。"}], "explanations": {"假装": "正确答案。“假装不累”表示故意做出不累的样子。", "担心": "搭配：“担心”接的是可能发生的坏事，不接“不累”这样的状态。", "拒绝": "配价：“拒绝”要接请求或事情，不能直接接“不累”这样的状态。", "忘记": "语义：“忘记”指记不住，与句中有意识地继续往前走的语境不符。"}, "sentence_index": 0, "correct_answer": "假装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子假装很舒服。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，椅子不能故意做样子；只说外观时用“显得”。"}, {"text": "这间屋子假装得很暖和。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，屋子不能故意做样子；只说感觉时用“显得”。"}, {"text": "这张桌子假装很结实。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，桌子不能故意做样子；只说外观时用“显得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b734a76f-5a0e-4d61-a58c-2f56b139478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_val