INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假装", "is_correct": true, "explanation": "正确答案。“假装打电话”表示做出打电话的样子。"}, {"text": "担心", "is_correct": false, "explanation": "搭配：“担心”接的是可能发生的坏事，不接“打电话”这样的动作。"}, {"text": "练习", "is_correct": false, "explanation": "语义：“练习”指反复学习，与“不想理那个人”的语境不合。"}, {"text": "帮助", "is_correct": false, "explanation": "配价：“帮助”需要受助对象，句中没有受助者，且与语境不合。"}], "explanations": {"假装": "正确答案。“假装打电话”表示做出打电话的样子。", "担心": "搭配：“担心”接的是可能发生的坏事，不接“打电话”这样的动作。", "练习": "语义：“练习”指反复学习，与“不想理那个人”的语境不合。", "帮助": "配价：“帮助”需要受助对象，句中没有受助者，且与语境不合。"}, "sentence_index": 6, "correct_answer": "假装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书假装很厚。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，书不能故意做样子；只说外观时用“显得”。"}, {"text": "这碗粥假装很香。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，粥不能故意做样子；只说气味或外观时用“显得”。"}, {"text": "这块石头假装很重。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，石头不能故意做样子；只说外观时用“显得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b734a76f-5a0e-4d61-a58c-2f56b139478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把假装累了，躺在床上。", "corrected_sentence": "他假装累了，躺在床上。", "error_description": "结构错误：“假装”前不能加“把”，“把”字句要求处置某个对象，这里应删去“把”。正确形式：“他假装累了，躺在床上。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b734a76f-5a0e-4d61-a58c-2f56b139478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐假装得不知道，笑着走开了。", "corrected_sentence": "姐姐假装不知道，笑着走开了。", "error_description": "结构错误：“假装”后面直接接要装出的样子，不能加“得”。正确形式：删去“得”，写作“姐姐假装不知道，笑着走开了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b734a76f-5a0e-4d61-a58c-2f56b139478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
