INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "儿童就是小孩子。", "primary_collocate": null, "pronunciation": "ér tóng", "ipa": "ɚ˧˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "公园里有很多儿童在玩。", "target_word": "儿童", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书是给儿童看的。", "target_word": "儿童", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "儿童不能一个人过马路。", "target_word": "儿童", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院为儿童准备了特别的玩具。", "target_word": "儿童", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "儿童和成人都喜欢这个游乐场。", "target_word": "儿童", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给儿童讲了一个有趣的故事。", "target_word": "儿童", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "儿童每天要睡十个小时左右才够。", "target_word": "儿童", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生专门治疗儿童的病。", "target_word": "儿童", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们长大后，就不再是儿童了。", "target_word": "儿童", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在很多国家，儿童坐车时要用专门的座椅。", "target_word": "儿童", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兒童", "label": "繁体"}, {"form": "儿童节", "label": "复合"}], "register": "中性", "sense_fingerprint": "年纪小的孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "儿童", "is_correct": true, "explanation": "儿童：指小孩子，与“很多……在玩”的语境相符。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是植物，不会在公园里“玩”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会在公园里“玩”。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“乘客”多与车站、坐车搭配，不与公园里的“玩”搭配。"}], "explanations": {"儿童": "儿童：指小孩子，与“很多……在玩”的语境相符。", "蔬菜": "语义：蔬菜是植物，不会在公园里“玩”。", "桌子": "语义：桌子是家具，不会在公园里“玩”。", "乘客": "搭配：“乘客”多与车站、坐车搭配，不与公园里的“玩”搭配。"}, "sentence_index": 0, "correct_answer": "儿童"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的儿童今年上大学了。", "explanation": "这里应该用〈孩子〉。儿童指年纪小的孩子，不指已经上大学的子女。"}, {"text": "她怀孕三个月了，肚子里的儿童很健康。", "explanation": "这里应该用〈胎儿〉。儿童指已经出生的小孩子，还在妈妈肚子里的要用胎儿。"}, {"text": "这群儿童都是大学生，明年就毕业了。", "explanation": "这里应该用〈年轻人〉。儿童指年纪小的孩子，大学生已经不是儿童了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "儿童", "is_correct": true, "explanation": "儿童：指小孩子，需要长时间睡眠，与“睡十个小时才够”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会睡觉，不能作“每天要睡十个小时”的主语。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会睡觉，不能作“每天要睡十个小时”的主语。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是体形指标，不能作睡觉的主语。"}], "explanations": {"儿童": "儿童：指小孩子，需要长时间睡眠，与“睡十个小时才够”相符。", "石头": "语义：石头不会睡觉，不能作“每天要睡十个小时”的主语。", "冰箱": "语义：冰箱不会睡觉，不能作“每天要睡十个小时”的主语。", "身高": "体貌：“身高”是体形指标，不能作睡觉的主语。"}, "sentence_index": 6, "correct_answer": "儿童"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的儿童都很勤奋，每天加班。", "explanation": "这里应该用〈员工〉。儿童指小孩子，不指公司里工作的人。"}, {"text": "他的爷爷是个儿童，今年七十岁。", "explanation": "这里应该用〈老人〉。儿童指小孩子，不能指七十岁的老人。"}, {"text": "我和儿童一起上班。", "explanation": "这里应该用〈同事〉。儿童指小孩子，不指一起工作的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园里有三只儿童在玩。", "corrected_sentence": "公园里有三个儿童在玩。", "error_description": "量词错误：“儿童”指人，应用“个”，不能用“只”，“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是儿童的的玩具。", "corrected_sentence": "这是儿童的玩具。", "error_description": "结构助词重复：“儿童的玩具”只用一个“的”，应说“这是儿童的玩具”，不能说“儿童的的玩具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
