INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39834, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "玩，做游戏。", "primary_collocate": null, "pronunciation": "wán shuǎ", "ipa": "wan˧˥ ʂwa˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子们在院子里玩耍。", "target_word": "玩耍", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末，弟弟在家门口玩耍。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了，孩子们又出来玩耍了。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友在沙地上玩耍，很开心。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在海边玩耍了一整天。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子需要时间玩耍和休息。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别在水边玩耍，那里很危险。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在房间里玩耍，玩完要把玩具收好。", "target_word": "玩耍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上快乐地玩耍。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐带着弟弟在公园里玩耍。", "target_word": "玩耍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "玩耍了", "label": "体标"}, {"form": "玩耍着", "label": "体标"}, {"form": "玩耍过", "label": "体标"}], "register": "中性", "sense_fingerprint": "玩，做游戏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e653b9f-1786-4a98-96fa-5c2fd7ba68c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玩耍", "is_correct": true, "explanation": "正确：“玩耍”指孩子在院子里做游戏，与“孩子们”“院子里”相合。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：“燃烧”指物体起火，不是孩子在院子里的活动。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”指制造物品，不是孩子在院子里的活动。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指来到世界，不能用作在院子里进行的活动。"}], "explanations": {"玩耍": "正确：“玩耍”指孩子在院子里做游戏，与“孩子们”“院子里”相合。", "燃烧": "语义：“燃烧”指物体起火，不是孩子在院子里的活动。", "生产": "语义：“生产”指制造物品，不是孩子在院子里的活动。", "出生": "语义：“出生”指来到世界，不能用作在院子里进行的活动。"}, "sentence_index": 0, "correct_answer": "玩耍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民每天在田里玩耍，种出了很多粮食。", "explanation": "这里应该用〈耕作〉。种粮食是农业劳动，玩耍指娱乐游戏，不能表示耕种。"}, {"text": "校长在礼堂里玩耍开学典礼。", "explanation": "这里应该用〈主持〉。“玩耍”是不及物动词，表示娱乐，不能带“典礼”作宾语。"}, {"text": "护士在病房里玩耍。", "explanation": "这里应该用〈照顾〉。玩耍不能用来描述照顾病人这类工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩耍", "is_correct": true, "explanation": "正确：“玩耍”指在水边做游戏，与“别在水边”的告诫相合。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指结束工作，与“别在水边”的告诫语境不合。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体状态，不能作为在水边进行的活动。"}, {"text": "坐月子", "is_correct": false, "explanation": "搭配：“坐月子”是固定说法，一般不说“在水边坐月子”。"}], "explanations": {"玩耍": "正确：“玩耍”指在水边做游戏，与“别在水边”的告诫相合。", "退休": "语义：“退休”指结束工作，与“别在水边”的告诫语境不合。", "发烧": "语义：“发烧”是身体状态，不能作为在水边进行的活动。", "坐月子": "搭配：“坐月子”是固定说法，一般不说“在水边坐月子”。"}, "sentence_index": 6, "correct_answer": "玩耍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵在阅兵场上玩耍。", "explanation": "这里应该用〈列队〉。阅兵是严肃场合，不能用“玩耍”来描述。"}, {"text": "厨师在厨房里玩耍。", "explanation": "这里应该用〈烹饪〉。玩耍是娱乐，不用于厨房里的烹饪工作。"}, {"text": "老师在讲台上玩耍。", "explanation": "这里应该用〈讲课〉。玩耍不用于教学活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们在草地上玩耍的很开心。", "corrected_sentence": "孩子们在草地上玩耍得很开心。", "error_description": "补语标记应用“得”，不能用“的”。程度补语紧跟在动词后面，应说“玩耍得很开心”，不能说“玩耍的很开心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹河边玩耍。", "corrected_sentence": "妹妹在河边玩耍。", "error_description": "处所状语要用“在”引出，应说“妹妹在河边玩耍”，不能省略“在”说“妹妹河边玩耍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
