INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指做游戏或进行娱乐活动。", "primary_collocate": null, "pronunciation": "wán shuǎ", "ipa": "wan˧˥ ʂwa˨˩˦", "syllable_count": 2, "sentences": [{"text": "木马让儿童的玩耍时光更加有趣。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "古罗马的孩子们很喜欢各种玩具，他们通过玩耍来学习和成长。", "target_word": "玩耍", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "古罗马的儿童也有玩耍的时间。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "孩子们在公园里玩耍。", "target_word": "玩耍", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下课后，同学们在操场上玩耍。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗和小猫在草地上一起玩耍。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们玩耍了一个下午，都累了。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不让孩子在马路上玩耍。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在河边玩耍着，笑声不断。", "target_word": "玩耍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我常和朋友在树下玩耍。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "玩耍了", "label": "体标"}, {"form": "玩耍着", "label": "体标"}, {"form": "玩耍过", "label": "体标"}], "register": "中性", "sense_fingerprint": "孩子等做游戏、进行娱乐活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e653b9f-1786-4a98-96fa-5c2fd7ba68c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玩耍", "is_correct": true, "explanation": "正确：“玩耍”指儿童做游戏、娱乐，与“木马”和“有趣”相合。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作”指劳动谋生，与儿童的“有趣”时光不符。"}, {"text": "劳动", "is_correct": false, "explanation": "搭配：“时光”多与“快乐”“童年”搭配，“劳动时光”不是常用说法。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是不愉快的状态，不能修饰“更加有趣”的时光。"}], "explanations": {"玩耍": "正确：“玩耍”指儿童做游戏、娱乐，与“木马”和“有趣”相合。", "工作": "语义：“工作”指劳动谋生，与儿童的“有趣”时光不符。", "劳动": "搭配：“时光”多与“快乐”“童年”搭配，“劳动时光”不是常用说法。", "生病": "语义：“生病”是不愉快的状态，不能修饰“更加有趣”的时光。"}, "sentence_index": 0, "correct_answer": "玩耍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们在工地上玩耍。", "explanation": "这里应该用〈劳动〉。玩耍指做游戏、娱乐，不用于工作场合。"}, {"text": "他每天在公司玩耍八个小时，挣钱养家。", "explanation": "这里应该用〈工作〉。挣钱养家靠的是工作，玩耍指娱乐游戏。"}, {"text": "学生们在考场上玩耍。", "explanation": "这里应该用〈考试〉。玩耍是轻松的娱乐，不能用来描述严肃的考试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩耍", "is_correct": true, "explanation": "正确：“玩耍”表示一段时间里做游戏，与“一个下午”“累了”相合。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”是一次性的事件，不能持续“一个下午”。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”是一次性的动作，不能说持续了一个下午。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”是一次性的事件，不能持续“一个下午”，也不会让人“都累了”。"}], "explanations": {"玩耍": "正确：“玩耍”表示一段时间里做游戏，与“一个下午”“累了”相合。", "出生": "语义：“出生”是一次性的事件，不能持续“一个下午”。", "迟到": "语义：“迟到”是一次性的动作，不能说持续了一个下午。", "结婚": "语义：“结婚”是一次性的事件，不能持续“一个下午”，也不会让人“都累了”。"}, "sentence_index": 6, "correct_answer": "玩耍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "信徒们在教堂里玩耍。", "explanation": "这里应该用〈祈祷〉。玩耍是轻松的娱乐，不用于宗教活动。"}, {"text": "人们在葬礼上玩耍。", "explanation": "这里应该用〈哀悼〉。葬礼是严肃场合，不能用“玩耍”来描述。"}, {"text": "警察每天在路口玩耍，维护交通秩序。", "explanation": "这里应该用〈执勤〉。维护交通秩序是警察的职责，玩耍指娱乐游戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们玩耍的很开心。", "corrected_sentence": "孩子们玩耍得很开心。", "error_description": "补语标记应用“得”，不能用“的”。程度补语紧跟在动词后面，应说“玩耍得很开心”，不能说“玩耍的很开心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
