INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不断流逝的时间本身，如“时光飞逝”。", "primary_collocate": null, "pronunciation": "shí guāng", "ipa": "ʂʐ̩˧˥ kuɑŋ˥", "syllable_count": 2, "sentences": [{"text": "时光过得真快，一年又过去了。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天和黑夜，都是时光的一部分。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起又落下，时光就这样走过。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要珍惜时光，不要浪费。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时光一天天过去，孩子长高了。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一天有二十四小时，时光不会停下来。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟表的指针转动，告诉我们时光在走。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春夏秋冬，时光不停地向前走。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时光慢慢地过去，天黑了。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天读书，不想浪费时光。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "時光", "label": "繁体"}, {"form": "时光机", "label": "复合"}], "register": "书面", "sense_fingerprint": "时光：不断流逝的时间本身（时光飞逝、珍惜时光）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d894458-c853-45d6-bca3-f85972cb2c8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时光", "is_correct": true, "explanation": "时光：不断流逝的时间本身，“时光过得真快”符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是流逝的时间，“天气过得真快”与句意不合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会“过得”快慢，与句中的时间流逝不相符。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本过得真快”的说法不成立，课本不能作为时间流逝的主语。"}], "explanations": {"时光": "时光：不断流逝的时间本身，“时光过得真快”符合句意。", "天气": "语义：天气不是流逝的时间，“天气过得真快”与句意不合。", "作业": "语义：作业不会“过得”快慢，与句中的时间流逝不相符。", "课本": "搭配：“课本过得真快”的说法不成立，课本不能作为时间流逝的主语。"}, "sentence_index": 0, "correct_answer": "时光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天没有时光去超市了，因为作业太多。", "explanation": "这里应该用〈时间〉。时光指不断流逝的时间本身，可支配的空闲要说时间。"}, {"text": "我们要珍惜一个时光，不要浪费。", "explanation": "这里应该用量词〈段〉。“一段时光”才是正确的说法。"}, {"text": "这个房间的时光很亮，照得人睁不开眼。", "explanation": "语义：时光不指光线，用来描述房间的亮度是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b734a76f-5a0e-4d61-a58c-2f56b139478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时光", "is_correct": true, "explanation": "时光：不断流逝的时间本身，“告诉我们时光在走”指时间在流逝，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会自己移动，“告诉我们桌子在走”与钟表指针的语境不合。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“在走”不能用于窗户，窗户不会行走。"}, {"text": "盐", "is_correct": false, "explanation": "语义：盐不是流逝的时间，“告诉我们盐在走”句意不通。"}], "explanations": {"时光": "时光：不断流逝的时间本身，“告诉我们时光在走”指时间在流逝，符合句意。", "桌子": "语义：桌子不会自己移动，“告诉我们桌子在走”与钟表指针的语境不合。", "窗户": "搭配：“在走”不能用于窗户，窗户不会行走。", "盐": "语义：盐不是流逝的时间，“告诉我们盐在走”句意不通。"}, "sentence_index": 6, "correct_answer": "时光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天读书，没有时光休息。", "explanation": "这里应该用〈时间〉。时光指不断流逝的时间本身，表示可以休息的空闲要说时间。"}, {"text": "他每天读书，一个时光都不想浪费。", "explanation": "这里应该用量词〈段〉，“一段时光”才是正确的说法。"}, {"text": "他的时光很亮，照亮了整个屋子。", "explanation": "语义：时光不指光线，用“时光很亮”来形容光线是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b734a76f-5a0e-4d61-a58c-2f56b139478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年时光得过很快。", "corrected_sentence": "这几年时光过得很快。", "error_description": "错误形式：“过得”后的补语结构颠倒，写成了“得过”。正确形式：应写作“过得很快”，补语“得”后接形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b734a76f-5a0e-4d61-a58c-2f56b139478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "日子一天天过去，时光不停得流走。", "corrected_sentence": "日子一天天过去，时光不停地流走。", "error_description": "错误形式：状语“不停”后用了“得”。正确形式：修饰动词“流走”的状语应用“地”，写作“不停地流走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b734a76f-5a0e-4d61-a58c-2f56b139478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
