INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "骑士是骑在马上打仗的勇士。", "primary_collocate": null, "pronunciation": "qí shì", "ipa": "tɕʰi˧˥ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "骑士骑着马冲向敌人。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位骑士在战场上打了很多仗。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争开始了，骑士们拿起长枪出发。", "target_word": "骑士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇敢的骑士举着长矛冲进敌人的队伍。", "target_word": "骑士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个骑士的马在战场上倒下了。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王派骑士去边境打仗。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑士用长剑挡住了敌人的进攻。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑士骑在高大的马背上作战。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人来了，骑士们骑马迎战。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一位在战场上冲锋的骑士。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "骑士精神", "label": "复合"}, {"form": "騎士", "label": "繁体"}], "register": "中性", "sense_fingerprint": "骑马作战的勇士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78836ff6-43bd-45b4-82eb-9adfdab50fcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39842, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士指骑马作战的勇士。"}, {"text": "其实", "is_correct": false, "explanation": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是「其实」（实际上）。"}, {"text": "气势", "is_correct": false, "explanation": "第一个音节 qì（第四声）与 qí（第二声）声调不同，意思是「气势」（气派与力量）。"}, {"text": "启示", "is_correct": false, "explanation": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启示」（引人领悟的道理）。"}, {"text": "情势", "is_correct": false, "explanation": "第一个音节 qíng 比 qí 多了 ng 韵尾，意思是「情势」（情况和形势）。"}], "explanations": {"骑士": "正确：骑士指骑马作战的勇士。", "其实": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是「其实」（实际上）。", "气势": "第一个音节 qì（第四声）与 qí（第二声）声调不同，意思是「气势」（气派与力量）。", "启示": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启示」（引人领悟的道理）。", "情势": "第一个音节 qíng 比 qí 多了 ng 韵尾，意思是「情势」（情况和形势）。"}, "sentence_index": null, "correct_answer": "骑士"}, "level_3": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士是骑马冲锋的战士，与「骑着马冲向敌人」相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能骑马冲向敌人。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有身体，不能骑马冲锋。"}, {"text": "马", "is_correct": false, "explanation": "配价：「骑」的施事必须是人，马不能作「骑」的主语。"}], "explanations": {"骑士": "正确：骑士是骑马冲锋的战士，与「骑着马冲向敌人」相符。", "书包": "语义：书包是物品，不能骑马冲向敌人。", "石头": "体貌：石头没有身体，不能骑马冲锋。", "马": "配价：「骑」的施事必须是人，马不能作「骑」的主语。"}, "sentence_index": 0, "correct_answer": "骑士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位骑士骑着马在草原上放羊。", "explanation": "这里应该用〈牧民〉。骑士指骑马打仗的勇士，在草原上骑马放羊的人要用牧民。"}, {"text": "这位骑士在手术室里给病人做手术。", "explanation": "这里应该用〈医生〉。骑士指骑马打仗的勇士，给病人做手术的人要用医生。"}, {"text": "这位骑士带着游客参观古城。", "explanation": "这里应该用〈导游〉。骑士指骑马打仗的勇士，带游客参观的人要用导游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39842, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士指骑马作战的勇士。"}, {"text": "骑师", "is_correct": false, "explanation": "第二个音节 shī（第一声）与 shì（第四声）声调不同，意思是「骑师」（职业赛马骑手）。"}, {"text": "启事", "is_correct": false, "explanation": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启事」（公开的通知文告）。"}, {"text": "集市", "is_correct": false, "explanation": "第一个音节 jí（第二声）与 qí 声母不同（j 与 q），意思是「集市」（定期交易的市场）。"}], "explanations": {"骑士": "正确：骑士指骑马作战的勇士。", "骑师": "第二个音节 shī（第一声）与 shì（第四声）声调不同，意思是「骑师」（职业赛马骑手）。", "启事": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启事」（公开的通知文告）。", "集市": "第一个音节 jí（第二声）与 qí 声母不同（j 与 q），意思是「集市」（定期交易的市场）。"}, "sentence_index": null, "correct_answer": "骑士"}, "level_3": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士是骑马作战的勇士，能用长剑挡住进攻。"}, {"text": "小猫", "is_correct": false, "explanation": "体貌：小猫的爪子和身体不能握住长剑，与「用长剑挡住」不符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能挥剑挡住进攻，与句子所述的战斗场景冲突。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：「用长剑挡住」的施事必须是能握剑的人，桌子不能作施事。"}], "explanations": {"骑士": "正确：骑士是骑马作战的勇士，能用长剑挡住进攻。", "小猫": "体貌：小猫的爪子和身体不能握住长剑，与「用长剑挡住」不符。", "花园": "语义：花园不能挥剑挡住进攻，与句子所述的战斗场景冲突。", "桌子": "配价：「用长剑挡住」的施事必须是能握剑的人，桌子不能作施事。"}, "sentence_index": 6, "correct_answer": "骑士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位骑士在画室里画了一幅肖像。", "explanation": "这里应该用〈画家〉。骑士指骑马打仗的勇士，在画室里作画的人要用画家。"}, {"text": "这位骑士每天在医院里给病人量血压。", "explanation": "这里应该用〈护士〉。骑士指骑马打仗的勇士，在医院里给病人量血压的人要用护士。"}, {"text": "这位骑士每天在教室里给学生上课。", "explanation": "这里应该用〈老师〉。骑士指骑马作战的勇士，在教室里给学生上课的人要用老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
