INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39843, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "骑士是古代欧洲骑在马上、穿着盔甲、为领主服务的战士。", "primary_collocate": null, "pronunciation": "qí shì", "ipa": "tɕʰi˧˥ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这个玩具帮助他们想象自己是勇敢的骑士，在广阔的土地上奔驰。", "target_word": "骑士", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "中世纪的欧洲骑士要保护国王和城堡。", "target_word": "骑士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位骑士穿着重重的盔甲走进城堡。", "target_word": "骑士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧洲的骑士要听领主的话。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑士的盔甲和剑都很重。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻的骑士向领主行礼。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代欧洲的骑士要先学会骑马。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位骑士为领主打了很多仗。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里有一套欧洲骑士的盔甲。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑士跪在国王面前，保证忠于领主。", "target_word": "骑士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "骑士精神", "label": "复合"}, {"form": "騎士", "label": "繁体"}], "register": "中性", "sense_fingerprint": "古代欧洲穿盔甲、为领主服务的战士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78836ff6-43bd-45b4-82eb-9adfdab50fcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39843, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士指古代欧洲骑马、穿盔甲、为领主服务的战士。"}, {"text": "其实", "is_correct": false, "explanation": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是「其实」（实际上）。"}, {"text": "气势", "is_correct": false, "explanation": "第一个音节 qì（第四声）与 qí（第二声）声调不同，意思是「气势」（气派与力量）。"}, {"text": "启示", "is_correct": false, "explanation": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启示」（引人领悟的道理）。"}, {"text": "情势", "is_correct": false, "explanation": "第一个音节 qíng 比 qí 多了 ng 韵尾，意思是「情势」（情况和形势）。"}], "explanations": {"骑士": "正确：骑士指古代欧洲骑马、穿盔甲、为领主服务的战士。", "其实": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是「其实」（实际上）。", "气势": "第一个音节 qì（第四声）与 qí（第二声）声调不同，意思是「气势」（气派与力量）。", "启示": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启示」（引人领悟的道理）。", "情势": "第一个音节 qíng 比 qí 多了 ng 韵尾，意思是「情势」（情况和形势）。"}, "sentence_index": null, "correct_answer": "骑士"}, "level_3": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士指骑马穿盔甲的战士，符合「勇敢」与「在土地上奔驰」的想象。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，不能“勇敢”，也不能在土地上奔驰。"}, {"text": "花朵", "is_correct": false, "explanation": "体貌：花朵没有能奔驰的身体，「奔驰」的主体不能是花。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：「勇敢」修饰能行动的人，不能修饰教室。"}], "explanations": {"骑士": "正确：骑士指骑马穿盔甲的战士，符合「勇敢」与「在土地上奔驰」的想象。", "雨伞": "语义：雨伞是物品，不能“勇敢”，也不能在土地上奔驰。", "花朵": "体貌：花朵没有能奔驰的身体，「奔驰」的主体不能是花。", "教室": "搭配：「勇敢」修饰能行动的人，不能修饰教室。"}, "sentence_index": 0, "correct_answer": "骑士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位骑士每天在工厂里组装汽车。", "explanation": "这里应该用〈工人〉。骑士指古代为领主打仗的战士，在工厂组装汽车的人要用工人。"}, {"text": "这位骑士每天在厨房里炒菜。", "explanation": "这里应该用〈厨师〉。骑士指古代为领主打仗的战士，在厨房里炒菜的人要用厨师。"}, {"text": "这位骑士每天开车送孩子上学。", "explanation": "这里应该用〈司机〉。骑士指骑马的战士，开车送孩子上学的人要用司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39843, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士指古代欧洲骑马、穿盔甲、为领主服务的战士。"}, {"text": "骑师", "is_correct": false, "explanation": "第二个音节 shī（第一声）与 shì（第四声）声调不同，意思是「骑师」（职业赛马骑手）。"}, {"text": "启事", "is_correct": false, "explanation": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启事」（公开的通知文告）。"}, {"text": "集市", "is_correct": false, "explanation": "第一个音节 jí（第二声）与 qí 声母不同（j 与 q），意思是「集市」（定期交易的市场）。"}], "explanations": {"骑士": "正确：骑士指古代欧洲骑马、穿盔甲、为领主服务的战士。", "骑师": "第二个音节 shī（第一声）与 shì（第四声）声调不同，意思是「骑师」（职业赛马骑手）。", "启事": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启事」（公开的通知文告）。", "集市": "第一个音节 jí（第二声）与 qí 声母不同（j 与 q），意思是「集市」（定期交易的市场）。"}, "sentence_index": null, "correct_answer": "骑士"}, "level_3": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士是古代欧洲的战士，「学会骑马」正是他们的训练内容。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能学会骑马。"}, {"text": "小猫", "is_correct": false, "explanation": "体貌：小猫的身体不能骑马，与「学会骑马」的主体不符。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：「学会骑马」的主体应是人，不能说花园学会骑马。"}], "explanations": {"骑士": "正确：骑士是古代欧洲的战士，「学会骑马」正是他们的训练内容。", "桌子": "语义：桌子是家具，不能学会骑马。", "小猫": "体貌：小猫的身体不能骑马，与「学会骑马」的主体不符。", "花园": "搭配：「学会骑马」的主体应是人，不能说花园学会骑马。"}, "sentence_index": 6, "correct_answer": "骑士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位骑士在画布上画了一幅风景。", "explanation": "这里应该用〈画家〉。骑士指古代为领主打仗的战士，在画布上画风景的人要用画家。"}, {"text": "这位骑士每天在银行里帮客户存钱。", "explanation": "这里应该用〈职员〉。骑士指古代为领主服务的战士，在银行帮客户存钱的人要用职员。"}, {"text": "这位骑士每天给病人打针。", "explanation": "这里应该用〈护士〉。骑士指古代为领主打仗的战士，给病人打针的人要用护士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只骑士披着沉重的盔甲走进城堡。", "corrected_sentence": "那位骑士披着沉重的盔甲走进城堡。", "error_description": "「骑士」指人，量词应用「位」，不能用「只」。错误在「那只」，应改为「那位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个位骑士在宫廷里向国王行礼。", "corrected_sentence": "那位骑士在宫廷里向国王行礼。", "error_description": "错误：“那个”与“位”两个量词重复使用，同一名词只用一个量词。正确应为“那位骑士”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭窄", "is_correct": true, "explanation": "反义：「狭窄」指场地或空间窄小，与「很大很宽」相对。"}, {"text": "灵活", "is_correct": false, "explanation": "「灵活」形容动作或思路敏捷，与场地大小无关，不是反义词。"}, {"text": "柔和", "is_correct": false, "explanation": "「柔和」形容光线、声音或态度温和，与场地大小无关，不是反义词。"}, {"text": "缓慢", "is_correct": false, "explanation": "「缓慢」形容速度慢，与场地大小无关，不是反义词。"}], "correct_answer": "狭窄", "explanations": {"狭窄": "反义：「狭窄」指场地或空间窄小，与「很大很宽」相对。", "灵活": "「灵活」形容动作或思路敏捷，与场地大小无关，不是反义词。", "柔和": "「柔和」形容光线、声音或态度温和，与场地大小无关，不是反义词。", "缓慢": "「缓慢」形容速度慢，与场地大小无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭窄", "is_correct": true, "explanation": "反义：「狭窄」指场地或空间窄小，与「很大很宽」相对。"}, {"text": "明亮", "is_correct": false, "explanation": "「明亮」形容光线充足或颜色鲜明，与场地大小无关，不是反义词。"}, {"text": "繁忙", "is_correct": false, "explanation": "「繁忙」形容事务多、忙碌，与场地大小无关，不是反义词。"}, {"text": "粗糙", "is_correct": false, "explanation": "「粗糙」形容表面不光滑，与场地大小无关，不是反义词。"}], "correct_answer": "狭窄", "explanations": {"狭窄": "反义：「狭窄」指场地或空间窄小，与「很大很宽」相对。", "明亮": "「明亮」形容光线充足或颜色鲜明，与场地大小无关，不是反义词。", "繁忙": "「繁忙」形容事务多、忙碌，与场地大小无关，不是反义词。", "粗糙": "「粗糙」形容表面不光滑，与场地大小无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很大很宽的地方。", "primary_collocate": null, "pronunciation": "guǎng kuò", "ipa": "kwɑŋ˨˩˦ kʰwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们喜欢在广阔的操场上玩。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个广场很广阔，能站几万人。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想去外面看看广阔的世界。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座广阔的牧场可以养很多牛羊。", "target_word": "广阔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市有广阔的公园和绿地。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广阔的空间让人觉得很自由。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山后是一片广阔的地方，没有一间房子。", "target_word": "广阔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在广阔的雪地中间，他觉得自己很小。", "target_word": "广阔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么广阔的地方，可以建一个大公园。", "target_word": "广阔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跑进广阔的田野里玩。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "广阔无边", "label": "复合"}, {"form": "广阔天地", "label": "复合"}, {"form": "廣闊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "场地、空间很大很宽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78836ff6-43bd-45b4-82eb-9adfdab50fcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "广阔", "is_correct": true, "explanation": "正确：广阔指场地很大很宽，与「在操场上玩」的场景相合。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：陡峭说地势斜而高，与平坦的操场不符。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：「聪明」修饰人或头脑，不能修饰操场。"}, {"text": "低矮", "is_correct": false, "explanation": "体貌：低矮形容物体外形矮小，操场是大面积场地，不能这样形容。"}], "explanations": {"广阔": "正确：广阔指场地很大很宽，与「在操场上玩」的场景相合。", "陡峭": "语义：陡峭说地势斜而高，与平坦的操场不符。", "聪明": "搭配：「聪明」修饰人或头脑，不能修饰操场。", "低矮": "体貌：低矮形容物体外形矮小，操场是大面积场地，不能这样形容。"}, "sentence_index": 0, "correct_answer": "广阔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的价格很广阔，大家都买不起。", "explanation": "这里应该用〈昂贵〉。广阔形容很大很宽的场地，价格的高低要用昂贵。"}, {"text": "他的力气很广阔，一个人能拉动一辆车。", "explanation": "这里应该用〈强大〉。广阔形容很大很宽的场地，力气的大小要用强大。"}, {"text": "这一小块饼很广阔，我们一口就吃完了。", "explanation": "这里应该用〈小〉。广阔指很大很宽的地方，一小块饼不能用广阔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "广阔", "is_correct": true, "explanation": "正确：广阔指很大很宽，与「没有一间房子」的空旷场景相符。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：拥挤说人或物太多，与「没有一间房子」的空旷场景矛盾。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：繁华指商业兴旺、建筑众多，与「没有一间房子」矛盾。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：「高耸」多修饰山峰或建筑，说「一片高耸的地方」不通。"}], "explanations": {"广阔": "正确：广阔指很大很宽，与「没有一间房子」的空旷场景相符。", "拥挤": "语义：拥挤说人或物太多，与「没有一间房子」的空旷场景矛盾。", "繁华": "语义：繁华指商业兴旺、建筑众多，与「没有一间房子」矛盾。", "高耸": "搭配：「高耸」多修饰山峰或建筑，说「一片高耸的地方」不通。"}, "sentence_index": 6, "correct_answer": "广阔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台大型机器很广阔，占满了整个车间。", "explanation": "这里应该用〈庞大〉。广阔形容很大很宽的场地，机器这样的实体要用庞大。"}, {"text": "这次会议的时间很广阔，开了一整天。", "explanation": "这里应该用〈漫长〉。广阔形容很大很宽的场地，时间的长短要用漫长。"}, {"text": "这双鞋很广阔，我穿着太松了。", "explanation": "这里应该用〈宽大〉。广阔形容很大很宽的场地，衣服、鞋子大要用宽大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片田野广阔地很，孩子们可以尽情奔跑。", "corrected_sentence": "这片田野广阔得很，孩子们可以尽情奔跑。", "error_description": "「广阔得很」是形容词加补语结构，要用「得」，不能用「地」。错误在「广阔地很」，应改为「广阔得很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在广阔地场地上踢球。", "corrected_sentence": "孩子们在广阔的场地上踢球。", "error_description": "「广阔」作定语应用「的」，「地」用于动词前修饰动作。错误在「广阔地场地」，应改为「广阔的场地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
