INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39847, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形容马或车等快速奔跑", "primary_collocate": null, "pronunciation": "bēn chí", "ipa": "pən˥ ʈʂʰʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这个玩具帮助他们想象自己是勇敢的骑士，在广阔的土地上奔驰。", "target_word": "奔驰", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "一匹白马在草原上奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车在铁路上飞快地奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骏马奔驰着，向远方跑去。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车在高速公路上奔驰了一天。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "马群在草地上奔驰，声音很大。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "列车奔驰过一座又一座大山。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黑色的马奔驰在雪地上。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一辆红色的车在公路上奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑着马向前奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "奔驰着", "label": "体标"}, {"form": "奔驰了", "label": "体标"}, {"form": "奔驰过", "label": "体标"}, {"form": "奔馳", "label": "繁体"}], "register": "中性", "sense_fingerprint": "马或车辆快速奔跑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78836ff6-43bd-45b4-82eb-9adfdab50fcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打印", "is_correct": false, "explanation": "语义：“打印”要以纸张或设备为对象，不能在广阔的土地上进行。"}, {"text": "奔驰", "is_correct": true, "explanation": "“奔驰”指马或车快速奔跑，与骑士在广阔土地上奔驰的情境相符。"}, {"text": "缝补", "is_correct": false, "explanation": "配价：“缝补”需要衣物之类的受事宾语，句中没有可缝补的对象。"}, {"text": "下载", "is_correct": false, "explanation": "语义：“下载”指从网络获取文件，与广阔土地和想象骑士的语境无关。"}], "explanations": {"打印": "语义：“打印”要以纸张或设备为对象，不能在广阔的土地上进行。", "奔驰": "“奔驰”指马或车快速奔跑，与骑士在广阔土地上奔驰的情境相符。", "缝补": "配价：“缝补”需要衣物之类的受事宾语，句中没有可缝补的对象。", "下载": "语义：“下载”指从网络获取文件，与广阔土地和想象骑士的语境无关。"}, "sentence_index": 0, "correct_answer": "奔驰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子在教室里奔驰。", "explanation": "这里应该用〈挪动〉。「奔驰」指马或车快速奔跑，椅子不能自己跑动，要说「挪动」。"}, {"text": "这匹老马慢慢地奔驰到草场上。", "explanation": "这里应该用〈走〉。“奔驰”指快速奔跑，与“慢慢地”的缓慢意思矛盾；缓慢移动要说“走”。"}, {"text": "这只蜗牛在草地上奔驰。", "explanation": "这里应该用〈爬〉。“奔驰”指快速奔跑，蜗牛行动极慢，要说“爬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉睡", "is_correct": false, "explanation": "语义：列车不会沉睡，句子描写的是快速经过群山。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：列车不会歌唱，句子描写的是快速经过群山。"}, {"text": "生长", "is_correct": false, "explanation": "配价：“生长”是不及物动词，不能带“大山”作宾语来表示经过。"}, {"text": "奔驰", "is_correct": true, "explanation": "“奔驰”指快速移动，与列车飞快经过一座又一座大山的语境相符。"}], "explanations": {"沉睡": "语义：列车不会沉睡，句子描写的是快速经过群山。", "歌唱": "语义：列车不会歌唱，句子描写的是快速经过群山。", "生长": "配价：“生长”是不及物动词，不能带“大山”作宾语来表示经过。", "奔驰": "“奔驰”指快速移动，与列车飞快经过一座又一座大山的语境相符。"}, "sentence_index": 6, "correct_answer": "奔驰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子在屋子里奔驰。", "explanation": "这里应该用〈挪动〉。“奔驰”指马、车等快速跑动，桌子不能自己移动，要说“挪动”。"}, {"text": "这块石头从山坡上奔驰下来。", "explanation": "这里应该用〈滚〉。“奔驰”指马、车等快速跑动，石头只能滚落，要说“滚”。"}, {"text": "这匹马在草地上奔驰，一动也不动。", "explanation": "这里应该用〈站着〉。“奔驰”指快速跑动，与“一动也不动”的静止意思矛盾；静止要说“站着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那匹白马在草原上很奔驰。", "corrected_sentence": "那匹白马在草原上奔驰。", "error_description": "错误形式：“很奔驰”。正确形式：“奔驰”前不加“很”。“奔驰”是动词，不能像形容词一样用程度副词“很”修饰，应说“在草原上奔驰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那群马在雪地上奔驰了着。", "corrected_sentence": "那群马在雪地上奔驰着。", "error_description": "错误形式：“奔驰了着”，动词后同时带“了”和“着”两个体标。正确形式：“奔驰着”。表示动作正在持续，只用动态助词“着”即可，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同之处", "is_correct": true, "explanation": "“不同之处”指两者不一样的地方，与“相似之处”相对。"}, {"text": "优点", "is_correct": false, "explanation": "“优点”指好的方面，与“相似之处”没有反义关系。"}, {"text": "原因", "is_correct": false, "explanation": "“原因”指事情发生的缘由，与“相似之处”没有反义关系。"}, {"text": "办法", "is_correct": false, "explanation": "“办法”指解决问题的方式，与“相似之处”没有反义关系。"}], "correct_answer": "不同之处", "explanations": {"不同之处": "“不同之处”指两者不一样的地方，与“相似之处”相对。", "优点": "“优点”指好的方面，与“相似之处”没有反义关系。", "原因": "“原因”指事情发生的缘由，与“相似之处”没有反义关系。", "办法": "“办法”指解决问题的方式，与“相似之处”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同之处", "is_correct": true, "explanation": "“不同之处”指两者不一样的地方，与“相似之处”相对。"}, {"text": "答案", "is_correct": false, "explanation": "“答案”指问题的解答，与“相似之处”没有反义关系。"}, {"text": "步骤", "is_correct": false, "explanation": "“步骤”指做事的先后环节，与“相似之处”没有反义关系。"}, {"text": "作用", "is_correct": false, "explanation": "“作用”指事物产生的效果，与“相似之处”没有反义关系。"}], "correct_answer": "不同之处", "explanations": {"不同之处": "“不同之处”指两者不一样的地方，与“相似之处”相对。", "答案": "“答案”指问题的解答，与“相似之处”没有反义关系。", "步骤": "“步骤”指做事的先后环节，与“相似之处”没有反义关系。", "作用": "“作用”指事物产生的效果，与“相似之处”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指两个或更多事物之间相同或类似的部分。", "primary_collocate": null, "pronunciation": "xiāng sì zhī chù", "ipa": "ɕjɑŋ˥ sɨ˥˩ ʈʂɨ˥ ʈʂʰu˥˩", "syllable_count": 4, "sentences": [{"text": "在古罗马，孩子们的日常生活和今天的孩子有些不同，但也有相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这两本书有很多相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国菜和意大利菜有哪些相似之处？", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐妹俩的性格有一个相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说说这两个城市的相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的相似之处是都爱运动。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到这两张画的相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语和日语在文字上有相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种动物的相似之处不多。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比较两个故事，你发现了哪些相似之处？", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "多个事物之间相同或类似的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c71fde6-0539-4dbc-ab5a-4c8d08a9070a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相似之处", "is_correct": true, "explanation": "“相似之处”指两者相同或类似的部分，与前句“有些不同”形成转折，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：古罗马没有手机，与句首“在古罗马”的时代背景冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：古罗马没有汽车，与“在古罗马”的背景不符。"}, {"text": "时代", "is_correct": false, "explanation": "语义：“也有时代”说不通，与比较古今生活的句意不符。"}], "explanations": {"相似之处": "“相似之处”指两者相同或类似的部分，与前句“有些不同”形成转折，符合句意。", "手机": "语义：古罗马没有手机，与句首“在古罗马”的时代背景冲突。", "汽车": "语义：古罗马没有汽车，与“在古罗马”的背景不符。", "时代": "语义：“也有时代”说不通，与比较古今生活的句意不符。"}, "sentence_index": 0, "correct_answer": "相似之处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个苹果的相似之处是一个大，一个小。", "explanation": "这里应该用〈不同之处〉。“相似之处”指相同或类似的部分，“一个大，一个小”说的是区别。"}, {"text": "哥哥和弟弟的相似之处是哥哥高，弟弟矮。", "explanation": "这里应该用〈不同之处〉。“哥哥高，弟弟矮”是区别，不是相似的地方。"}, {"text": "这家饭馆的相似之处是菜很便宜。", "explanation": "这里应该用〈特点〉。“相似之处”要比较两个或更多事物，只说一家饭馆不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相似之处", "is_correct": true, "explanation": "“相似之处”与“找不到”搭配，指两张画之间相同或类似的部分，符合句意。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：画作没有音乐，与句中的“这两张画”对象不符。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：画作没有温度，不能说“这两张画的温度”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不能说画的体重。"}], "explanations": {"相似之处": "“相似之处”与“找不到”搭配，指两张画之间相同或类似的部分，符合句意。", "音乐": "语义：画作没有音乐，与句中的“这两张画”对象不符。", "温度": "搭配：画作没有温度，不能说“这两张画的温度”。", "体重": "搭配：“体重”用于人或动物，不能说画的体重。"}, "sentence_index": 6, "correct_answer": "相似之处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个故事的相似之处是结局不同。", "explanation": "这里应该用〈区别〉。“相似之处”指相同或类似的部分，后面接“结局不同”，前后自相矛盾，应说“区别”。"}, {"text": "两所学校的相似之处是校风不同。", "explanation": "这里应该用〈差异〉。“相似之处”后接“校风不同”，前后矛盾，应说“差异”。"}, {"text": "这两种茶的相似之处是口味不同。", "explanation": "这里应该用〈差别〉。“相似之处”后接“口味不同”，前后矛盾，应说“差别”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两部电影有一只相似之处：主角都是老师。", "corrected_sentence": "这两部电影有一个相似之处：主角都是老师。", "error_description": "量词错误：“只”用于动物等，不能修饰“相似之处”，应说“一个相似之处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两所学校很多相似之处。", "corrected_sentence": "这两所学校有很多相似之处。", "error_description": "漏掉动词“有”：表示存在的“有”不能省，应说“有很多相似之处”，不说“很多相似之处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
