INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39853, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指男性儿童，与女孩相对。", "primary_collocate": null, "pronunciation": "nán hái", "ipa": "nan˧˥ xaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "古罗马的家庭非常重视孩子们的教育，尤其是男孩。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "那个男孩在公园里踢足球。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有一个男孩和一个女孩。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男孩今年八岁了。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩把书包放在桌子上。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个穿红衣服的男孩是我弟弟。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问男孩哪里不舒服。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩笑着跑向妈妈。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男孩很爱看书。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请男孩站起来回答问题。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "男孩子", "label": "复合"}], "register": "中性", "sense_fingerprint": "男性儿童，与女孩相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c71fde6-0539-4dbc-ab5a-4c8d08a9070a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男孩", "is_correct": true, "explanation": "男孩：指男性儿童，与前文“孩子们的教育”的语境相符。"}, {"text": "男人", "is_correct": false, "explanation": "语义：“男人”指成年男性，与“孩子们的教育”的语境不符。"}, {"text": "老人", "is_correct": false, "explanation": "语义：“老人”指年长的人，与“孩子们”的教育不相关，不能放在“尤其是”之后。"}, {"text": "男士", "is_correct": false, "explanation": "语域：“男士”是对成年男子的礼貌称呼，与讨论儿童教育的语境不协调。"}], "explanations": {"男孩": "男孩：指男性儿童，与前文“孩子们的教育”的语境相符。", "男人": "语义：“男人”指成年男性，与“孩子们的教育”的语境不符。", "老人": "语义：“老人”指年长的人，与“孩子们”的教育不相关，不能放在“尤其是”之后。", "男士": "语域：“男士”是对成年男子的礼貌称呼，与讨论儿童教育的语境不协调。"}, "sentence_index": 0, "correct_answer": "男孩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个男孩每个月按时还房贷。", "explanation": "这里应该用〈男人〉。男孩指男性儿童，不能用来指每个月还房贷的成年男子。"}, {"text": "我昨天在公园看见那位男孩的妻子。", "explanation": "这里应该用〈男人〉。男孩指男性儿童，不能用来指已经结婚、有妻子的成年男子。"}, {"text": "这位男孩上个月刚刚退休。", "explanation": "这里应该用〈老人〉或〈老先生〉。男孩指男性儿童，不能用来指已经退休的成年男子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男孩", "is_correct": true, "explanation": "男孩：指男性儿童，能够被医生询问哪里不舒服。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是没有感觉的物体，不能被医生问哪里不舒服。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“问”的对象要求是有生命的人，“空气”不能作受问的对象。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不会感到不舒服，与“医生问”的对象不符。"}], "explanations": {"男孩": "男孩：指男性儿童，能够被医生询问哪里不舒服。", "桌子": "语义：“桌子”是没有感觉的物体，不能被医生问哪里不舒服。", "空气": "配价：“问”的对象要求是有生命的人，“空气”不能作受问的对象。", "书包": "语义：“书包”是物品，不会感到不舒服，与“医生问”的对象不符。"}, "sentence_index": 6, "correct_answer": "男孩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位男孩在军队里当了二十年的上校。", "explanation": "这里应该用〈军官〉。男孩指男性儿童，不能用来指在军队里任职二十年的成年军官。"}, {"text": "这位男孩每天开车送我上班。", "explanation": "这里应该用〈司机〉。男孩指儿童，不能用来指每天开车的司机。"}, {"text": "这位男孩每周在医院值夜班。", "explanation": "这里应该用〈医生〉。男孩指儿童，不能用来指在医院值夜班的成年医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只男孩每天早上自己刷牙。", "corrected_sentence": "这个男孩每天早上自己刷牙。", "error_description": "“男孩”指人，量词应用“个”，不能用“只”（“只”多用于动物或单件物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室里有三个男孩们在画画。", "corrected_sentence": "教室里有三个男孩在画画。", "error_description": "“男孩”前已有数量词“三个”，不能再加“们”，应说“三个男孩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
