INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39855, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指阅读和书写的能力或行为。", "primary_collocate": null, "pronunciation": "dú xiě", "ipa": "tu˧˥ ɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们通常会去学校学习读写和算术。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "孩子上学以后，读写慢慢变好了。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的学生读写都不错。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好读写需要每天练习。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的读写比口语好。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很注意孩子的读写。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读写是学习语言的基础。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国学生的读写常常比听说难。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小读写很好。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书能帮你练习读写。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "读写能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "阅读和书写的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c71fde6-0539-4dbc-ab5a-4c8d08a9070a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39855, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "读写", "is_correct": true, "explanation": "读写：指阅读和书写的能力，与“学习……和算术”相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不是可以学习的内容，与“学习”搭配不成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是可以学习的内容。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不是可以学习的内容，与“学习”搭配不成立。"}], "explanations": {"读写": "读写：指阅读和书写的能力，与“学习……和算术”相符。", "太阳": "语义：太阳不是可以学习的内容，与“学习”搭配不成立。", "冰箱": "语义：冰箱是家电，不是可以学习的内容。", "云朵": "语义：云朵不是可以学习的内容，与“学习”搭配不成立。"}, "sentence_index": 0, "correct_answer": "读写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆的读写很好吃。", "explanation": "这里应该用〈饭菜〉。读写指阅读和书写的能力，不能用来形容食物的味道。"}, {"text": "这篇文章的读写很精彩。", "explanation": "这里应该用〈写作〉。读写指阅读和书写的能力，不是文章的写作水平或风格。"}, {"text": "这家公司的读写非常稳定。", "explanation": "这里应该用〈经营〉。读写指阅读和书写的能力或行为，不能用来说公司的经营状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "读写", "is_correct": true, "explanation": "读写：指阅读和书写的能力，是“基础”的合适主语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与学习语言无关，不能作“学习语言的基础”的主语。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是物品，与学习语言无关，不能作“基础”的主语。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指外形特征，与学习语言的基础无关。"}], "explanations": {"读写": "读写：指阅读和书写的能力，是“基础”的合适主语。", "天气": "语义：天气与学习语言无关，不能作“学习语言的基础”的主语。", "鞋子": "语义：鞋子是物品，与学习语言无关，不能作“基础”的主语。", "身高": "体貌：“身高”指外形特征，与学习语言的基础无关。"}, "sentence_index": 6, "correct_answer": "读写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的读写是硕士。", "explanation": "这里应该用〈学历〉。读写指阅读和书写的能力，不能用来说明受教育的程度。"}, {"text": "他的读写一米八。", "explanation": "这里应该用〈身高〉。读写是能力，不能用数值来表示身高。"}, {"text": "她的读写是三十岁。", "explanation": "这里应该用〈年龄〉。读写指阅读和书写的能力，不能用来表示年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在学校学了一个读写。", "corrected_sentence": "他在学校学了读写。", "error_description": "“读写”是表示能力的抽象名词，不能用量词“个”来计数，应去掉“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子的读写们很好。", "corrected_sentence": "这个孩子的读写很好。", "error_description": "“读写”此处是名词（阅读和书写的能力），属抽象名词，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
