INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39857, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "算术是数学中最基础的部分，包括加、减、乘、除等运算。", "primary_collocate": null, "pronunciation": "suàn shù", "ipa": "suan˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他们通常会去学校学习读写和算术。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "算术是数学里最基础的部分。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子上小学后，先学算术，再学代数。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "算术里有加、减、乘、除四种运算。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的算术很好，不用计算器也能算对。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上午我们学语文，下午学算术。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数学比算术复杂得多。", "target_word": "算术", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古代的商人都需要懂一点算术。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书讲的是最简单的算术。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就喜欢算术，不怕数字。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "算術", "label": "繁体"}, {"form": "算术题", "label": "复合"}], "register": "中性", "sense_fingerprint": "算术：数学中最基础的部分，含加减乘除运算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d76871c-acf7-4b48-b16d-14696abcf71b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "算术", "is_correct": true, "explanation": "正确：suàn shù，指数学中最基础的加、减、乘、除运算。"}, {"text": "算是", "is_correct": false, "explanation": "算是（suàn shì）与算术（suàn shù）只有第二音节韵母不同（shì 与 shù），意思是“算作”。"}, {"text": "算出", "is_correct": false, "explanation": "算出（suàn chū）与算术（suàn shù）第一音节相同，第二音节声母（ch 与 sh）和声调不同，意思是“计算得出”。"}, {"text": "战术", "is_correct": false, "explanation": "战术（zhàn shù）与算术（suàn shù）第一音节声母不同（zh 与 s），意思是作战的方法。"}, {"text": "算书", "is_correct": false, "explanation": "算书（suàn shū）与算术（suàn shù）第一音节相同，第二音节只差声调（阴平与去声），意思是古代的数学书。"}], "explanations": {"算术": "正确：suàn shù，指数学中最基础的加、减、乘、除运算。", "算是": "算是（suàn shì）与算术（suàn shù）只有第二音节韵母不同（shì 与 shù），意思是“算作”。", "算出": "算出（suàn chū）与算术（suàn shù）第一音节相同，第二音节声母（ch 与 sh）和声调不同，意思是“计算得出”。", "战术": "战术（zhàn shù）与算术（suàn shù）第一音节声母不同（zh 与 s），意思是作战的方法。", "算书": "算书（suàn shū）与算术（suàn shù）第一音节相同，第二音节只差声调（阴平与去声），意思是古代的数学书。"}, "sentence_index": null, "correct_answer": "算术"}, "level_3": {"options": [{"text": "算术", "is_correct": true, "explanation": "正确：“读写和算术”是学校最基础的两类内容，符合句意。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不是可以学习的科目，“学习……”后面不能接“体温”。"}, {"text": "微积分", "is_correct": false, "explanation": "语义：微积分属于高等数学，与“读写”并列时层次不合，句中指的是最基础的学科。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能作为学习的对象，与“学习读写和……”不搭。"}], "explanations": {"算术": "正确：“读写和算术”是学校最基础的两类内容，符合句意。", "体温": "搭配：“体温”不是可以学习的科目，“学习……”后面不能接“体温”。", "微积分": "语义：微积分属于高等数学，与“读写”并列时层次不合，句中指的是最基础的学科。", "天气": "搭配：“天气”不能作为学习的对象，与“学习读写和……”不搭。"}, "sentence_index": 0, "correct_answer": "算术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把算术放进冰箱里保存。", "explanation": "这里应该用〈食物〉。算术是学科名称，不是实物，不能放进冰箱保存。"}, {"text": "他把算术穿在身上去上学。", "explanation": "这里应该用〈衣服〉。算术是学科名称，不是衣物，不能穿在身上。"}, {"text": "他很会打算术。", "explanation": "这里应该用〈算盘〉。常说“打算盘”；算术是学科名称，不能说“打算术”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39857, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "算术", "is_correct": true, "explanation": "正确：算术是数学中最基础的部分，拿来与“数学”比较复杂程度，符合句意。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”是人的外在形体，不能拿来与学科比较复杂程度。"}, {"text": "红绿灯", "is_correct": false, "explanation": "语义：红绿灯与数学不是同类事物，无法比较复杂程度。"}, {"text": "纸张", "is_correct": false, "explanation": "语义：纸张是普通物品，与数学之间没有可以比较的复杂程度。"}], "explanations": {"算术": "正确：算术是数学中最基础的部分，拿来与“数学”比较复杂程度，符合句意。", "身材": "体貌：“身材”是人的外在形体，不能拿来与学科比较复杂程度。", "红绿灯": "语义：红绿灯与数学不是同类事物，无法比较复杂程度。", "纸张": "语义：纸张是普通物品，与数学之间没有可以比较的复杂程度。"}, "sentence_index": 6, "correct_answer": "算术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天下午用算术画画。", "explanation": "这里应该用〈画笔〉。算术是学科名称，不是绘画工具，不能用来画画。"}, {"text": "他的算术很有礼貌。", "explanation": "这里应该用〈态度〉。算术是学科名称，不能用来形容人的品行，“有礼貌”应搭配“态度”。"}, {"text": "他很快地算术这些数字。", "explanation": "这里应该用〈计算〉。算术是名词，指数学中最基础的运算，不能直接当动词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小学时每天都二十道算术题。", "corrected_sentence": "他小学时每天都做二十道算术题。", "error_description": "错误：“都二十道算术题”缺少动词。应为“都做二十道算术题”。“算术题”前要用动词“做”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从小就学了算术的。", "corrected_sentence": "他从小就学了算术。", "error_description": "错误：句末多出“的”。应为“他从小就学了算术。”。“学了算术”后面不能直接加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
