INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蜡板是一种可以在上面写字的板子。", "primary_collocate": null, "pronunciation": "là bǎn", "ipa": "la˥˩ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "蜡板是一种可以写字的板子。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在蜡板上写下了自己的名字。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那块蜡板已经很旧了。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "罗马人常常带着蜡板出门。", "target_word": "蜡板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩拿着蜡板，认真地写字。", "target_word": "蜡板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一块蜡板和一支笔。", "target_word": "蜡板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把要买的东西记在蜡板上。", "target_word": "蜡板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜡板的表面有一层蜡。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把蜡板递给我。", "target_word": "蜡板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人从箱子里拿出一块旧蜡板。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "蠟板", "label": "繁体"}, {"form": "块", "label": "量词"}], "register": "中性", "sense_fingerprint": "蜡板：可以在上面写字的板子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d76871c-acf7-4b48-b16d-14696abcf71b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜡板", "is_correct": true, "explanation": "正确：蜡板是可以在上面写字的板子，符合句意。"}, {"text": "纸张", "is_correct": false, "explanation": "语义：纸不是板子，与“一种可以写字的板子”不合。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，不是可以写字的板子。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：墨水是液体，不能说“是一种板子”，主语与谓语不搭配。"}], "explanations": {"蜡板": "正确：蜡板是可以在上面写字的板子，符合句意。", "纸张": "语义：纸不是板子，与“一种可以写字的板子”不合。", "钢笔": "语义：钢笔是书写工具，不是可以写字的板子。", "墨水": "搭配：墨水是液体，不能说“是一种板子”，主语与谓语不搭配。"}, "sentence_index": 0, "correct_answer": "蜡板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只蜡板已经很旧了。", "explanation": "这里应该用〈块〉。“只”多用于动物等，蜡板是平板，应用“块”。"}, {"text": "小孩用蜡板盛粥。", "explanation": "这里应该用〈碗〉。蜡板不能盛装食物，应该用碗盛粥。"}, {"text": "罗马人常常穿着蜡板出门。", "explanation": "这里应该用〈铠甲〉。蜡板不能穿在身上，“穿着”只搭配衣物、铠甲等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜡板", "is_correct": true, "explanation": "正确：要买的东西记在可以写字的蜡板上，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：东西不能记在空气上，“记在……上”需要可以承载书写的平面。"}, {"text": "水面", "is_correct": false, "explanation": "语义：水面不能用来记东西，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能用来记录东西，与“记在……上”不合。"}], "explanations": {"蜡板": "正确：要买的东西记在可以写字的蜡板上，符合句意。", "空气": "搭配：东西不能记在空气上，“记在……上”需要可以承载书写的平面。", "水面": "语义：水面不能用来记东西，句意不通。", "天空": "语义：天空不能用来记录东西，与“记在……上”不合。"}, "sentence_index": 6, "correct_answer": "蜡板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人对着蜡板梳头。", "explanation": "这里应该用〈镜子〉。蜡板不能用来照看或梳头。"}, {"text": "下雨了，他撑着蜡板走出门。", "explanation": "这里应该用〈雨伞〉。蜡板不能用来遮雨，应该撑雨伞。"}, {"text": "老人打开蜡板看节目。", "explanation": "这里应该用〈电视机〉。蜡板不是电器，不能“打开”来看节目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一只蜡板放在桌上。", "corrected_sentence": "他把一块蜡板放在桌上。", "error_description": "错误：“一只蜡板”。应为“一块蜡板”。“只”多用于动物等，蜡板是平板，应用“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在蜡板里写下了一行字。", "corrected_sentence": "他在蜡板上写下了一行字。", "error_description": "错误：“蜡板里”。应为“蜡板上”。蜡板是平面，表示位置要用“上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
