INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女孩就是小女生。", "primary_collocate": null, "pronunciation": "nǚ hái", "ipa": "ny˨˩˦ xaɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我们班的女孩都喜欢跳舞。", "target_word": "女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩是我同桌，她叫小美。", "target_word": "女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女孩在操场上跑步。", "target_word": "女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩们在教室里唱歌。", "target_word": "女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天有个女孩问我作业的事。", "target_word": "女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个爱笑的女孩，大家都喜欢她。", "target_word": "女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩比我小两岁。", "target_word": "女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们班有二十个女孩。", "target_word": "女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女孩把书放在桌子上。", "target_word": "女孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩们都想去看电影。", "target_word": "女孩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "女孩们", "label": "复数"}, {"form": "小女孩", "label": "复合"}], "register": "中性", "sense_fingerprint": "小女生，年纪小的女学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d76871c-acf7-4b48-b16d-14696abcf71b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女孩", "is_correct": true, "explanation": "正确：“我们班”的同学多为女生，“女孩”与“都喜欢跳舞”相符。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：“我们班”指班级里的学生，一般不与“小狗”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会“喜欢跳舞”，与句意冲突。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能“喜欢跳舞”。"}], "explanations": {"女孩": "正确：“我们班”的同学多为女生，“女孩”与“都喜欢跳舞”相符。", "小狗": "搭配：“我们班”指班级里的学生，一般不与“小狗”搭配。", "桌子": "语义：桌子不会“喜欢跳舞”，与句意冲突。", "石头": "语义：石头没有生命，不能“喜欢跳舞”。"}, "sentence_index": 0, "correct_answer": "女孩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位女孩已经五十岁了，在医院工作。", "explanation": "这里应该用〈女人〉。女孩指年纪小的女学生，五十岁的人要用女人。"}, {"text": "那个女孩每天在家带孙子，很辛苦。", "explanation": "这里应该用〈奶奶〉。女孩指年纪小的女学生，带孙子的老人要用奶奶。"}, {"text": "那位女孩已经结婚多年，有两个孩子。", "explanation": "这里应该用〈妇女〉。女孩指年纪小的女学生，已婚多年的成年女性要用妇女。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女孩", "is_correct": true, "explanation": "正确：“比我小两岁”说明年龄较小，与“女孩”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有年龄，无法与“我”比较岁数。"}, {"text": "老人", "is_correct": false, "explanation": "搭配：“老人”一般比说话人年长，与“比我小两岁”搭配不当。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头没有年龄，无法比较岁数。"}], "explanations": {"女孩": "正确：“比我小两岁”说明年龄较小，与“女孩”相符。", "桌子": "语义：桌子没有年龄，无法与“我”比较岁数。", "老人": "搭配：“老人”一般比说话人年长，与“比我小两岁”搭配不当。", "木头": "语义：木头没有年龄，无法比较岁数。"}, "sentence_index": 6, "correct_answer": "女孩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位女孩已经五十多岁，是这家医院的护士长。", "explanation": "这里应该用〈女士〉。女孩指年纪小的女学生，五十多岁担任护士长的成年女性要用女士。"}, {"text": "那位女孩和丈夫结婚多年，一起养大了两个孩子。", "explanation": "这里应该用〈妻子〉。女孩指年纪小的女学生，已与丈夫结婚并养育孩子的女性要用妻子。"}, {"text": "这位女孩已经七十岁了，头发全白了。", "explanation": "这里应该用〈老太太〉。女孩指年纪小的女学生，七十岁的老年女性要用老太太。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有十五个女孩们。", "corrected_sentence": "我们班有十五个女孩。", "error_description": "错误：数量词“十五个”之后的名词不能再加“们”。正确应为“十五个女孩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室门口有个聪明地女孩在等我。", "corrected_sentence": "教室门口有个聪明的女孩在等我。", "error_description": "错误：修饰名词“女孩”的形容词“聪明”之后应用“的”，不用“地”（“地”用于修饰动词）。正确应为“聪明的女孩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
