INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "母亲是生你养你的妈妈。", "primary_collocate": null, "pronunciation": "mǔ qīn", "ipa": "mu˨˩˦ tɕʰin˥˥", "syllable_count": 2, "sentences": [{"text": "母亲给了我生命，也教我做人。", "target_word": "母亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个孩子都爱自己的母亲。", "target_word": "母亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲很辛苦地把我养大。", "target_word": "母亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给母亲打个电话。", "target_word": "母亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的母亲很早就去世了。", "target_word": "母亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲做的饭最好吃。", "target_word": "母亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲站在门口等着我回家。", "target_word": "母亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢母亲，您辛苦了！", "target_word": "母亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她像母亲一样照顾着弟弟。", "target_word": "母亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲的手很粗，但是很温暖。", "target_word": "母亲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "母亲们", "label": "复数"}, {"form": "母亲节", "label": "复合"}], "register": "中性", "sense_fingerprint": "生下并养大自己的妈妈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d76871c-acf7-4b48-b16d-14696abcf71b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "母亲", "is_correct": true, "explanation": "正确：“母亲”是生下并养育我的人，与“给了我生命，也教我做人”相符。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师不能“给了我生命”，只能“教我做人”。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子没有生命，不能“给了我生命”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能“给了我生命”。"}], "explanations": {"母亲": "正确：“母亲”是生下并养育我的人，与“给了我生命，也教我做人”相符。", "老师": "语义：老师不能“给了我生命”，只能“教我做人”。", "椅子": "语义：椅子没有生命，不能“给了我生命”。", "石头": "语义：石头没有生命，不能“给了我生命”。"}, "sentence_index": 0, "correct_answer": "母亲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位母亲才七岁，正在学习写字。", "explanation": "这里应该用〈孩子〉。母亲指生育子女的女性家长，七岁的小孩只能称孩子，不能称母亲。"}, {"text": "他的母亲比他小一岁，每天一起去幼儿园。", "explanation": "这里应该用〈妹妹〉。母亲指生育子女的女性家长，比“他”小一岁的女孩是妹妹，不能称母亲。"}, {"text": "这个母亲还在学走路，见人就笑。", "explanation": "这里应该用〈宝宝〉。母亲指生育子女的女性家长，还在学走路的婴儿只能称宝宝，不能称母亲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "母亲", "is_correct": true, "explanation": "正确：“母亲”是等我回家的家人，与“站在门口等着我回家”相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能站在门口等人，与句意冲突。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能站在门口等人，与句意冲突。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头没有等待的意识，不能“等着我回家”。"}], "explanations": {"母亲": "正确：“母亲”是等我回家的家人，与“站在门口等着我回家”相符。", "月亮": "语义：月亮不能站在门口等人，与句意冲突。", "桌子": "语义：桌子不能站在门口等人，与句意冲突。", "木头": "语义：木头没有等待的意识，不能“等着我回家”。"}, "sentence_index": 6, "correct_answer": "母亲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的母亲今年四岁，还不认识字。", "explanation": "这里应该用〈女儿〉。母亲指生育子女的女性家长，四岁的孩子是女儿，不能称母亲。"}, {"text": "我的母亲正在上小学，每天背着书包。", "explanation": "这里应该用〈妹妹〉。母亲指生育子女的女性家长，正在上小学的女孩要用妹妹。"}, {"text": "那个母亲每天要人抱着睡觉。", "explanation": "这里应该用〈孩子〉。母亲指生育子女的女性家长，每天要人抱着睡觉的婴儿要用孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母亲的做的菜很好吃。", "corrected_sentence": "母亲做的菜很好吃。", "error_description": "错误：“母亲”之后多加了“的”，与“做”的修饰关系重复。正确为“母亲做的菜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家里来了两个母亲们。", "corrected_sentence": "家里来了两个母亲。", "error_description": "错误：数量词“两个”之后的名词不能再加“们”。正确为“两个母亲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
