INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "家里要做的事情，比如打扫、做饭。", "primary_collocate": null, "pronunciation": "jiā wù", "ipa": "tɕja˥˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "今天我的家务是洗碗。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打扫房间是最累的家务。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一个人做所有的家务，很累。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先做完家务，再写作业。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个星期六，我们全家一起做家务。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家务做得很好。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天家务太多，我没有时间看书。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，家务不分男女。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完家务，她坐下来喝茶。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "擦桌子也是一种家务。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家务事", "label": "复合"}, {"form": "家务活", "label": "复合"}], "register": "中性", "sense_fingerprint": "家里要做的事，如打扫、做饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d76871c-acf7-4b48-b16d-14696abcf71b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是要做的事，“今天我的天气是洗碗”说不通"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯工具，不是要做的事，“今天我的电话是洗碗”说不通"}, {"text": "家务", "is_correct": true, "explanation": "家务：家里要做的事，洗碗是家务的一种，符合语境"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验学习的活动，不是家里要做的事，“今天我的考试是洗碗”说不通"}], "explanations": {"天气": "语义：天气是气象状况，不是要做的事，“今天我的天气是洗碗”说不通", "电话": "语义：电话是通讯工具，不是要做的事，“今天我的电话是洗碗”说不通", "家务": "家务：家里要做的事，洗碗是家务的一种，符合语境", "考试": "语义：考试是测验学习的活动，不是家里要做的事，“今天我的考试是洗碗”说不通"}, "sentence_index": 0, "correct_answer": "家务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们请了家务来打扫卫生。", "explanation": "这里应该用〈家政〉。请人来做清洁等服务要说家政；家务是家里自己要做的事，不能请来"}, {"text": "这对年轻人组成了一个幸福的家务。", "explanation": "这里应该用〈家庭〉。能组成的是家庭，家务是家里要做的事，不能用来组成一个家"}, {"text": "他的主要家务是处理合同。", "explanation": "这里应该用〈事务〉。处理合同属于工作事务，家务指家里要做的事"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：“太多”说的是数量，空气是无处不在的气体，“今天空气太多”说不通"}, {"text": "家务", "is_correct": true, "explanation": "家务：家里要做的事，句中说今天要做的事太多，符合语境"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是每人每年一次的日子，不能说“今天生日太多”"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“太多”不能修饰体温，体温只说高低"}], "explanations": {"空气": "语义：“太多”说的是数量，空气是无处不在的气体，“今天空气太多”说不通", "家务": "家务：家里要做的事，句中说今天要做的事太多，符合语境", "生日": "语义：生日是每人每年一次的日子，不能说“今天生日太多”", "体温": "搭配：“太多”不能修饰体温，体温只说高低"}, "sentence_index": 6, "correct_answer": "家务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈今天洗了一块家务，很累。", "explanation": "量词错误：“块”用于块状的东西，家务要用〈项〉或〈件〉"}, {"text": "爸爸做了一把家务，就去看电视了。", "explanation": "量词错误：“把”用于有柄的器具，家务要用〈项〉或〈件〉"}, {"text": "我擦了一扇家务，很累。", "explanation": "量词错误：“扇”用于门窗，家务要用〈项〉或〈件〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都要做繁重地家务。", "corrected_sentence": "他每天都要做繁重的家务。", "error_description": "修饰名词“家务”要用“的”，应写作“繁重的家务”；用“地”（修饰动词用）是误用", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我常常做完一家务以后看书。", "corrected_sentence": "我常常做完一件家务以后看书。", "error_description": "错误：“一家务”。家务是名词，前面有数词“一”时要加量词“件”，应为“一件家务”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
