INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39867, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39867, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "家庭日常事务，如打扫、洗衣、做饭等。", "primary_collocate": null, "pronunciation": "jiā wù", "ipa": "tɕja˥˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "女孩们则大多在家学习，她们的母亲会教她们家务，比如织布和缝衣服。", "target_word": "家务", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "父亲是家庭的权威，母亲则负责管理家务和照顾孩子。", "target_word": "家务", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "孩子们需要帮助家里做一些简单的家务，比如打扫庭院或者去市场买东西。", "target_word": "家务", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "古罗马的儿童，他们的日常生活充满了学习、家务和简单的快乐，构成了他们童年的一部分。", "target_word": "家务", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "周末我帮父母做家务。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天下班后还要做很多家务。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的家务，大家一起分担。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱做家务，只爱玩游戏。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣服和做饭都是家务。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子很小就学会了做家务。", "target_word": "家务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家务事", "label": "复合"}, {"form": "家务活", "label": "复合"}], "register": "中性", "sense_fingerprint": "家庭日常事务，如打扫、洗衣、做饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d76871c-acf7-4b48-b16d-14696abcf71b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业指学校布置的习题，不是家里要做的事，不能说“教她们作业，比如织布和缝衣服”"}, {"text": "家务", "is_correct": true, "explanation": "家务：家里要做的事，这里指织布、缝衣等家庭劳动，符合语境"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票是金融投资的凭证，与织布、缝衣无关，不能用“教”来搭配"}, {"text": "事务", "is_correct": false, "explanation": "语域：“事务”偏书面、正式，口语中不说“教她们事务”，也不指织布缝衣这类家庭劳动"}], "explanations": {"作业": "语义：作业指学校布置的习题，不是家里要做的事，不能说“教她们作业，比如织布和缝衣服”", "家务": "家务：家里要做的事，这里指织布、缝衣等家庭劳动，符合语境", "股票": "语义：股票是金融投资的凭证，与织布、缝衣无关，不能用“教”来搭配", "事务": "语域：“事务”偏书面、正式，口语中不说“教她们事务”，也不指织布缝衣这类家庭劳动"}, "sentence_index": 0, "correct_answer": "家务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去邮局寄了一封家务。", "explanation": "这里应该用〈家书〉。写给家人的信要说家书；家务是家里要做的事，不能用来指信"}, {"text": "我们的家务很和睦。", "explanation": "这里应该用〈家庭〉。和睦形容的是家里人之间的关系，要说家庭和睦；家务是要做的事，不能和睦"}, {"text": "他负责公司的家务。", "explanation": "这里应该用〈事务〉。公司的工作要说事务，如“负责公司的日常事务”；家务只指家里的劳动"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节日", "is_correct": false, "explanation": "语义：节日是特定的日子，不是可以分担的事，“我们家的节日，大家一起分担”说不通"}, {"text": "家务", "is_correct": true, "explanation": "家务：家里要做的事，可以大家一起分担，符合语境"}, {"text": "零食", "is_correct": false, "explanation": "搭配：“分担”搭配的是负担、工作、费用，不说分担零食"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身体数据，不能分担，句子说不通"}], "explanations": {"节日": "语义：节日是特定的日子，不是可以分担的事，“我们家的节日，大家一起分担”说不通", "家务": "家务：家里要做的事，可以大家一起分担，符合语境", "零食": "搭配：“分担”搭配的是负担、工作、费用，不说分担零食", "身高": "语义：身高是人的身体数据，不能分担，句子说不通"}, "sentence_index": 6, "correct_answer": "家务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈今天干了一本家务，累坏了。", "explanation": "量词错误：“本”用于书册，家务要用〈项〉或〈件〉，应说“一项家务”"}, {"text": "他一个人做完了一座家务，才去休息。", "explanation": "量词错误：“座”用于山、楼等大型物体，家务要用〈项〉或〈件〉"}, {"text": "她一辆家务做了一上午。", "explanation": "量词错误：“辆”用于车，家务要用〈项〉或〈件〉，应说“一件家务”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚做完一家务，就去睡觉了。", "corrected_sentence": "他刚做完一件家务，就去睡觉了。", "error_description": "错误：“一家务”。应为“一件家务”。家务作为名词，前面有数词时要加量词“件”，不能说“一家务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "儿子做地家务做得很好。", "corrected_sentence": "儿子做家务做得很好。", "error_description": "错误：“做地家务”。动词“做”和宾语“家务”之间不能加“地”，应说“做家务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '065e1ee5-9660-4cda-8ec4-5396552adb65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
