INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用针和线把衣服破的地方补好。", "primary_collocate": null, "pronunciation": "féng yī fu", "ipa": "fəŋ³⁵ i⁵⁵ fu", "syllable_count": 3, "sentences": [{"text": "袖子破了，我自己用针线缝衣服。", "target_word": "缝衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不会缝衣服，只好请邻居帮忙。", "target_word": "缝衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆眼睛不好，不能再缝衣服了。", "target_word": "缝衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开了一节课，教学生怎么缝衣服。", "target_word": "缝衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边听音乐，一边缝衣服。", "target_word": "缝衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缝衣服的时候，小心别扎到手。", "target_word": "缝衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孙子的衣服破了，奶奶忙着给他缝衣服。", "target_word": "缝衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学缝衣服，这样衣服破了就能自己补。", "target_word": "缝衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在门口，认真地缝衣服。", "target_word": "缝衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹第一次缝衣服，扎到了手指。", "target_word": "缝衣服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缝了衣服", "label": "体标"}, {"form": "缝过衣服", "label": "体标"}, {"form": "缝缝衣服", "label": "重叠"}, {"form": "縫衣服", "label": "繁体"}], "register": "中性", "sense_fingerprint": "缝衣服|用针线把衣服破处补好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03c328b-1704-46b9-8a36-3a9e57b7a59b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缝衣服", "is_correct": true, "explanation": "正确答案：缝衣服，用针线缝补破袖子，与“用针线”的语境一致。"}, {"text": "炒", "is_correct": false, "explanation": "语义：炒菜与针线无关，“用针线炒”不成立。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象应是衣物、餐具等，不能与“针线”搭配。"}, {"text": "晒", "is_correct": false, "explanation": "语义：晒是晾干，与“袖子破了”和“针线”的修补语境无关。"}], "explanations": {"缝衣服": "正确答案：缝衣服，用针线缝补破袖子，与“用针线”的语境一致。", "炒": "语义：炒菜与针线无关，“用针线炒”不成立。", "洗": "搭配：“洗”的对象应是衣物、餐具等，不能与“针线”搭配。", "晒": "语义：晒是晾干，与“袖子破了”和“针线”的修补语境无关。"}, "sentence_index": 0, "correct_answer": "缝衣服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用熨斗缝衣服。", "explanation": "这里应该用〈熨衣服〉。熨斗用来烫平衣物，不能用来缝合，缝衣服要用针线或缝纫机。"}, {"text": "她用菜刀缝衣服。", "explanation": "这里应该用〈切菜〉。菜刀用来切食物，不能用来缝合衣物，缝衣服要用针线。"}, {"text": "她用剪刀缝衣服。", "explanation": "这里应该用〈剪布〉。剪刀用来剪开布料，不能把破的地方缝好，缝衣服要用针线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缝衣服", "is_correct": true, "explanation": "正确答案：缝衣服，孙子的衣服破了，奶奶用针线把它补好，符合语境。"}, {"text": "接生", "is_correct": false, "explanation": "语义：“接生”指帮助婴儿出生，“给孙子接生”句意不通。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体状况，不是能替别人去做的动作，“给孙子发烧”不成立。"}, {"text": "运送", "is_correct": false, "explanation": "语域：“运送”偏书面，与这句口语化的叙述不协调，且“给孙子运送”语义不通。"}], "explanations": {"缝衣服": "正确答案：缝衣服，孙子的衣服破了，奶奶用针线把它补好，符合语境。", "接生": "语义：“接生”指帮助婴儿出生，“给孙子接生”句意不通。", "发烧": "语义：“发烧”是身体状况，不是能替别人去做的动作，“给孙子发烧”不成立。", "运送": "语域：“运送”偏书面，与这句口语化的叙述不协调，且“给孙子运送”语义不通。"}, "sentence_index": 6, "correct_answer": "缝衣服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在缝铁管。", "explanation": "这里应该用〈焊接〉（焊接铁管）。缝衣服的对象是布料衣物，铁管要用“焊接”。"}, {"text": "工人在缝木箱。", "explanation": "这里应该用〈钉〉（钉木箱）。缝衣服是用针线缝合布料，木箱要用“钉”。"}, {"text": "工人在缝木头。", "explanation": "这里应该用〈锯〉（锯木头）。缝衣服的对象是衣物，木头要用“锯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她缝衣服得很仔细。", "corrected_sentence": "她缝衣服缝得很仔细。", "error_description": "错误：“缝衣服得很仔细”。正确：“缝衣服缝得很仔细”。带补语的句子要重复动词，格式为“动词＋宾语＋动词＋得＋补语”，漏掉第二个“缝”就错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他缝衣服好了。", "corrected_sentence": "他缝衣服缝好了。", "error_description": "错误：“缝衣服好了”。正确：“缝衣服缝好了”。带结果补语的句子要重复动词，格式为“动词＋宾语＋动词＋补语”，漏掉第二个“缝”就错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
