INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "管理家务就是管家里的事情。", "primary_collocate": null, "pronunciation": "guǎn lǐ jiā wù", "ipa": "kwan˨˩˦ li˨˩˦ tɕja˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "爷爷说，管理家务也是一种本事。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她们姐妹三人轮流管理家务。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他退休以后开始学着管理家务。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻夫妻搬出来住，得自己管理家务。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们不在家的时候，谁来管理家务？", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管理家务需要耐心，也需要好的计划。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妈妈管理家务三十年了，从来没喊过累。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边工作，一边管理家务，每天都很忙。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家政课上，老师教学生怎么管理家务。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把工资交给丈夫，自己专心管理家务。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "管理家務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "管家里的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03c328b-1704-46b9-8a36-3a9e57b7a59b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能说是一种本事，句意不通。"}, {"text": "管理家务", "is_correct": true, "explanation": "正确。指管家里的事情，可以说是一种本事。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯不能说是一种本事，句意不通。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯不能说是一种本事，句意不通。"}], "explanations": {"椅子": "语义：椅子不能说是一种本事，句意不通。", "管理家务": "正确。指管家里的事情，可以说是一种本事。", "电梯": "语义：电梯不能说是一种本事，句意不通。", "台灯": "语义：台灯不能说是一种本事，句意不通。"}, "sentence_index": 0, "correct_answer": "管理家务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年轻夫妻搬出来住，得自己管理衣服。", "explanation": "这里应该用〈洗〉。“管理”不与“衣服”搭配，洗衣服要用〈洗〉。"}, {"text": "年轻夫妻搬出来住，得自己管理面包。", "explanation": "这里应该用〈做〉。“管理”不与“面包”搭配，做面包要用〈做〉。"}, {"text": "年轻夫妻搬出来住，得自己管理床。", "explanation": "这里应该用〈铺〉。“管理”不与“床”搭配，铺床要用〈铺〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“从来没喊过累”的长期劳作语境不符，“睡觉三十年”不合理。"}, {"text": "管理家务", "is_correct": true, "explanation": "正确。指长期料理家务，与“从来没喊过累”相合。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业三十年”与“从来没喊过累”的劳作语境矛盾。"}, {"text": "请假", "is_correct": false, "explanation": "语义：“请假三十年”不合理，也与“从来没喊过累”的劳作语境矛盾。"}], "explanations": {"睡觉": "语义：“睡觉”与“从来没喊过累”的长期劳作语境不符，“睡觉三十年”不合理。", "管理家务": "正确。指长期料理家务，与“从来没喊过累”相合。", "失业": "语义：“失业三十年”与“从来没喊过累”的劳作语境矛盾。", "请假": "语义：“请假三十年”不合理，也与“从来没喊过累”的劳作语境矛盾。"}, "sentence_index": 6, "correct_answer": "管理家务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把工资交给丈夫，自己专心管理饭。", "explanation": "这里应该用〈做〉。“管理”不与“饭”搭配，做饭要用〈做〉。"}, {"text": "她把工资交给丈夫，自己专心管理汤。", "explanation": "这里应该用〈熬〉。“管理”不与“汤”搭配，熬汤要用〈熬〉。"}, {"text": "她把工资交给丈夫，自己专心管理钢琴。", "explanation": "这里应该用〈弹〉。“管理”不与“钢琴”搭配，弹钢琴要用〈弹〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她以前没管理了家务。", "corrected_sentence": "她以前没管理过家务。", "error_description": "错误：“没管理了”。正确：“没管理过”。否定过去的经历用“没……过”，“没”后面的动词不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她管理家务管理很好。", "corrected_sentence": "她管理家务管理得很好。", "error_description": "补语错误：“管理家务”后的程度补语须用“得”，应说“管理得很好”，不能直接说“管理很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
