INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39875, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "负责处理家庭中的日常事务，如做饭、打扫、照顾家人等。", "primary_collocate": null, "pronunciation": "guǎn lǐ jiā wù", "ipa": "kwan˨˩˦ li˨˩˦ tɕja˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "父亲是家庭的权威，母亲则负责管理家务和照顾孩子。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "奶奶年纪大了，现在由妈妈管理家务。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她结婚以后辞了工作，在家专门管理家务。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会管理家务，家里每天都干干净净。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妻子上班，丈夫在家管理家务和带孩子。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就跟着母亲学习管理家务。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱和时间都要安排，管理家务真不容易。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人生病住院，家里没人管理家务了。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把管理家务的事交给了大女儿。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位阿姨负责管理家务，你不用操心。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "管理家務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "负责处理家庭日常事务（做饭、打扫、照顾家人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03c328b-1704-46b9-8a36-3a9e57b7a59b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打哈欠", "is_correct": false, "explanation": "语义：“打哈欠”是生理动作，不能作为母亲“负责”的职责。"}, {"text": "管理家务", "is_correct": true, "explanation": "正确。与后句“照顾孩子”并列，指处理家庭日常事务。"}, {"text": "离开", "is_correct": false, "explanation": "搭配：“负责”后接的应是任务性动词，“离开”不能与之搭配。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”不是母亲的职责，与“负责”和“照顾孩子”的语境矛盾。"}], "explanations": {"打哈欠": "语义：“打哈欠”是生理动作，不能作为母亲“负责”的职责。", "管理家务": "正确。与后句“照顾孩子”并列，指处理家庭日常事务。", "离开": "搭配：“负责”后接的应是任务性动词，“离开”不能与之搭配。", "忘记": "语义：“忘记”不是母亲的职责，与“负责”和“照顾孩子”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "管理家务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很会管理家务，公司的账目都由他来算。", "explanation": "“管理家务”指处理家庭中的日常事务，公司的账目属于公司事务，不是家务。"}, {"text": "这位经理在工厂里管理家务，每天检查机器。", "explanation": "“管理家务”指处理家庭事务，工厂里检查机器属于生产管理，不是家务。"}, {"text": "校长负责管理家务，安排全校老师的课。", "explanation": "“管理家务”指处理家庭事务，安排学校课程属于学校事务，不是家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙发", "is_correct": false, "explanation": "语义：沙发不能作“真不容易”的主语，句意不通。"}, {"text": "管理家务", "is_correct": true, "explanation": "正确。指处理家务，与前句“钱和时间都要安排”的语境相合。"}, {"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”与前句的安排语境不符，作主语也不自然。"}, {"text": "发呆", "is_correct": false, "explanation": "搭配：“真不容易”的评价与随意的“发呆”状态不搭配。"}], "explanations": {"沙发": "语义：沙发不能作“真不容易”的主语，句意不通。", "管理家务": "正确。指处理家务，与前句“钱和时间都要安排”的语境相合。", "撒谎": "语义：“撒谎”与前句的安排语境不符，作主语也不自然。", "发呆": "搭配：“真不容易”的评价与随意的“发呆”状态不搭配。"}, "sentence_index": 6, "correct_answer": "管理家务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位阿姨负责管理家务，每天在银行给客户办业务。", "explanation": "“管理家务”指处理家庭事务，在银行办业务是工作，不是家务。"}, {"text": "市长负责管理家务，让城市的交通更方便。", "explanation": "“管理家务”指处理家庭事务，管理城市交通是城市管理，不是家务。"}, {"text": "他在超市管理家务，负责摆放货架上的商品。", "explanation": "“管理家务”指处理家庭事务，在超市摆货架是工作，不是家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一直管理家务过。", "corrected_sentence": "她一直管理家务。", "error_description": "体标错误：句末多出“过”，宾语之后不能加“过”，应删去，说“她一直管理家务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她管理家务管理很好。", "corrected_sentence": "她管理家务管理得很好。", "error_description": "补语错误：“管理家务”后的程度补语须用“得”，应说“管理得很好”，不能直接说“管理很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
