INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39876, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "照顾就是帮助和看管别人。", "primary_collocate": null, "pronunciation": "zhào gù", "ipa": "tʂɑʊ˥˩ ku˥˩", "syllable_count": 2, "sentences": [{"text": "他每天放学后都要照顾妹妹。", "target_word": "照顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你帮我照顾一下我的小弟弟。", "target_word": "照顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里的护士会认真照顾每一位病人。", "target_word": "照顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家幼儿园的老师很会照顾小朋友。", "target_word": "照顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一边工作，一边照顾生病的母亲。", "target_word": "照顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长大以后，我要好好照顾父母。", "target_word": "照顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们互相照顾，生活得很幸福。", "target_word": "照顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让大一点的同学照顾新来的同学。", "target_word": "照顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在养老院工作，每天照顾几位老人。", "target_word": "照顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保姆把孩子照顾得很好，我们很放心。", "target_word": "照顾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "照顧", "label": "繁体"}, {"form": "照顾了", "label": "体标"}, {"form": "照顾过", "label": "体标"}, {"form": "照顾着", "label": "体标"}, {"form": "照顾照顾", "label": "重叠"}], "register": "中性", "sense_fingerprint": "帮助、看管别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03c328b-1704-46b9-8a36-3a9e57b7a59b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39876, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "照顾", "is_correct": true, "explanation": "正确：照顾（zhào gù）即本词条。"}, {"text": "招股", "is_correct": false, "explanation": "声调不同：招股（zhāo gǔ）两个音节的声调都与 zhào gù 不同，意思是公开募集股份。"}, {"text": "照度", "is_correct": false, "explanation": "声母不同：gù 与 dù 只差声母（g 与 d），照度（zhào dù）指光照的强弱。"}, {"text": "罩裤", "is_correct": false, "explanation": "声母不同：gù 与 kù 只差声母（g 与 k），罩裤（zhào kù）指套在外面的裤子。"}], "explanations": {"照顾": "正确：照顾（zhào gù）即本词条。", "招股": "声调不同：招股（zhāo gǔ）两个音节的声调都与 zhào gù 不同，意思是公开募集股份。", "照度": "声母不同：gù 与 dù 只差声母（g 与 d），照度（zhào dù）指光照的强弱。", "罩裤": "声母不同：gù 与 kù 只差声母（g 与 k），罩裤（zhào kù）指套在外面的裤子。"}, "sentence_index": null, "correct_answer": "照顾"}, "level_3": {"options": [{"text": "照顾", "is_correct": true, "explanation": "正确：“照顾”指放学后看管、照料妹妹，与“每天都要”的责任语境相符。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”的对象是物体，不能用于妹妹这样的人。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不能说“打扫妹妹”。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”表示抛下不管，与放学后照看妹妹的语境相反。"}], "explanations": {"照顾": "正确：“照顾”指放学后看管、照料妹妹，与“每天都要”的责任语境相符。", "擦拭": "搭配：“擦拭”的对象是物体，不能用于妹妹这样的人。", "打扫": "搭配：“打扫”的对象是场所或物品，不能说“打扫妹妹”。", "丢弃": "语义：“丢弃”表示抛下不管，与放学后照看妹妹的语境相反。"}, "sentence_index": 0, "correct_answer": "照顾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家们正在照顾这个新出现的问题。", "explanation": "这里应该用〈关注〉。照顾的对象是人，新出现的问题要用“关注”。"}, {"text": "工人正在照顾坏掉的电梯。", "explanation": "这里应该用〈维修〉。照顾的对象是人，电梯这类设备要用“维修”。"}, {"text": "他每天照顾桌子，让它保持干净。", "explanation": "这里应该用〈擦〉。照顾的对象是人，擦桌子要用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "照顾", "is_correct": true, "explanation": "正确：“照顾”表示互相关心照料，与“生活得很幸福”的语境相符。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：“嫉妒”表示怨恨别人，与“生活得很幸福”的语境相矛盾。"}, {"text": "伤害", "is_correct": false, "explanation": "语义：“伤害”表示使人受损，与“生活得很幸福”的语境相矛盾。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”含讥讽之意，与“生活得很幸福”的互相关照相矛盾。"}], "explanations": {"照顾": "正确：“照顾”表示互相关心照料，与“生活得很幸福”的语境相符。", "嫉妒": "语义：“嫉妒”表示怨恨别人，与“生活得很幸福”的语境相矛盾。", "伤害": "语义：“伤害”表示使人受损，与“生活得很幸福”的语境相矛盾。", "嘲笑": "语义：“嘲笑”含讥讽之意，与“生活得很幸福”的互相关照相矛盾。"}, "sentence_index": 6, "correct_answer": "照顾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "欢迎大家常来照顾我们的小店。", "explanation": "这里“照顾”表示“光顾、惠顾”，指顾客来买东西，不是帮助或看管别人。"}, {"text": "他说话很照顾别人的感受，从不伤人。", "explanation": "这里“照顾”表示“顾及、考虑”，指顾及别人的情绪，不是帮助或看管别人。"}, {"text": "这次活动的各个细节都照顾到了，大家很满意。", "explanation": "这里“照顾”表示“兼顾、顾到”，指安排周全，不是帮助或看管别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把弟弟照顾很仔细。", "corrected_sentence": "我把弟弟照顾得很仔细。", "error_description": "“照顾”后接程度补语时必须加“得”，应说“照顾得很仔细”，不能说“照顾很仔细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天照顾了生病的弟弟了一整天。", "corrected_sentence": "我昨天照顾了生病的弟弟一整天。", "error_description": "体标错误：“照顾”后已用“了”表示完成，宾语和时量之间多出的“了”应删去，应说“照顾了生病的弟弟一整天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '908a634d-5edc-49f9-a145-e98ca9b13c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
