INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小孩子就是年龄很小的人。", "primary_collocate": null, "pronunciation": "xiǎo hái zi", "ipa": "ɕjɑʊ˨˩ xaɪ˧˥ tsɨ", "syllable_count": 3, "sentences": [{"text": "这个小孩子才三岁，还不会写字。", "target_word": "小孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子的问题总是特别多。", "target_word": "小孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商店里的小孩子正在选玩具。", "target_word": "小孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子生病了，爸爸带他去医院。", "target_word": "小孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子最怕一个人待在黑房间里。", "target_word": "小孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候是个爱笑的小孩子。", "target_word": "小孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里有专门给小孩子玩的地方。", "target_word": "小孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子看见小狗，高兴地跑过去。", "target_word": "小孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别生气，他只是个小孩子。", "target_word": "小孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "几个小孩子坐在地上画画。", "target_word": "小孩子", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小孩子们", "label": "复数"}], "register": "口语", "sense_fingerprint": "年龄很小的人，强调年纪小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706b40f2-5ae9-4c6f-b968-a9729a151036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老人", "is_correct": false, "explanation": "语义：“老人”指年长的人，与“才三岁”矛盾。"}, {"text": "大学生", "is_correct": false, "explanation": "语义：大学生已经成年，与“才三岁”矛盾。"}, {"text": "人员", "is_correct": false, "explanation": "语域：“人员”是书面、行政用语，与描述三岁幼儿的口语语境不合。"}, {"text": "小孩子", "is_correct": true, "explanation": "“小孩子”指年纪很小的人，与“才三岁，还不会写字”相符。"}], "explanations": {"老人": "语义：“老人”指年长的人，与“才三岁”矛盾。", "大学生": "语义：大学生已经成年，与“才三岁”矛盾。", "人员": "语域：“人员”是书面、行政用语，与描述三岁幼儿的口语语境不合。", "小孩子": "“小孩子”指年纪很小的人，与“才三岁，还不会写字”相符。"}, "sentence_index": 0, "correct_answer": "小孩子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位小孩子已经二十五岁，在公司担任经理。", "explanation": "这里应该用〈青年〉。小孩子强调年纪小，二十五岁的人不能这样称呼。"}, {"text": "这位小孩子已经七十五岁了，每天在小区里散步。", "explanation": "这里应该用〈老人〉。小孩子强调年纪小，七十五岁的人不能这样称呼。"}, {"text": "那个小孩子已经三十五岁，在工厂工作了十年。", "explanation": "这里应该用〈工人〉。小孩子强调年纪小，三十五岁、工作十年的人不能这样称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能作为在游玩场所里“玩”的对象，句意冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能作为“专门给……玩”的对象，句意冲突。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会“玩”，不能说“专门给桌子玩的地方”。"}, {"text": "小孩子", "is_correct": true, "explanation": "“小孩子”指年幼的孩子，是专为他们设计的玩耍场所，句意通顺。"}], "explanations": {"椅子": "语义：椅子是家具，不能作为在游玩场所里“玩”的对象，句意冲突。", "汽车": "语义：汽车是交通工具，不能作为“专门给……玩”的对象，句意冲突。", "桌子": "语义：桌子是家具，不会“玩”，不能说“专门给桌子玩的地方”。", "小孩子": "“小孩子”指年幼的孩子，是专为他们设计的玩耍场所，句意通顺。"}, "sentence_index": 6, "correct_answer": "小孩子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所大学的校园里有一万个小孩子。", "explanation": "这里应该用〈大学生〉。小孩子指年幼的儿童，不指大学生。"}, {"text": "这个小孩子已经六十岁了，做了三十年饭。", "explanation": "这里应该用〈厨师〉。小孩子强调年纪小，六十岁、做了三十年饭的人不能这样称呼。"}, {"text": "这位小孩子已经八十岁了，身体很好。", "explanation": "这里应该用〈老人〉。小孩子强调年纪小，八十岁的人不能这样称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教室里有五台小孩子在画画。", "corrected_sentence": "教室里有五个小孩子在画画。", "error_description": "量词错误：“五台小孩子”中的“台”用错了。“台”用于机器，小孩子是人，应说“五个小孩子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "草地上跑来一只小孩子。", "corrected_sentence": "草地上跑来一个小孩子。", "error_description": "量词错误：“一只小孩子”中的“只”用错了。“只”用于动物，小孩子是人，应说“一个小孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
