INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39884, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "球是圆圆的，可以拍着玩的东西。", "primary_collocate": null, "pronunciation": "qiú", "ipa": "tɕʰjoʊ˧˥", "syllable_count": 1, "sentences": [{"text": "球是圆的，可以在地上滚。", "target_word": "球", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明拍着球走进了院子。", "target_word": "球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球很软，小孩子也能玩。", "target_word": "球", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "球一不小心滚到了马路上。", "target_word": "球", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天放学后都拍球。", "target_word": "球", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸给我买了一个蓝色的球。", "target_word": "球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个球里没有气了。", "target_word": "球", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "球打在窗户上，发出很大的声音。", "target_word": "球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她接住了朋友扔来的球。", "target_word": "球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们几个人围着球跑来跑去。", "target_word": "球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "皮球", "label": "复合"}], "register": "口语", "sense_fingerprint": "圆圆的、可以拍着玩的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706b40f2-5ae9-4c6f-b968-a9729a151036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "球", "is_correct": true, "explanation": "正确。“球”是圆的，能在地上滚，符合句子的描述。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”不是圆的，也不能在地上滚。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”没有形状，不能说它是圆的，也不能滚动。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“在地上滚”通常用于球、轮子这类物体，不说“饭”在地上滚。"}], "explanations": {"球": "正确。“球”是圆的，能在地上滚，符合句子的描述。", "书": "语义：“书”不是圆的，也不能在地上滚。", "空气": "语义：“空气”没有形状，不能说它是圆的，也不能滚动。", "饭": "搭配：“在地上滚”通常用于球、轮子这类物体，不说“饭”在地上滚。"}, "sentence_index": 0, "correct_answer": "球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一瓶球。", "explanation": "这里的量词用错了。“瓶”用于装在瓶子里的东西，球不能用“瓶”来数。"}, {"text": "他每天放学后都写球。", "explanation": "搭配：“写”的对象是文字，球不能被写，这里的动词用错了。"}, {"text": "他买了一根球。", "explanation": "量词用错了。“根”用于细长的条状东西，球是圆的，不能用“根”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "球", "is_correct": true, "explanation": "正确。这里说的是充了气的球，“那个球里没有气了”符合句意。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：“抽屉”不是充了气的东西，不会说里面没有气。"}, {"text": "碗", "is_correct": false, "explanation": "语义：“碗”不充气，说它里面没有气不合常理。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“没有气”一般用于充气的物品，不能用在“饼干”上。"}], "explanations": {"球": "正确。这里说的是充了气的球，“那个球里没有气了”符合句意。", "抽屉": "语义：“抽屉”不是充了气的东西，不会说里面没有气。", "碗": "语义：“碗”不充气，说它里面没有气不合常理。", "饼干": "搭配：“没有气”一般用于充气的物品，不能用在“饼干”上。"}, "sentence_index": 6, "correct_answer": "球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上放着一块球。", "explanation": "这里的量词用错了。“块”用于成块的东西，球是圆的整体，不能用“块”来数。"}, {"text": "他把那个球穿在脚上玩。", "explanation": "搭配：“穿”的对象是衣服、鞋袜，球不能穿在脚上，这里的动词用错了。"}, {"text": "他的书包里装着一本球。", "explanation": "这里的量词用错了。“本”用于书册，球不能用“本”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我买了一条皮球。", "corrected_sentence": "妈妈给我买了一个皮球。", "error_description": "量词错误：“皮球”应该用量词“个”，“条”用于细长的东西，不能用来数皮球。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他球把扔给了妹妹。", "corrected_sentence": "他把球扔给了妹妹。", "error_description": "语序错误：“把”要放在宾语“球”的前面，应说“他把球扔给了妹妹”，不能说“他球把扔给了妹妹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
