INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39887, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一种儿童游戏，一人蒙眼或藏匿，其他人寻找。", "primary_collocate": null, "pronunciation": "zhuō mí cáng", "ipa": "ʈʂwo˥ mi˧˥ tsʰɑŋ˧˥", "syllable_count": 3, "sentences": [{"text": "孩子们还会一起玩游戏，比如捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "我们在公园里玩捉迷藏，我藏在大树后面。", "target_word": "捉迷藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟闭上眼睛数数，我们跟他捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚饭后，孩子们在院子里捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明蒙着眼睛，大家都和他捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，孩子们只好在家里玩捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹最喜欢捉迷藏，因为她很会藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们捉迷藏的时候，他躲在门后面。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们玩捉迷藏，我来当找人的那个。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，我常和朋友们在村子里捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "捉迷藏", "label": "原形"}, {"form": "捉了迷藏", "label": "完成体"}], "register": "口语", "sense_fingerprint": "儿童游戏：一人蒙眼或躲藏，其他人去找", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706b40f2-5ae9-4c6f-b968-a9729a151036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39887, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捉迷藏", "is_correct": true, "explanation": "正确。“捉迷藏”是一种游戏，与前面的“玩游戏”一致。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：“写作业”是学习任务，不是一起玩的游戏。"}, {"text": "学习", "is_correct": false, "explanation": "语义：“学习”不是游戏，与“玩游戏”的列举不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不是游戏，不能作为“玩游戏”的例子。"}], "explanations": {"捉迷藏": "正确。“捉迷藏”是一种游戏，与前面的“玩游戏”一致。", "写作业": "语义：“写作业”是学习任务，不是一起玩的游戏。", "学习": "语义：“学习”不是游戏，与“玩游戏”的列举不符。", "睡觉": "语义：“睡觉”不是游戏，不能作为“玩游戏”的例子。"}, "sentence_index": 0, "correct_answer": "捉迷藏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在院子里下捉迷藏。", "explanation": "搭配：“下”的对象是棋类，不能接“捉迷藏”，这个动词用错了。"}, {"text": "他在操场上踢捉迷藏。", "explanation": "搭配：“踢”的对象是球类，不能与“捉迷藏”搭配，这个动词用错了。"}, {"text": "我们在院子里吃捉迷藏。", "explanation": "搭配：“吃”的对象是食物，不能与“捉迷藏”搭配，这个动词用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39887, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捉迷藏", "is_correct": true, "explanation": "正确。“捉迷藏”是游戏，与后句“很会藏”的理由相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与后句“很会藏”没有因果关系，理由说不通。"}, {"text": "跳绳", "is_correct": false, "explanation": "语义：“跳绳”和“很会藏”没有关系，前后不连贯。"}, {"text": "洗碗", "is_correct": false, "explanation": "语义：“洗碗”和后句“很会藏”没有关系，理由说不通。"}], "explanations": {"捉迷藏": "正确。“捉迷藏”是游戏，与后句“很会藏”的理由相符。", "唱歌": "语义：“唱歌”与后句“很会藏”没有因果关系，理由说不通。", "跳绳": "语义：“跳绳”和“很会藏”没有关系，前后不连贯。", "洗碗": "语义：“洗碗”和后句“很会藏”没有关系，理由说不通。"}, "sentence_index": 6, "correct_answer": "捉迷藏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们玩了一条捉迷藏。", "explanation": "量词用错了。“条”用于细长的东西，捉迷藏是游戏活动，计量应用“场”或“次”，不能用“条”。"}, {"text": "我们在操场上跳捉迷藏。", "explanation": "搭配：“跳”不能接“捉迷藏”这类游戏，这里的动词用错了。"}, {"text": "孩子们在院子里唱捉迷藏。", "explanation": "搭配：“唱”的对象是歌曲，不能与“捉迷藏”搭配，这个动词用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我们去院子里玩过捉迷藏。", "corrected_sentence": "明天我们去院子里玩捉迷藏。", "error_description": "体标错误：“过”表示过去的经历，不能用在“明天”这种将来的计划里。应去掉“过”，说“明天我们去院子里玩捉迷藏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹正在和我们玩了捉迷藏。", "corrected_sentence": "妹妹正在和我们玩捉迷藏。", "error_description": "体标错误：“正在”表示动作正在进行，不能和“了”同用。应说“妹妹正在和我们玩捉迷藏”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
