INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39888, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在水里玩。", "primary_collocate": null, "pronunciation": "wán shuǐ", "ipa": "wan˧˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子们在浅浅的河边玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完手以后不要在洗手池玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友们在沙滩上玩水，也玩沙子。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候常和哥哥去池塘玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天太热了，我们去溪边玩水吧。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在浴缸里玩水，玩得很开心。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷看着孙子在水盆里玩水。", "target_word": "玩水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，孩子们跑到院子里玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不会游泳，只敢在浅水区玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏令营的第一天，同学们去湖边玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "玩水", "label": "原形"}, {"form": "玩了水", "label": "完成体"}, {"form": "玩玩水", "label": "重叠"}], "register": "口语", "sense_fingerprint": "在水里玩耍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706b40f2-5ae9-4c6f-b968-a9729a151036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39888, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "玩水", "is_correct": true, "explanation": "玩水（wán shuǐ）指在水里玩耍，是本词。"}, {"text": "完税", "is_correct": false, "explanation": "wán 相同，shuì（第四声）与 shuǐ（第三声）声调不同；完税意思是缴纳税款。"}, {"text": "晚睡", "is_correct": false, "explanation": "wǎn（第三声）与 wán（第二声）、shuì（第四声）与 shuǐ（第三声）声调都不同；晚睡意思是很晚才睡觉。"}, {"text": "王水", "is_correct": false, "explanation": "wáng 与 wán 只差韵尾（ng 与 n），声调相同；王水是一种化学溶液，与玩水意思不同。"}], "explanations": {"玩水": "玩水（wán shuǐ）指在水里玩耍，是本词。", "完税": "wán 相同，shuì（第四声）与 shuǐ（第三声）声调不同；完税意思是缴纳税款。", "晚睡": "wǎn（第三声）与 wán（第二声）、shuì（第四声）与 shuǐ（第三声）声调都不同；晚睡意思是很晚才睡觉。", "王水": "wáng 与 wán 只差韵尾（ng 与 n），声调相同；王水是一种化学溶液，与玩水意思不同。"}, "sentence_index": null, "correct_answer": "玩水"}, "level_3": {"options": [{"text": "玩水", "is_correct": true, "explanation": "正确：玩水指在水里嬉戏，与“浅浅的河边”的语境相符。"}, {"text": "滑雪", "is_correct": false, "explanation": "搭配：滑雪需要雪场或雪地，不能说在浅浅的河边滑雪。"}, {"text": "堆雪人", "is_correct": false, "explanation": "语义：河边没有雪，句中的情境不可能堆雪人。"}, {"text": "取暖", "is_correct": false, "explanation": "语义：在河边的情境并不需要取暖，句意不合常理。"}], "explanations": {"玩水": "正确：玩水指在水里嬉戏，与“浅浅的河边”的语境相符。", "滑雪": "搭配：滑雪需要雪场或雪地，不能说在浅浅的河边滑雪。", "堆雪人": "语义：河边没有雪，句中的情境不可能堆雪人。", "取暖": "语义：在河边的情境并不需要取暖，句意不合常理。"}, "sentence_index": 0, "correct_answer": "玩水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民每天早上在田里玩水，给庄稼供水。", "explanation": "这里应该用〈浇水〉。玩水指嬉戏，不能用来表示给庄稼供水。"}, {"text": "孩子渴了，赶紧去玩水。", "explanation": "这里应该用〈喝水〉。玩水指在水中嬉戏，渴了要喝水，不能用玩水代替。"}, {"text": "他一口气玩水了三百米。", "explanation": "这里应该用〈游〉。玩水不能和表示距离的数量词搭配，游三百米要用“游”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩水", "is_correct": true, "explanation": "正确：玩水指在水中嬉戏，与“水盆里”的情境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：水盆里不能睡觉，“孙子在水盆里睡觉”的情境不合常理。"}, {"text": "看书", "is_correct": false, "explanation": "语义：水盆里不适合看书，与句中的水上情境不合。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：跑步需要场地，不能说在水盆里跑步。"}], "explanations": {"玩水": "正确：玩水指在水中嬉戏，与“水盆里”的情境相符。", "睡觉": "语义：水盆里不能睡觉，“孙子在水盆里睡觉”的情境不合常理。", "看书": "语义：水盆里不适合看书，与句中的水上情境不合。", "跑步": "搭配：跑步需要场地，不能说在水盆里跑步。"}, "sentence_index": 6, "correct_answer": "玩水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶一早去井边玩水，准备做饭。", "explanation": "这里应该用〈打水〉。打水是取水，玩水指嬉戏，不表示取水。"}, {"text": "爸爸在厨房玩水，准备煮面条。", "explanation": "这里应该用〈烧水〉。玩水不表示给水加热，煮面条前要用“烧水”。"}, {"text": "花太干了，你快去给花玩水吧。", "explanation": "这里应该用〈浇水〉。玩水指在水中嬉戏，不能表示给花供水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候在河里玩水过。", "corrected_sentence": "我小时候在河里玩过水。", "error_description": "错误形式：“玩水过”；正确形式：“玩过水”。“过”表示经历，要紧跟在动词后面，构成“玩过”，再接宾语“水”，不能放在宾语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在院子里玩水玩很开心。", "corrected_sentence": "孩子们在院子里玩水玩得很开心。", "error_description": "错误形式：“玩水玩很开心”；正确形式：“玩水玩得很开心”。动词与表示程度的补语之间要用结构助词“得”连接，漏掉“得”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
