INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39889, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指在水中玩耍、嬉戏。", "primary_collocate": null, "pronunciation": "wán shuǐ", "ipa": "wan˧˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "在夏天，他们可能会去河边玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "夏天，孩子们喜欢在小河里玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别在水边玩水，太危险了。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在海边玩水玩了一天。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹穿着小雨靴，在水坑里玩水。", "target_word": "玩水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很热，大家都想去泳池玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟玩水玩得全身都湿了。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我带孩子去公园的喷泉旁玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗也跳进河里，跟我们一起玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说春天水还冷，不要玩水。", "target_word": "玩水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "玩水", "label": "原形"}, {"form": "玩了水", "label": "完成体"}, {"form": "玩玩水", "label": "重叠"}], "register": "口语", "sense_fingerprint": "在河、海、泳池等水中玩耍嬉戏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706b40f2-5ae9-4c6f-b968-a9729a151036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
