INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩水", "is_correct": true, "explanation": "正确：玩水指在水中嬉戏，与“全身都湿了”的结果相符。"}, {"text": "读书", "is_correct": false, "explanation": "语义：读书不会把人弄得全身湿透，与“玩得全身都湿了”的结果矛盾。"}, {"text": "画画", "is_correct": false, "explanation": "语义：画画不会弄湿身体，与“全身都湿了”的结果不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”与“玩得全身都湿了”这一结果补语不搭配，唱歌不会使人湿透。"}], "explanations": {"玩水": "正确：玩水指在水中嬉戏，与“全身都湿了”的结果相符。", "读书": "语义：读书不会把人弄得全身湿透，与“玩得全身都湿了”的结果矛盾。", "画画": "语义：画画不会弄湿身体，与“全身都湿了”的结果不符。", "唱歌": "搭配：“唱歌”与“玩得全身都湿了”这一结果补语不搭配，唱歌不会使人湿透。"}, "sentence_index": 6, "correct_answer": "玩水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他渴了，去厨房玩水。", "explanation": "这里应该用〈喝水〉。玩水是嬉戏，渴了要喝水，不能用玩水代替。"}, {"text": "妈妈在厨房玩水，准备煮面条。", "explanation": "这里应该用〈烧水〉。玩水不表示给水加热，煮面条前要用“烧水”。"}, {"text": "他一早去井边玩水，准备做饭。", "explanation": "这里应该用〈打水〉。打水是取水，玩水指嬉戏，不表示取水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们在河边玩水得很开心。", "corrected_sentence": "孩子们在河边玩水玩得很开心。", "error_description": "错误形式：“玩水得很开心”；正确形式：“玩水玩得很开心”。“玩水”是动宾式词语，带补语时要重复动词“玩”，说成“玩水玩得”，不能省去前面的“玩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们小时候在池塘玩水过。", "corrected_sentence": "我们小时候在池塘玩过水。", "error_description": "错误形式：“玩水过”；正确形式：“玩过水”。“过”表示经历，必须紧跟动词“玩”，构成“玩过”，再接宾语“水”，不能放在宾语“水”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
