INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "兴趣就是你喜欢做一件事的感觉。", "primary_collocate": null, "pronunciation": "xìng qù", "ipa": "ɕiŋ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "我对做饭越来越有兴趣了。", "target_word": "兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一听到足球，就来了兴趣。", "target_word": "兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有兴趣，学习就很累。", "target_word": "兴趣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "姐姐的兴趣是拍照。", "target_word": "兴趣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我对下棋没有兴趣。", "target_word": "兴趣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "兴趣可以让生活更有意思。", "target_word": "兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王对中国历史很有兴趣。", "target_word": "兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你对什么运动有兴趣？", "target_word": "兴趣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的兴趣不一样，所以常常去不同的地方。", "target_word": "兴趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把兴趣变成了工作。", "target_word": "兴趣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兴趣", "label": "原形"}, {"form": "感兴趣", "label": "复合"}, {"form": "兴趣班", "label": "复合"}, {"form": "兴趣爱好", "label": "复合"}, {"form": "一种兴趣", "label": "量词"}], "register": "中性", "sense_fingerprint": "喜欢做某件事的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706b40f2-5ae9-4c6f-b968-a9729a151036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兴趣", "is_correct": true, "explanation": "正确：兴趣指喜欢做某事的感觉，与“对做饭越来越有”的语境相符。"}, {"text": "力气", "is_correct": false, "explanation": "语义：“力气”指体力，与“对做饭越来越有”搭配后不表示喜欢做饭的感觉。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“有体重”不是常用搭配，句中表示喜好的语境不能用体重。"}, {"text": "钱", "is_correct": false, "explanation": "语义：“有钱”说的是财富，与对做饭的喜欢之感无关。"}], "explanations": {"兴趣": "正确：兴趣指喜欢做某事的感觉，与“对做饭越来越有”的语境相符。", "力气": "语义：“力气”指体力，与“对做饭越来越有”搭配后不表示喜欢做饭的感觉。", "体重": "搭配：“有体重”不是常用搭配，句中表示喜好的语境不能用体重。", "钱": "语义：“有钱”说的是财富，与对做饭的喜欢之感无关。"}, "sentence_index": 0, "correct_answer": "兴趣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的兴趣很大。", "explanation": "这里应该用〈作用〉。兴趣指喜欢做某事的感觉，不能用来形容药物的效果。"}, {"text": "这部电影很有兴趣。", "explanation": "这里应该用〈有趣〉。兴趣指人对事情的喜爱，形容电影让人觉得有意思要用“有趣”，不能说“很有兴趣”。"}, {"text": "这辆车的兴趣很快。", "explanation": "这里应该用〈速度〉。兴趣指人对事情的喜欢，不能用来形容车的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兴趣", "is_correct": true, "explanation": "正确：兴趣指对中国历史的喜爱，与“很有”搭配表示喜爱程度。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情或急躁的情绪，与对历史的喜爱无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观，不能用来形容对历史的喜欢程度。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是身体的温度，不能与“很有”搭配，句中也不表示心理倾向。"}], "explanations": {"兴趣": "正确：兴趣指对中国历史的喜爱，与“很有”搭配表示喜爱程度。", "脾气": "语义：“脾气”指性情或急躁的情绪，与对历史的喜爱无关。", "颜色": "语义：“颜色”指外观，不能用来形容对历史的喜欢程度。", "体温": "搭配：“体温”是身体的温度，不能与“很有”搭配，句中也不表示心理倾向。"}, "sentence_index": 6, "correct_answer": "兴趣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司要维护股东的兴趣。", "explanation": "这里应该用〈利益〉。兴趣指喜欢某事的心理倾向，维护股东的得失要用“利益”。"}, {"text": "这份礼物的兴趣很重。", "explanation": "这里应该用〈分量〉。兴趣指人对事情的喜爱，不能用来形容礼物的轻重。"}, {"text": "他的兴趣很饱满。", "explanation": "这里应该用〈精神〉。“饱满”形容精神状态，兴趣不能用“饱满”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前对游泳过有兴趣。", "corrected_sentence": "我以前对游泳有过兴趣。", "error_description": "错误形式：“过有兴趣”；正确形式：“有过兴趣”。“过”表示经历，要紧跟动词“有”，构成“有过”，再接宾语“兴趣”，不能放在“有”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对音乐有感兴趣。", "corrected_sentence": "他对音乐感兴趣。", "error_description": "错误形式：“有感兴趣”；正确形式：“感兴趣”。“感兴趣”本身已经是一个动词短语，前面不能再加动词“有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c1e4e1f-84b7-4666-be22-6767a18cefdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
