INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39893, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示转折，引出与前面相反或相对的事实或情况。", "primary_collocate": null, "pronunciation": "què shì", "ipa": "tɕʰɥe˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "虽然古罗马的生活方式和我们今天有很大不同，但孩子们对家庭的爱和对游戏的兴趣，却是跨越时空的。", "target_word": "却是", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我以为他是医生，他却是老师。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说他会来，来的却是他弟弟。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我等的是朋友，来的却是送快递的人。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想买红色的，拿到手的却是蓝色的。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说是为我好，结果却是害了我。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天天气预报说有雨，今天却是大晴天。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很少说话，说出来的却是最重要的话。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想早点睡，等着我的却是一大堆工作。", "target_word": "却是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿得很普通，开的车却是名牌。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "转折副词：前面说一种情况，后面用“却是”引出相反或不同的事实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e30e707f-e868-41d3-92c0-29d881cfc989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "却是", "is_correct": true, "explanation": "表示转折，引出与前面“虽然…但…”所说相反或不同的情况，符合句中的对照关系。"}, {"text": "太", "is_correct": false, "explanation": "搭配：「太」修饰形容词或心理动词，不能直接修饰「跨越时空」这样的动词短语。"}, {"text": "最", "is_correct": false, "explanation": "搭配：「最」表示程度最高，要修饰形容词，不能用在动词「跨越」前。"}, {"text": "很多", "is_correct": false, "explanation": "语法：「很多」不能放在「是」前作状语，句子不通。"}], "explanations": {"却是": "表示转折，引出与前面“虽然…但…”所说相反或不同的情况，符合句中的对照关系。", "太": "搭配：「太」修饰形容词或心理动词，不能直接修饰「跨越时空」这样的动词短语。", "最": "搭配：「最」表示程度最高，要修饰形容词，不能用在动词「跨越」前。", "很多": "语法：「很多」不能放在「是」前作状语，句子不通。"}, "sentence_index": 0, "correct_answer": "却是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他又高又帅，却是很聪明。", "explanation": "这里应该用〈也〉。〈却是〉表示转折，前后要有相反的情况；这句只是并列补充两个优点，没有对照，应该用〈也〉。"}, {"text": "我们俩都是学生，他却是我的同学。", "explanation": "这里应该用〈就是〉。〈却是〉表示转折，前后要有对立；这里只是确认身份，没有对照，应该用〈就是〉。"}, {"text": "我今天很高兴，却是给你打了电话。", "explanation": "这里应该用〈就〉。〈却是〉表示转折，这句只是说明我的动作，前后没有相反的情况，应该用〈就〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "却是", "is_correct": true, "explanation": "表示转折，前面说昨天的天气预报预告有雨，后面用「却是」引出今天实际相反的大晴天。"}, {"text": "果然", "is_correct": false, "explanation": "语义：「果然」表示与预料相符，而前句预报的是有雨，「果然是大晴天」与之矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：「十分」修饰形容词，不能直接放在「是大晴天」前面。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」修饰形容词或动词，不能直接修饰名词短语「大晴天」。"}], "explanations": {"却是": "表示转折，前面说昨天的天气预报预告有雨，后面用「却是」引出今天实际相反的大晴天。", "果然": "语义：「果然」表示与预料相符，而前句预报的是有雨，「果然是大晴天」与之矛盾。", "十分": "搭配：「十分」修饰形容词，不能直接放在「是大晴天」前面。", "非常": "搭配：「非常」修饰形容词或动词，不能直接修饰名词短语「大晴天」。"}, "sentence_index": 6, "correct_answer": "却是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早起锻炼，却是身体很好。", "explanation": "这里应该用〈所以〉。早起锻炼与身体很好是因果关系，不是相反的情况，〈却是〉表示转折，不适用。"}, {"text": "天气很冷，我们却是穿上了厚衣服。", "explanation": "这里应该用〈于是〉。前后是先后承接的动作，没有对立，〈却是〉表示转折，用在这里不自然。"}, {"text": "他每天练琴，却是琴弹得很好。", "explanation": "这里应该用〈因而〉。前后是因果关系，没有相反的对照，〈却是〉表示转折，用在这里不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以为这次考试很难，结果题目却是了很简单。", "corrected_sentence": "我以为这次考试很难，结果题目却是很简单。", "error_description": "错误：「却是了」。正确：「却是」。「却是」是副词，后面不能再加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他平时工作很忙，周末却是了在家休息。", "corrected_sentence": "他平时工作很忙，周末却是在家休息。", "error_description": "错误：「却是了在家」。正确：「却是在家」。「却是」是副词，后面不能再加「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
