INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39895, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指某事物被某种内容或状态完全占据，数量很多。", "primary_collocate": null, "pronunciation": "chōng mǎn", "ipa": "ʈʂʰʊŋ˥ man˨˩˦", "syllable_count": 2, "sentences": [{"text": "古罗马的儿童，他们的日常生活充满了学习、家务和简单的快乐，构成了他们童年的一部分。", "target_word": "充满", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的脸上充满了笑容。", "target_word": "充满", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个故事充满了希望。", "target_word": "充满", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子的眼睛里充满着好奇。", "target_word": "充满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作充满了机会和挑战。", "target_word": "充满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的话充满了爱心。", "target_word": "充满", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她对新生活充满信心。", "target_word": "充满", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的心里充满了感谢。", "target_word": "充满", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那段日子充满了快乐的回忆。", "target_word": "充满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书充满了有意思的想法。", "target_word": "充满", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "充满了", "label": "完成体"}, {"form": "充满着", "label": "持续体"}, {"form": "充满过", "label": "经历体"}, {"form": "充滿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "抽象的情感、状态、内容占满某人或某事物，如充满希望、充满信心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e30e707f-e868-41d3-92c0-29d881cfc989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "充满", "is_correct": true, "explanation": "表示内容或情感被完全占据，与「学习、家务和简单的快乐」搭配，符合句意。"}, {"text": "舍弃", "is_correct": false, "explanation": "语义：「舍弃」表示放弃，与句中「充满」所表示的有很多之义相反，句意不通。"}, {"text": "缺乏", "is_correct": false, "explanation": "语义：「缺乏」表示没有，与「充满」的意思相反，与句中积极的描述相矛盾。"}, {"text": "驱散", "is_correct": false, "explanation": "语义：「驱散」表示赶走，与句中「快乐」等内容的存在相反，句意不通。"}], "explanations": {"充满": "表示内容或情感被完全占据，与「学习、家务和简单的快乐」搭配，符合句意。", "舍弃": "语义：「舍弃」表示放弃，与句中「充满」所表示的有很多之义相反，句意不通。", "缺乏": "语义：「缺乏」表示没有，与「充满」的意思相反，与句中积极的描述相矛盾。", "驱散": "语义：「驱散」表示赶走，与句中「快乐」等内容的存在相反，句意不通。"}, "sentence_index": 0, "correct_answer": "充满"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班级充满了三十名学生。", "explanation": "这里应该用〈有〉或〈共有〉。〈充满〉表示内容或感情把空间占满，不用于计算具体的人数。"}, {"text": "他的心里充满了一个念头。", "explanation": "这里应该用〈产生〉。〈充满〉要求大量的内容，一个念头不足以把心里占满。"}, {"text": "他的脸上充满了一个酒窝。", "explanation": "这里应该用〈长〉。〈充满〉指被大量内容占满，一个酒窝不足以占满脸；描述脸上有某个部位时应该用〈长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充满", "is_correct": true, "explanation": "表示内心被某种情绪占满，「她对新生活充满信心」符合句意。"}, {"text": "填补", "is_correct": false, "explanation": "搭配：「填补」表示补上空缺，不与「信心」搭配，句意不通。"}, {"text": "充当", "is_correct": false, "explanation": "配价：「充当」表示担任某种角色，后面要接身份名词，不能接「信心」。"}, {"text": "充塞", "is_correct": false, "explanation": "语域：「充塞」是书面语，多指杂乱堵塞的东西，与积极的「信心」不符。"}], "explanations": {"充满": "表示内心被某种情绪占满，「她对新生活充满信心」符合句意。", "填补": "搭配：「填补」表示补上空缺，不与「信心」搭配，句意不通。", "充当": "配价：「充当」表示担任某种角色，后面要接身份名词，不能接「信心」。", "充塞": "语域：「充塞」是书面语，多指杂乱堵塞的东西，与积极的「信心」不符。"}, "sentence_index": 6, "correct_answer": "充满"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这次考试充满了一点信心。", "explanation": "这里应该用〈有〉。〈充满〉表示感情很多、占满，不能和「一点」一起用。"}, {"text": "这个故事充满了一句笑话。", "explanation": "这里应该用〈有〉。〈充满〉要求大量内容，一句笑话不能「充满」故事。"}, {"text": "她的话里充满了一个问题。", "explanation": "这里应该用〈有〉。〈充满〉指被大量内容占满，一个问题不能用〈充满〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间里充满过了温暖的气氛。", "corrected_sentence": "这个房间里充满了温暖的气氛。", "error_description": "错误：「充满过了」。正确：「充满了」。「过」表示经历，与「了」表示完成不能同时用在「充满」后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的心里充满了着对未来的希望。", "corrected_sentence": "他的心里充满着对未来的希望。", "error_description": "错误：「充满了着」。正确：「充满着」。「着」表示持续状态，不能和「了」同时用在「充满」后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
