INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很久很久以前的时间。", "primary_collocate": null, "pronunciation": "gǔ shí hou", "ipa": "ku˨˩ ʂɨ˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "古时候，这座山上住着一位老神仙。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候人们不知道地球是圆的。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说古时候冬天比现在冷得多。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候没有汽车，人们走路去远方。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事发生在没有电的古时候。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人靠种地和打猎生活。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，古时候这里有一条大河。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的夏天没有空调，大家用扇子。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，孩子们没有玩具，只能玩泥巴。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的房子大多是用木头盖的。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "古時候", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很久很久以前的那段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74be4108-6649-40ac-88e8-98d0ee81051b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古时候", "is_correct": true, "explanation": "正确：“古时候”指很久很久以前的时间，与“老神仙”的传说语境相符。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”指一顿饭，不表示时间，不能作句首的时间话题。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是处所名词，与“这座山上住着神仙”的叙述不搭。"}, {"text": "年份", "is_correct": false, "explanation": "语义：“年份”指具体的年度，不指很久以前的一段时期，与“老神仙”的叙述不搭。"}], "explanations": {"古时候": "正确：“古时候”指很久很久以前的时间，与“老神仙”的传说语境相符。", "早饭": "语义：“早饭”指一顿饭，不表示时间，不能作句首的时间话题。", "厨房": "语义：“厨房”是处所名词，与“这座山上住着神仙”的叙述不搭。", "年份": "语义：“年份”指具体的年度，不指很久以前的一段时期，与“老神仙”的叙述不搭。"}, "sentence_index": 0, "correct_answer": "古时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我古时候在北京住过三年。", "explanation": "这里应该用〈以前〉。古时候指很久远的时代，不能用来说说话人自己在北京的经历。"}, {"text": "我古时候很怕黑，每次都不敢一个人睡。", "explanation": "这里应该用〈小时候〉。古时候指遥远的古代，不指说话人自己的童年。"}, {"text": "我古时候刚吃完午饭。", "explanation": "这里应该用〈刚才〉。古时候指很久远的时代，不能用来说刚刚发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古时候", "is_correct": true, "explanation": "正确：“古时候”作时间话题，与“书上说”的历史叙述相符。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“因为”是连词，不能单独作时间话题，“书上说，因为这里有一条大河”不成句。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能放在“这里”前面表示时间。"}, {"text": "驼背", "is_correct": false, "explanation": "体貌：“驼背”描述人的体态，不表示时间，也不能作这里的时间话题。"}], "explanations": {"古时候": "正确：“古时候”作时间话题，与“书上说”的历史叙述相符。", "因为": "语法：“因为”是连词，不能单独作时间话题，“书上说，因为这里有一条大河”不成句。", "很": "语法：“很”是程度副词，不能放在“这里”前面表示时间。", "驼背": "体貌：“驼背”描述人的体态，不表示时间，也不能作这里的时间话题。"}, "sentence_index": 6, "correct_answer": "古时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古时候我们要去火星工作。", "explanation": "这里应该用〈将来〉。古时候指过去的时代，不能用来说还没有发生的计划。"}, {"text": "古时候，我刚见过他。", "explanation": "这里应该用〈不久前〉。古时候指很久远的时代，不能和“刚”所表示的刚刚发生的事搭配。"}, {"text": "我古时候在上大学，明年就毕业了。", "explanation": "这里应该用〈目前〉。古时候指遥远的时代，不能用来说说话人现在正在进行的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古时候的时候，这里还没有人居住。", "corrected_sentence": "古时候，这里还没有人居住。", "error_description": "「古时候」本身已表示时间，后面不能再加「的时候」。正确：古时候，这里还没有人居住；错误：古时候的时候，这里还没有人居住。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古时候那时候，这里就有人住了。", "corrected_sentence": "古时候，这里就有人住了。", "error_description": "「古时候」本身已表示那段时间，后面不能再接「那时候」。正确：古时候，这里就有人住了；错误：古时候那时候，这里就有人住了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
