INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39899, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "防备和抵挡外来的攻击或侵犯。", "primary_collocate": null, "pronunciation": "fáng yù", "ipa": "faŋ˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "古时候，人们修建长城是为了防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "敌人来了，士兵们开始防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城墙很高，士兵们在上面防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山上建了墙，加强防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物用角来防御敌人。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的城市都很重视防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人太多，我们只能先防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队一直在边境防御，不让敌人过来。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小动物没办法防御大鸟的攻击。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王下令，军队要在边境防御敌人。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防御力", "label": "复合"}, {"form": "防御战", "label": "复合"}, {"form": "防禦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "防备并抵挡外来的攻击或侵犯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74be4108-6649-40ac-88e8-98d0ee81051b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防御", "is_correct": true, "explanation": "正确：“防御”指防备和抵挡外来的攻击，与修建长城的目的一致。"}, {"text": "学习", "is_correct": false, "explanation": "语义：“学习”指获取知识，与修建长城的防卫目的无关。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭，与修建长城的目的不相符。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”指关心、看护他人，与修建长城的防卫目的不相符。"}], "explanations": {"防御": "正确：“防御”指防备和抵挡外来的攻击，与修建长城的目的一致。", "学习": "语义：“学习”指获取知识，与修建长城的防卫目的无关。", "烹饪": "语义：“烹饪”指做饭，与修建长城的目的不相符。", "照顾": "语义：“照顾”指关心、看护他人，与修建长城的防卫目的不相符。"}, "sentence_index": 0, "correct_answer": "防御"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "注意安全，防御事故发生。", "explanation": "这里应该用〈防止〉。防御只用于抵挡外来的攻击或侵犯，不用于事故。"}, {"text": "这种药能防御头痛。", "explanation": "这里应该用〈缓解〉。防御用于抵挡外来的攻击，不用于消除身体上的疼痛。"}, {"text": "运动前要防御受伤。", "explanation": "这里应该用〈预防〉。防御用于抵挡外来攻击，不用于受伤等身体上的问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防御", "is_correct": true, "explanation": "正确：“防御”表示抵挡敌人的攻击，与“敌人太多”的处境相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象多为客人，不说“欢迎敌人”。"}, {"text": "致辞", "is_correct": false, "explanation": "语域：“致辞”是正式场合的讲话用语，与战场上的紧急处境不搭。"}, {"text": "请客", "is_correct": false, "explanation": "搭配：“请客”的对象是客人或朋友，与“敌人太多”的语境不搭配。"}], "explanations": {"防御": "正确：“防御”表示抵挡敌人的攻击，与“敌人太多”的处境相符。", "欢迎": "搭配：“欢迎”的对象多为客人，不说“欢迎敌人”。", "致辞": "语域：“致辞”是正式场合的讲话用语，与战场上的紧急处境不搭。", "请客": "搭配：“请客”的对象是客人或朋友，与“敌人太多”的语境不搭配。"}, "sentence_index": 6, "correct_answer": "防御"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要防御环境。", "explanation": "这里应该用〈保护〉。防御指抵挡外来的攻击，不用于环境。"}, {"text": "他防御了我们的建议。", "explanation": "这里应该用〈拒绝〉。防御只用于抵挡外来的攻击，不能用于建议。"}, {"text": "我防御了这篇文章的错字。", "explanation": "这里应该用〈修改〉。防御指抵挡外来的攻击，不用于改正文章中的错字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们在城墙上的防御敌人。", "corrected_sentence": "士兵们在城墙上防御敌人。", "error_description": "「防御」是动词，前面不能加定语标记「的」。正确：士兵们在城墙上防御敌人；错误：士兵们在城墙上的防御敌人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵们防御很好，敌人没有进城。", "corrected_sentence": "士兵们防御得很好，敌人没有进城。", "error_description": "动词「防御」后带情态补语时，要用补语标记「得」。正确：防御得很好；错误：防御很好。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
