INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人做事情需要的力量。", "primary_collocate": null, "pronunciation": "rén lì", "ipa": "ʐən˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这辆车不用马，靠人力就能走。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人力有限，所以要用机器。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么重的东西，人力搬不动。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候没有电，磨面靠人力。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水车用水力，不用人力。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水太大，人力挡不住。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器比人力快得多。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风车用风力，推车用人力。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "靠人力拉船，又慢又累。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震来了，光靠人力救不了所有人。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人力资源", "label": "复合"}, {"form": "人力车", "label": "复合"}], "register": "中性", "sense_fingerprint": "人自身所能使出的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74be4108-6649-40ac-88e8-98d0ee81051b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39900, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人力", "is_correct": true, "explanation": "人力，指人自身所能使出的力量，是正确答案。"}, {"text": "人迹", "is_correct": false, "explanation": "人迹（rén jì）与人力的声母不同（j 与 l），声调相同，意思是人走过的痕迹。"}, {"text": "人气", "is_correct": false, "explanation": "人气（rén qì）与人力的第二个音节声母不同（q 与 l），意思是受欢迎的程度。"}, {"text": "神力", "is_correct": false, "explanation": "神力（shén lì）与人力的第一个音节声母不同（sh 与 r），意思是神奇的力量。"}], "explanations": {"人力": "人力，指人自身所能使出的力量，是正确答案。", "人迹": "人迹（rén jì）与人力的声母不同（j 与 l），声调相同，意思是人走过的痕迹。", "人气": "人气（rén qì）与人力的第二个音节声母不同（q 与 l），意思是受欢迎的程度。", "神力": "神力（shén lì）与人力的第一个音节声母不同（sh 与 r），意思是神奇的力量。"}, "sentence_index": null, "correct_answer": "人力"}, "level_3": {"options": [{"text": "人力", "is_correct": true, "explanation": "人力：指人自身的力量，这里指车不借助马，靠人的力量行进。"}, {"text": "马力", "is_correct": false, "explanation": "语义：句中说“不用马”，“马力”与“不用马”矛盾。"}, {"text": "脑力", "is_correct": false, "explanation": "语义：车靠的是人的力量，不是脑力，“脑力”与句意不符。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“靠”后面要接动力来源，不能说“靠人数就能走”。"}], "explanations": {"人力": "人力：指人自身的力量，这里指车不借助马，靠人的力量行进。", "马力": "语义：句中说“不用马”，“马力”与“不用马”矛盾。", "脑力": "语义：车靠的是人的力量，不是脑力，“脑力”与句意不符。", "人数": "搭配：“靠”后面要接动力来源，不能说“靠人数就能走”。"}, "sentence_index": 0, "correct_answer": "人力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的人力很大，一天能磨出五百斤面。", "explanation": "这里应该用〈动力〉。动力指机器的驱动能量，人力指人自身的力量，不能用来说机器的动力大小。"}, {"text": "这位同学的人力很高，一学就会。", "explanation": "这里应该用〈智力〉。人力指人做事需要的力量，不指思维能力，形容聪明要说“智力”。"}, {"text": "这座风车的人力很大，转得又快又稳。", "explanation": "这里应该用〈风力〉。风车靠风转动，应说风力；人力指人做事需要的力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人力", "is_correct": true, "explanation": "人力：指人自身的力量，这里指用人力比较机器的速度。"}, {"text": "耐心", "is_correct": false, "explanation": "语义：耐心不能用来比较快慢，与“快得多”不搭。"}, {"text": "文字", "is_correct": false, "explanation": "语义：文字不能用来比较快慢，与句意不符。"}, {"text": "效率", "is_correct": false, "explanation": "搭配：“快”形容速度，说效率要用“高”，不能说“效率快”。"}], "explanations": {"人力": "人力：指人自身的力量，这里指用人力比较机器的速度。", "耐心": "语义：耐心不能用来比较快慢，与“快得多”不搭。", "文字": "语义：文字不能用来比较快慢，与句意不符。", "效率": "搭配：“快”形容速度，说效率要用“高”，不能说“效率快”。"}, "sentence_index": 6, "correct_answer": "人力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台拖拉机的人力很大，耕地又快又深。", "explanation": "这里应该用〈马力〉。马力指发动机的功率，人力指人自身的力量，不能用来说机器的动力大小。"}, {"text": "他工作了一整天，人力却依然充沛。", "explanation": "这里应该用〈精力〉。人力指人做事需要的力量，精神和活力的充沛要说“精力”。"}, {"text": "他靠人力认出了远处的那只鸟。", "explanation": "这里应该用〈眼力〉。人力指人的体力或力量，认出远处的东西靠的是眼力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古时候没有电，磨面全靠人力们。", "corrected_sentence": "古时候没有电，磨面全靠人力。", "error_description": "词缀错误：“人力”是不可数的抽象名词，不能加“们”表示复数，应删去“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们全靠人力的推磨，一天只磨两袋面。", "corrected_sentence": "他们全靠人力推磨，一天只磨两袋面。", "error_description": "结构错误：“靠人力”后直接接动词短语，不能加“的”，应删去“的”，说“靠人力推磨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
