INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39901, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人的劳力、体力或劳动力。", "primary_collocate": null, "pronunciation": "rén lì", "ipa": "ʐən˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "修建长城用了很多人力和很多年的时间。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个工程需要很多人力和钱。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前没有机器，只能用人力。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司缺少人力，工作做不完。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬这些大石头要花很多人力。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在机器代替了很多人力。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用人力把船拉上了岸。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是用人力一点一点修成的。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修路既花钱，又花人力。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农忙的时候，村里的人力不够。", "target_word": "人力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人力资源", "label": "复合"}, {"form": "人力车", "label": "复合"}], "register": "中性", "sense_fingerprint": "做工作所需要的人的劳动力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74be4108-6649-40ac-88e8-98d0ee81051b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39901, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人力", "is_correct": true, "explanation": "人力，指人的劳力，即人的体力或劳动力，是正确答案。"}, {"text": "人迹", "is_correct": false, "explanation": "人迹（rén jì）与人力的声母不同（j 与 l），声调相同，意思是人走过的痕迹。"}, {"text": "人气", "is_correct": false, "explanation": "人气（rén qì）与人力的第二个音节声母不同（q 与 l），意思是受欢迎的程度。"}, {"text": "神力", "is_correct": false, "explanation": "神力（shén lì）与人力的第一个音节声母不同（sh 与 r），意思是神奇的力量。"}], "explanations": {"人力": "人力，指人的劳力，即人的体力或劳动力，是正确答案。", "人迹": "人迹（rén jì）与人力的声母不同（j 与 l），声调相同，意思是人走过的痕迹。", "人气": "人气（rén qì）与人力的第二个音节声母不同（q 与 l），意思是受欢迎的程度。", "神力": "神力（shén lì）与人力的第一个音节声母不同（sh 与 r），意思是神奇的力量。"}, "sentence_index": null, "correct_answer": "人力"}, "level_3": {"options": [{"text": "人力", "is_correct": true, "explanation": "人力：指人的劳动力，这里指修长城所需的人工劳动。"}, {"text": "舞蹈", "is_correct": false, "explanation": "舞蹈与修建无关，不能说“用了很多舞蹈和很多年的时间”。"}, {"text": "水力", "is_correct": false, "explanation": "语义：修长城靠的是人的劳动，不是水力，“水力”与句中的劳动不符。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“用”后面要接劳动资源，不能说“用了很多人数”。"}], "explanations": {"人力": "人力：指人的劳动力，这里指修长城所需的人工劳动。", "舞蹈": "舞蹈与修建无关，不能说“用了很多舞蹈和很多年的时间”。", "水力": "语义：修长城靠的是人的劳动，不是水力，“水力”与句中的劳动不符。", "人数": "搭配：“用”后面要接劳动资源，不能说“用了很多人数”。"}, "sentence_index": 0, "correct_answer": "人力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题很难，他靠人力想了半天。", "explanation": "这里应该用〈脑力〉。人力指人的劳力或体力，思考问题靠的是脑力，不能说“靠人力想”。"}, {"text": "他的人力很好，远处的字一眼就看清了。", "explanation": "这里应该用〈眼力〉。人力指人的劳力或体力，看清远处的东西靠的是眼力。"}, {"text": "他的人力很强，什么难题都能解决。", "explanation": "这里应该用〈能力〉。人力指劳动力，不指解决问题的本领，说人的本事要用“能力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人力", "is_correct": true, "explanation": "人力：指人的劳动力，这里指用人的劳动拉船。"}, {"text": "脑力", "is_correct": false, "explanation": "语义：拉船要靠身体的力量，不能靠脑力。"}, {"text": "精神", "is_correct": false, "explanation": "语义：“精神”不能把船拉上岸，与拉船的动作不符。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“用”后接的是手段，不能说“用时间把船拉上了岸”。"}], "explanations": {"人力": "人力：指人的劳动力，这里指用人的劳动拉船。", "脑力": "语义：拉船要靠身体的力量，不能靠脑力。", "精神": "语义：“精神”不能把船拉上岸，与拉船的动作不符。", "时间": "搭配：“用”后接的是手段，不能说“用时间把船拉上了岸”。"}, "sentence_index": 6, "correct_answer": "人力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆卡车的人力很大，拉得动很重的货。", "explanation": "这里应该用〈马力〉。马力指发动机的功率，人力指人的劳力，不能用来说车的动力大小。"}, {"text": "这个孩子的人力很高，学什么都快。", "explanation": "这里应该用〈智力〉。人力指劳动力，不指思维能力，不能用来形容人的聪明程度。"}, {"text": "这辆摩托车的人力很大，一下子就冲上了山坡。", "explanation": "这里应该用〈动力〉。动力指机器的驱动能量，人力指人的劳力，不能用来说摩托车的动力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥需要一个人力，还要很多钱。", "corrected_sentence": "这座桥需要不少人力，还要很多钱。", "error_description": "量词错误：“人力”是不可数名词，不能用量词“个”计量，应把“一个”改为“不少”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工地上调来了不少人力们，很快就把路修好了。", "corrected_sentence": "工地上调来了不少人力，很快就把路修好了。", "error_description": "词缀错误：“人力”是不可数名词，不能加后缀“们”表示复数，应删去“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
