INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "是一种很大的龙，常常出现在神话故事里。", "primary_collocate": null, "pronunciation": "jù lóng", "ipa": "tɕy˥˩ lʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "故事里有一条巨龙，住在山洞里。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇士走进山洞，看见了一条巨龙。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巨龙从天上飞下来了。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢听巨龙和勇士的故事。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里的巨龙会喷火。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巨龙守着一大堆金子。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里画着一条绿色的巨龙。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王请勇士去打巨龙。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巨龙睡了一千年。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩梦见自己骑着巨龙飞上了天。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巨龍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "神话故事里的大龙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74be4108-6649-40ac-88e8-98d0ee81051b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巨龙", "is_correct": true, "explanation": "巨龙：传说中的大龙，住在山洞里，这里指故事中的生物。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是生物，不会“住在山洞里”，与句意不符。"}, {"text": "铁路", "is_correct": false, "explanation": "语义：铁路是人修的交通线，不会住在山洞里，与句意不符。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子是物品，不会住在山洞里，与故事的情节不符。"}], "explanations": {"巨龙": "巨龙：传说中的大龙，住在山洞里，这里指故事中的生物。", "河流": "语义：河流不是生物，不会“住在山洞里”，与句意不符。", "铁路": "语义：铁路是人修的交通线，不会住在山洞里，与句意不符。", "绳子": "语义：绳子是物品，不会住在山洞里，与故事的情节不符。"}, "sentence_index": 0, "correct_answer": "巨龙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "动物园里有一条巨龙，很凶，游客都不敢靠近。", "explanation": "这里应该用〈鳄鱼〉。巨龙是神话中的生物，动物园里养的是现实中的动物，不能说“巨龙”。"}, {"text": "生物学家在森林里发现了一种巨龙，它以树叶为食。", "explanation": "这里把“巨龙”当成现实中的动物，巨龙只指神话中的生物，应换成具体的动物名称。"}, {"text": "非洲草原上生活着一条巨龙，常以羚羊为食。", "explanation": "这里把“巨龙”当成现实中的动物，巨龙只指神话中的生物，草原上的动物应说〈狮子〉之类的具体名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巨龙", "is_correct": true, "explanation": "巨龙：传说中的大龙，这里指书里画的绿色的龙。"}, {"text": "消息", "is_correct": false, "explanation": "语义：消息是信息，不是能画在书里的东西，与“画着”不符。"}, {"text": "规定", "is_correct": false, "explanation": "搭配：“画”的对象要是具体事物，不能说“画着一条规定”。"}, {"text": "建议", "is_correct": false, "explanation": "语义：建议是言语，不是可以画出来的事物，与句意不符。"}], "explanations": {"巨龙": "巨龙：传说中的大龙，这里指书里画的绿色的龙。", "消息": "语义：消息是信息，不是能画在书里的东西，与“画着”不符。", "规定": "搭配：“画”的对象要是具体事物，不能说“画着一条规定”。", "建议": "语义：建议是言语，不是可以画出来的事物，与句意不符。"}, "sentence_index": 6, "correct_answer": "巨龙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条巨龙生活在热带雨林里，常常捕食小鹿。", "explanation": "这里应该用〈蟒蛇〉。巨龙是神话中的生物，不指现实中生活在雨林里的动物。"}, {"text": "科学家在海底发现了一条活着的巨龙。", "explanation": "这里把“巨龙”当成现实中的动物，巨龙只指神话中的生物，不能说发现了活着的巨龙。"}, {"text": "我在宠物店买了一条小巨龙，每天给它喂菜叶。", "explanation": "这里把“巨龙”当成现实中能买到的宠物。巨龙只是神话中的生物，宠物店里买不到，应换成〈乌龟〉之类的真实动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "故事的开头，山里住着一个巨龙。", "corrected_sentence": "故事的开头，山里住着一条巨龙。", "error_description": "量词错误：“巨龙”要用量词“条”计量，用通用量词“个”不对，应把“个”改为“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "勇士骑上了一个巨龙，飞过了那座高山。", "corrected_sentence": "勇士骑上了一条巨龙，飞过了那座高山。", "error_description": "量词错误：“巨龙”要用量词“条”计量，用“个”不对，应把“一个”改为“一条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669fa907-e516-4ce8-8679-9785b5cae3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
